QDB_COLORS = {"pos": (0.25, 0.8, 0.45), "buy": (0.898, 0.722, 0.259), "muted": (0.55, 0.51, 0.45)}

QDB_MOCK_LUA = r'''
-- LibQuestieDB as QuestieDB 1.1.2 shows it to other addons (src/api.lua,
-- contract 4): Quest and Item with Get, GetAll, GetAllIds and Exists over the
-- rows a scenario gives; number fields read 0 and objectives {} for a known
-- id, table fields come back as fresh copies, an unknown id reads nil.
local M = MOCK
local data = ...
M.profileMs = M.profileMs or 0
-- reads: every Get; objectives: how many quests' objectives were read (the
-- index reads each quest's once); fail: every read errors; cost: fake
-- milliseconds a read takes (for debugprofilestop).
M.qdb = { reads = 0, objectives = 0, fail = false, cost = nil, contractFails = data.contractFails == true }
local function copy(v)
  if type(v) ~= "table" then return v end
  local o = {}
  for k, x in pairs(v) do o[k] = copy(x) end
  return o
end
local QUEST_NUM = { requiredLevel = 1, questLevel = 1, requiredRaces = 1, requiredClasses = 1, sourceItemId = 1,
  zoneOrSort = 1, nextQuestInChain = 1, questFlags = 1, specialFlags = 1, parentQuest = 1, breadcrumbForQuestId = 1,
  requiredSpell = 1, requiredSpecialization = 1, requiredMaxLevel = 1, availableUntilCompleted = 1,
  availableStartingWith = 1, disabledByQuest = 1 }
local QUEST_TABLES = { startedBy = 1, finishedBy = 1, objectivesText = 1, triggerEnd = 1, objectives = 1,
  preQuestGroup = 1, preQuestSingle = 1, childQuests = 1, inGroupWith = 1, exclusiveTo = 1, requiredSkill = 1,
  requiredMinRep = 1, requiredMaxRep = 1, requiredSourceItems = 1, reputationReward = 1, breadcrumbs = 1,
  extraObjectives = 1, requiredRanks = 1 }
local NEVER_NIL = { startedBy = 1, finishedBy = 1, objectives = 1 }
local ITEM_NUM = { startQuest = 1, flags = 1, foodType = 1, itemLevel = 1, requiredLevel = 1, ammoType = 1,
  class = 1, subClass = 1, teachesSpell = 1 }
local ITEM_TABLES = { npcDrops = 1, objectDrops = 1, itemDrops = 1, questRewards = 1, vendors = 1, relatedQuests = 1 }
local NPC_NUM = { minLevel = 1, maxLevel = 1, rank = 1, zoneID = 1, factionID = 1, npcFlags = 1 }
local NPC_TABLES = { spawns = 1, waypoints = 1, questStarts = 1, questEnds = 1 }
local NPC_STRINGS = { friendlyToFaction = 1, subName = 1 }
local OBJECT_NUM = { zoneID = 1, factionID = 1 }
local OBJECT_TABLES = { questStarts = 1, questEnds = 1, spawns = 1, waypoints = 1 }
local function entity(rows, nums, tables, neverNil, kind, strings)
  local e, ids, map = {}, {}, {}
  for id in pairs(rows) do ids[#ids + 1] = id end
  table.sort(ids)
  for _, id in ipairs(ids) do map[id] = true end
  local function get(id, key)
    local st = M.qdb
    if st.fail then error("QuestieDB read failed") end
    st.reads = st.reads + 1
    if st.cost then M.profileMs = M.profileMs + st.cost end
    if type(key) ~= "string" or not (key == "name" or nums[key] or tables[key] or (strings and strings[key])) then return nil end
    local r = rows[id]
    if not r then return nil end
    if kind == "Quest" and key == "objectives" then st.objectives = st.objectives + 1 end
    local v = r[key]
    if v == nil then
      if nums[key] then return 0 end
      if neverNil[key] then return {} end
      return nil
    end
    return copy(v)
  end
  e.Get = get
  function e.GetAll(id, keys)
    if not map[id] then return nil end
    local out = { n = #keys }
    for i, k in ipairs(keys) do out[i] = get(id, k) end
    return out
  end
  function e.GetAllIds(hashmap) if hashmap == true then return map end return ids end
  function e.Exists(id) return map[id] == true end
  return e
end
local L = {
  Quest = entity(data.quests, QUEST_NUM, QUEST_TABLES, NEVER_NIL, "Quest"),
  Item = entity(data.items, ITEM_NUM, ITEM_TABLES, {}, "Item"),
  Npc = entity(data.npcs, NPC_NUM, NPC_TABLES, {}, "Npc", NPC_STRINGS),
  Object = entity(data.objects, OBJECT_NUM, OBJECT_TABLES, {}, "Object"),
  contractVersion = 4, minSupportedContract = 1, addonName = "QuestieDB", readMode = "baked",
  Enum = { raceMaskById = data.races, factionRaceMasks = { Alliance = data.ally, Horde = data.horde } },
}
function L.RequireContract(required)
  if M.qdb.contractFails then return false, "QuestieDB contract mismatch: this consumer needs version 4" end
  if type(required) == "number" and required >= L.minSupportedContract and required <= L.contractVersion then return true end
  return false, "QuestieDB contract mismatch"
end
if data.noQuestList then L.Quest.GetAllIds = nil end
if data.noNpcs then L.Npc, L.Object = nil, nil end
LibQuestieDB, QuestDB, ItemDB = L, L.Quest, L.Item
M.loaded.QuestieDB = true
M.addonMeta.QuestieDB = { Version = data.version, ["X-BUILD-COMMIT"] = data.commit, ["X-Contract-Version"] = "4" }
'''


def install_questie(w, version="1.1.2", commit=QDB_COMMIT, filler=0, contract_fails=False, no_quest_list=False,
                    no_npcs=False, extra=None):
    """QuestieDB loaded (as LibQuestieDB), with QDB_QUESTS, QDB_ITEMS, QDB_NPCS and
    QDB_OBJECTS plus `filler` more quests (every 7th asks for one of 50 made-up
    items) and the `extra` quest rows. no_npcs: a QuestieDB with no NPC or object reads."""
    quests = dict(QDB_QUESTS)
    quests.update(extra or {})
    for k in range(filler):
        row = {"name": "Filler Quest %d" % (k + 1), "requiredRaces": QDB_ALLY if k % 2 else 0}
        if k % 7 == 0:
            row["objectives"] = qobj(880000 + k % 50)
        quests[100001 + k] = row
    data = {"quests": quests, "items": QDB_ITEMS, "npcs": QDB_NPCS, "objects": QDB_OBJECTS, "version": version,
            "commit": commit, "races": QDB_RACES, "ally": QDB_ALLY, "horde": QDB_HORDE, "contractFails": contract_fails,
            "noQuestList": no_quest_list, "noNpcs": no_npcs}
    w.loader(QDB_MOCK_LUA, "@MOCK/QuestieDB.lua", w.to_lua(data))
    return quests


def quest_bags(w, log=None, done=()):
    for bag, slot, iid, count, name, fields in QUEST_BAG:
        bag_add_item(w, iid, name, 1, 0, **fields)
        bag_put(w, bag, slot, iid, count)
    bag_quests(w, LOG_FIND_GEMS if log is None else log)
    for q in done:
        w.M.questDone[q] = True


def lua_to_py(v):
    """A Lua table as Python dicts (whole-number keys as int)."""
    if lua51.lua_type(v) != "table":
        return v
    out = {}
    for k, x in v.items():
        if isinstance(k, float) and k == int(k):
            k = int(k)
        out[k] = lua_to_py(x)
    return out


# --- an independent model of Bags.lua's QuestieDB verdicts ---------------------------
QDB_RANK = {"use": 1, "nextq": 2, "start": 3, "give": 4}
QDB_REPEATABLE = {12840, 12841, 12843, 12844, 22523, 22524, 22525, 22526, 22527, 22528, 22529, 21377, 21383, 20404,
                  20513, 20514, 20515} | set(range(19698, 19716))


def ref_quest_index(quests):
    """item -> quest * 4 + role (0 asks for it, 1 gives it): one code, or a list in quest order."""
    idx = {}

    def add(it, code):
        lst = idx.setdefault(it, [])
        if code not in lst:
            lst.append(code)
    for q in sorted(quests):
        row = quests[q]
        for o in (row.get("objectives") or {}).get(3, []):
            add(o[0], q * 4)
        for it in row.get("requiredSourceItems", []):
            add(it, q * 4)
        if row.get("sourceItemId"):
            add(row["sourceItemId"], q * 4 + 1)
    return {k: (v[0] if len(v) == 1 else v) for k, v in idx.items()}


class QV(tuple):
    """A verdict (kind, quest name, repeatable); at: who takes a turn-in in (not compared)."""
    at = None


def qv(kind, name, rep, at=None):
    v = QV((kind, name, rep))
    v.at = at
    return v


QDB_HORDE_RACES = (2, 5, 6, 8, 96)


def ref_hand_in(quests, q, race):
    """Who takes quest q in: its first NPC friendly to the player's side, else its
    first NPC, else its first object (QDB_NPCS / QDB_OBJECTS names); None without."""
    side = "H" if race in QDB_HORDE_RACES else "A"
    fin = quests[q].get("finishedBy") or {}
    npcs = [QDB_NPCS[n]["name"] for n in fin.get(1, []) if n in QDB_NPCS]
    for n in fin.get(1, []):
        if n in QDB_NPCS and side in (QDB_NPCS[n].get("friendlyToFaction") or ""):
            return QDB_NPCS[n]["name"]
    if npcs:
        return npcs[0]
    objs = [QDB_OBJECTS[o]["name"] for o in fin.get(2, []) if o in QDB_OBJECTS]
    return objs[0] if objs else None


def ref_quest_verdict(quests, iid, in_log, done, race=1, cls=1, log_known=True, start_q=None, usable=True,
                      hidden=None, named_by=None, titles=None, level=60, npcs=True, skills=None):
    """(kind, quest name, repeatable) or None, as Bags.lua QuestieVerdict decides it.
    kind: keep, starts, done, open, or maybe-next / maybe-hidden (not sure);
    keep-turnin / keep-later: kept for a quest you can still do that asks for it as
    an objective (at: who takes it in) / needs it, not in your log; done-shut: its
    quests are shut for you (none done); open-fresh: only for quests that give it to
    you when you take them, none done. A quest is shut by one done that excludes it,
    the one it is available until, the one it is a breadcrumb for, or a top level
    under `level`.
    in_log: the quests known to be in the log; log_known: whether every other
    quest is known not to be (False: closed headers and no IsOnQuest).
    usable: the item has a Use effect (a tool): the quest after the one that
    gave it is the one it is for. Any item a quest gave you is kept while a
    quest after its giver is in the log (the ones between done; for a tool,
    up to a quest that starts at an object the one before is handed in at);
    a note you only read (usable False) is maybe needed while the quest
    right after its giver is not done.
    hidden: closed headers hide quests (default: not log_known), so nothing
    is done or not started (both are not sure). skills: the skill line ids
    the game lists (None: it cannot be told). done-pre / done-skill: the
    quest that asks for it (none gives it) is one you can never take: every
    quest of its preQuestSingle, or one of its preQuestGroup (unless that one
    has exclusiveTo quests; a negative id has none), is not for you and not
    done, or it needs a profession you have not learned. named_by: the title of a
    quest in the log that names the item: it keeps it, whatever QuestieDB
    says (also when no quest QuestieDB knows uses it for you). A next quest
    QuestieDB has no row for counts by its id (titles: its title in the log)."""
    if hidden is None:
        hidden = not log_known
    idx = ref_quest_index(quests)
    item = QDB_ITEMS.get(iid, {})
    starts = [q for q in (item.get("startQuest", 0), start_q) if q]
    R, order, given_for, givers = {}, [], {}, []
    gives = {q for q in quests if quests[q].get("sourceItemId") == iid and q not in starts}

    def mine(row):
        races, classes = row.get("requiredRaces", 0), row.get("requiredClasses", 0)
        rb, cb = QDB_RACES[race], 2 ** (cls - 1)
        return (not races or (races // rb) % 2 == 1) and (not classes or (classes // cb) % 2 == 1)

    def add(q, role):
        if not q or q <= 0:
            return False
        if q in R:
            return True
        row = quests.get(q)
        if not row or not mine(row):
            return False
        R[q] = role
        order.append(q)
        return True
    # The quest it starts first: QuestieDB also lists a starter as the item its
    # quest gives, and it stays the quest it starts (no quest after it counts).
    for s in starts:
        add(s, "start")
    e = idx.get(iid)
    for c in (e if isinstance(e, list) else ([] if e is None else [e])):
        q, role = c // 4, c % 4
        if role == 0:
            add(q, "use")
        elif role == 1 and q not in starts:
            givers.append(q)
            if add(q, "give") and usable:
                n = quests[q].get("nextQuestInChain", 0)
                if add(n, "nextq"):
                    given_for.setdefault(n, q)
    if not order:
        return ("keep", named_by, False) if named_by else None

    def pick(pred):
        best = None
        for q in order:
            if pred(q) and (best is None or QDB_RANK[R[q]] < QDB_RANK[R[best]]):
                best = q
        return best

    def closed(q):
        row = quests[q]
        crumb, top = row.get("breadcrumbForQuestId", 0), row.get("requiredMaxLevel", 0)
        return (q in done or row.get("availableUntilCompleted") in done
                or any(x in done for x in row.get("exclusiveTo", []))
                or bool(crumb and crumb in done) or bool(top and level > top))

    def not_mine(p, ex):
        if p < 0:
            p, ex = -p, False
        row = quests.get(p)
        if not row or p in done or mine(row):
            return False
        return not (ex and row.get("exclusiveTo"))

    def never(q):
        row = quests[q]
        one = [p for p in row.get("preQuestSingle", []) if p]
        if one and all(not_mine(p, False) for p in one):
            return "pre"
        if any(not_mine(p, True) for p in row.get("preQuestGroup", []) if p):
            return "pre"
        sk = row.get("requiredSkill")
        if sk and sk[0] > 0 and skills is not None and sk[0] not in skills:
            return "skill"
        return None

    def logged(q):
        return True if q in in_log else (False if log_known else None)
    def name(q):
        return quests[q]["name"] if q in quests else (titles or {}).get(q)

    def final(v):
        if named_by:
            return ("keep", named_by, False)
        if v[0].split("-")[0] in ("done", "open") and hidden:
            return ("maybe-hidden", v[1], False)
        return v

    def chain(g, tool):
        """The quests after g (a done giver), past done ones, at most 6; a tool's
        chain ends where a quest starts at an object the one before ends at."""
        q, seen = g, {g}
        for step in range(1, 7):
            n = quests[q].get("nextQuestInChain", 0)
            if not n or n <= 0 or n in seen:
                return None, None
            seen.add(n)
            row = quests.get(n)
            if not row:
                s = logged(n)
                if s is True:
                    return "keep", n
                if n in done:
                    return None, None
                if s is None:
                    return "hidden", n
                return ("maybe", n) if step == 1 else (None, None)
            if not mine(row):
                return None, None
            if tool and step > 1 and (set(quests[q].get("finishedBy", {}).get(2, []))
                                      & set(row.get("startedBy", {}).get(2, []))):
                return None, None
            s = logged(n)
            if s is True:
                return "keep", n
            if not closed(n):
                if s is None:
                    return "hidden", n
                return ("maybe", n) if step == 1 else (None, None)
            q = n
        return None, None
    q = pick(lambda x: x in in_log)
    if q:
        return ("keep", name(q), False)
    after = None
    for g in givers:
        if g in R and g in done:
            k, n = chain(g, usable)
            if k == "keep":
                return ("keep", name(n), False)
            if k and after is None:
                after = ("maybe-hidden" if k == "hidden" else "maybe-next", name(n), False)
    q = pick(lambda x: R[x] == "start" and not closed(x))
    if q:
        return ("starts", name(q), False)
    q = pick(lambda x: quests[x].get("specialFlags", 0) % 2 == 1)
    if q or iid in QDB_REPEATABLE:
        return ("keep", name(q or pick(lambda x: True)), True)
    q = pick(lambda x: not closed(x))
    if not q:
        # The quest it was given for is handed in at an object where the next
        # quest starts: kept until that one is taken.
        wait = None
        for x in order:
            n = quests[x].get("nextQuestInChain", 0)
            row = quests.get(n)
            if x not in given_for or x not in done or not row or not mine(row) or closed(n):
                continue
            if set(quests[x].get("finishedBy", {}).get(2, [])) & set(row.get("startedBy", {}).get(2, [])):
                s = logged(n)
                if s is False:
                    return ("keep", name(n), False)
                if s is None and wait is None:
                    wait = ("maybe-hidden", name(n), False)
        d = pick(lambda x: x in done)
        return final(after or wait or (("done" if d else "done-shut"), name(d or pick(lambda x: True)), False))
    # Halfway along a chain: a quest done gave it or rewarded it, or one that
    # needs it comes after a quest in the log.
    got = any(g in done for g in givers) or any(r in done for r in item.get("questRewards", []))

    def after_log(x):
        pre = list(quests[x].get("preQuestSingle", [])) + [abs(p) for p in quests[x].get("preQuestGroup", [])]
        return any(p in in_log for p in pre)
    q2 = pick(lambda x: not closed(x) and (got or after_log(x)))
    if q2:
        return ("keep", name(q2), False)
    # A quest you can still do asks for it (and does not give it to you): kept,
    # whatever the log shows.
    t = pick(lambda x: R[x] == "use" and not closed(x) and x not in gives and not never(x))
    if t:
        if iid not in quests[t].get("requiredSourceItems", []):
            return qv("keep-turnin", name(t), False, at=ref_hand_in(quests, t, race) if npcs else None)
        return ("keep-later", name(t), False)
    g = pick(lambda x: not closed(x) and (R[x] == "give" or x in gives))
    nv = None if g else never(q)
    if nv:
        return final(("done-" + nv, name(q), False))
    return final(("open-fresh" if g else "open", name(g or q), False))


def quest_line_text(v):
    """The tooltip line and its colour key for a model verdict."""
    kind, n, rep = v
    if kind == "done":
        return "Can drop: done with %s" % n, "pos"
    if kind == "done-shut":
        return "Can drop: %s is no longer open to you" % n, "pos"
    if kind == "done-pre":
        return "Can drop: %s is not open to you" % n, "pos"
    if kind == "done-skill":
        return "Can drop: %s needs a profession you do not have" % n, "pos"
    if kind == "open":
        return "Only for %s, not in your quest log" % n, "muted"
    if kind == "open-fresh":
        return "Can drop: taking %s gives you a new one" % n, "muted"
    if kind == "keep-turnin":
        at = getattr(v, "at", None)
        return "Keep: turn in for %s%s" % (n, (" at " + at) if at else ""), "buy"
    if kind == "keep-later":
        return "Keep: needed for %s" % n, "buy"
    if kind == "maybe-hidden":
        return "Not sure: some quest log headers are closed", "muted"
    if kind == "maybe-next":
        return "May be needed for %s" % (n or "the next quest"), "muted"
    if kind == "maybe-reading":
        return "Not sure yet: still reading your quest log", "muted"
    if kind == "starts":
        return "Starts %s" % n, "buy"
    if rep:
        return "Keep: for %s (repeatable)" % n, "buy"
    return "Keep: needed for %s" % n, "buy"


def lua_verdict(w, iid):
    """Bags.lua's verdict as (kind, quest name, repeatable); a not sure one is maybe-next or maybe-hidden,
    one kept for a quest not taken keep-turnin (at: who takes it in) or keep-later, a done one whose
    quests are shut for you done-shut (done-pre / done-skill: one you can never take), an open one
    whose quest gives a new one open-fresh."""
    v = w.ns.QuestItemVerdict(iid)
    if v is None:
        return None
    kind = v.kind
    if kind == "maybe":
        kind = "maybe-" + str(v.why)
    elif kind == "keep" and v.later:
        kind = "keep-turnin" if v.turnin else "keep-later"
    elif kind == "done" and v.shut:
        kind = ("done-" + str(v.never)) if v.never else "done-shut"
    elif kind == "open" and v.fresh:
        kind = "open-fresh"
    return qv(kind, v.name, bool(v.rep), at=v.at)


def quest_tip(w, bag, slot):
    """Our lines on the bag slot's item tooltip: (text, colour) each."""
    tt = w.g.GameTooltip
    tt.SetOwner(tt, w.g.UIParent, "ANCHOR_RIGHT")
    tt.SetBagItem(tt, bag, slot)
    al = w.M.addonLines(tt)
    out = []
    for i in range(1, len(al) + 1):
        ln = al[i]
        c = None if ln.lr is None else (round(ln.lr, 3), round(ln.lg, 3), round(ln.lb, 3))
        out.append((ln.left, c))
    tt.Hide(tt)
    return out


def quest_rows(BP):
    """The cleanup panel's shown OLD QUEST ITEMS rows: (item, right text, right colour)."""
    out = []
    for i in range(1, len(BP.rows) + 1):
        r = BP.rows[i]
        if r.IsShown(r) and r.kind == "quest":
            c = r.right._textColor
            out.append((r.entry.id, r.right._text, (round(c[1], 3), round(c[2], 3), round(c[3], 3))))
    return out


NO_LISTINGS = ("Goblin Ledger: no recent listings", QDB_COLORS["muted"])


def plain_tip(fields):
    """Our lines on a quest item's tooltip without QuestieDB: none, or for one
    that is not bound (it might go on the auction house) the no-listings line."""
    return [] if fields.get("bind") in (1, 4) else [NO_LISTINGS]


def quest_checks(sc, w, quests, in_log, done, label, race=1, cls=1, log_known=True, ids=None, bag_list=None,
                 hidden=None, named=None, titles=None, level=60, npcs=True, skills=None):
    """Every bag item's verdict, tooltip line and colour against the model.
    named: item -> the title of the quest in the log that names it. titles:
    quest -> its title in the log, for a quest QuestieDB has no row for."""
    for bag, slot, iid, count, name, fields in (bag_list or QUEST_BAG):
        if ids and iid not in ids:
            continue
        want = ref_quest_verdict(quests, iid, in_log, done, race, cls, log_known, fields.get("startsQuest"),
                                 usable="useSpell" in fields, hidden=hidden, named_by=(named or {}).get(iid),
                                 titles=titles, level=level, npcs=npcs, skills=skills)
        sc.eq(lua_verdict(w, iid), want, "%s: %s verdict" % (label, name))
        tip = quest_tip(w, bag, slot)
        if want is None:
            sc.eq(tip, plain_tip(fields), "%s: %s tooltip has no quest line" % (label, name))
        else:
            text, key = quest_line_text(want)
            sc.eq(tip, plain_tip(fields) + [(text, QDB_COLORS[key])], "%s: %s tooltip, one quest line last" % (label, name))


def sc_bag_questie(sc, ref, items):
    """With QuestieDB: a quest item's tooltip says whether it can go (keep,
    starts, done, not started), the cleanup panel lists the done and not
    started ones with the quest in the row tooltip, /gl bags says the same,
    and the phial the player asked about says done once its quests are."""
    w = World(ref, items)
    M, ns, g = w.M, w.ns, w.g
    quests = install_questie(w)
    quest_bags(w, LOG_FIND_GEMS, done=(2198, 2199, 2200))
    QI = ns.QuestIndex
    sc.eq(QI.state, "idle", "questie: the index waits a few seconds after login")
    # First need: the phial's tooltip. Nothing yet, the index starts.
    sc.eq(quest_tip(w, 0, 1), [], "questie: no quest line while the index is being made")
    sc.eq(QI.state, "building", "questie: a quest item's tooltip starts the index")
    w.settle(0.5)
    sc.eq(QI.state, "ready", "questie: the index is ready a few frames later")
    sc.eq(QI.size, len(ref_quest_index(quests)), "questie: every item a quest asks for or gives is indexed")
    # On Find the Gems (2200 done): the phial is needed.
    in_log, done = {2201}, {2198, 2199, 2200}
    sc.eq(lua_verdict(w, 7667), ("keep", "Find the Gems", False), "questie: phial while on Find the Gems: keep")
    sc.eq(lua_verdict(w, 7846), ("keep-turnin", "Badlands Reagent Run", False),
          "questie: Crag Coyote Fang, Badlands Reagent Run not in the log: kept for it (you can still do it)")
    sc.eq(lua_verdict(w, 900501), ("starts", "A Sealed Letter", False), "questie: the letter starts a quest you have not done")
    sc.eq(lua_verdict(w, 12840), ("keep", "Minion's Scourgestones", True), "questie: a repeatable turn-in is kept")
    sc.eq(lua_verdict(w, 900502), None, "questie: an item QuestieDB does not know has no verdict")
    quest_checks(sc, w, quests, in_log, done, "on Find the Gems")
    tip = quest_tip(w, 0, 1)
    sc.eq(tip, [("Keep: needed for Find the Gems", QDB_COLORS["buy"])], "questie: phial tooltip, gold keep line")
    sc.eq(quest_tip(w, 0, 2), [("Keep: turn in for Badlands Reagent Run at Ghak Healtouch", QDB_COLORS["buy"])],
          "questie: fang tooltip, gold turn in line naming who takes it")
    # The panel: items a quest you can still do asks for are kept (not listed); the one
    # QuestieDB does not know is listed by the quest log's words.
    M.OpenBags(1)
    w.settle(0.2)
    BP = ns.BagPanel
    M.click(BP.tab)
    w.settle(0.2)
    mu, pos = QDB_COLORS["muted"], QDB_COLORS["pos"]
    sc.eq(quest_rows(BP), [(900502, "not needed", mu)],
          "questie panel: the items open quests ask for are kept; only the one QuestieDB does not know is listed")
    sc.check(bag_row_for(BP, 7846) is None, "questie panel: the fang has no row")
    out = [plain(x) for x in w.slash("/gl bags")]
    sc.check(any(t.endswith("old quest items: [Gnarled Root] x2 (no quest needs it)") for t in out),
             "questie /gl bags: quest line (%s)" % out)
    sc.check(not any("still reading" in t for t in out), "questie /gl bags: nothing about reading once ready")

    # Find the Gems done, Restoring the Necklace (it mentions Talvash) in the log: the phial can go.
    bag_quests(w, LOG_NECKLACE)
    M.questDone[2201] = True
    M.fire("QUEST_LOG_UPDATE")
    w.settle(0.5)
    in_log, done = {2204}, {2198, 2199, 2200, 2201}
    sc.eq(lua_verdict(w, 7667), ("done", "Find the Gems", False), "questie: phial after Find the Gems, Restoring the Necklace in the log: done")
    sc.eq(quest_tip(w, 0, 1), [("Can drop: done with Find the Gems", QDB_COLORS["pos"])], "questie: phial tooltip, green done line")
    quest_checks(sc, w, quests, in_log, done, "after Find the Gems")
    rows = quest_rows(BP)
    sc.eq(rows[:1], [(7667, "done", pos)], "questie panel: the phial is listed first, done in green")
    row = bag_row_for(BP, 7667)
    if sc.check(row is not None, "questie panel: the phial has a row"):
        M.enter(row)
        lines = [plain(l) for l, _ in w.all_lines(g.GameTooltip)]
        sc.check("Can drop: done with Find the Gems." in lines, "questie panel: the phial's row tooltip (%s)" % lines)
        sc.check(not any("check your quest log" in l for l in lines), "questie panel: no unsure note for a QuestieDB verdict")
        M.leave(row)
        # The drop flow is as before for quest items: picked up, the game asks.
        n_pick = len(M.pickups)
        M.click(row, "LeftButton")
        C = g.ForeverAHBagConfirm
        sc.check(C is None or not C.IsShown(C), "questie panel: a quest item gets no drop box")
        sc.eq(len(M.pickups), n_pick + 1, "questie panel: a click picks the phial up")
        if len(M.pickups) > n_pick:
            p = M.pickups[len(M.pickups)]
            sc.eq((p[1], p[2]), (0, 1), "questie panel: the phial's slot")
        w.lua.execute("ClearCursor()")
        sc.eq(len(M.destroyed), 0, "questie panel: nothing destroyed")
    out = [plain(x) for x in w.slash("/gl bags")]
    sc.check(any("old quest items: [Talvash's Phial of Scrying] (done: Find the Gems), " in t for t in out),
             "questie /gl bags: the phial is done (%s)" % out)

    # The letter's quest taken, then done; the scourgestone's quest done; the
    # Alliance reagent run done (the Horde one does not count); one of the two
    # ogre quests done (the other is shut).
    M.quests[len(M.quests) + 1] = w.to_lua({"title": "A Sealed Letter", "questID": 950001, "objectives": []})
    M.questActive[950001] = True
    sc.eq(lua_verdict(w, 900501), ("keep", "A Sealed Letter", False), "questie: the letter while its quest is in the log: keep")
    M.quests[len(M.quests)] = None
    M.questActive[950001] = None
    for q in (950001, 950002, 2500, 950010, 950031):
        M.questDone[q] = True
    done = done | {950001, 950002, 2500, 950010, 950031}
    sc.eq(lua_verdict(w, 900501), ("done", "A Sealed Letter", False), "questie: the letter once its quest is done: done")
    sc.eq(lua_verdict(w, 12840), ("keep", "Minion's Scourgestones", True), "questie: a repeatable turn-in is never done")
    sc.eq(lua_verdict(w, 7846), ("done", "Badlands Reagent Run", False),
          "questie: fang with the Alliance reagent run done: done (the Horde one is not yours)")
    sc.eq(lua_verdict(w, 900503), ("done", "Ogre Toll", False), "questie: a quest shut by the one you did counts as done")
    sc.eq(lua_verdict(w, 900505), ("done-shut", "Old Debts", False),
          "questie: a quest only available until one you did counts as done (shut for you)")
    sc.eq(quest_tip(w, 0, 8), [("Can drop: Old Debts is no longer open to you", QDB_COLORS["pos"])],
          "questie: and its tooltip says it is shut, not done")
    quest_checks(sc, w, quests, in_log, done, "later")

    # Closed quest log headers and no IsOnQuest: done is not sure: a quest
    # under the closed header may name the item (your quest log beats
    # QuestieDB). Nor for the phial: whether Restoring the Necklace was taken
    # at the scrying bowl cannot be told. They say so (not sure) and are
    # listed as check log, none as done. Items a quest you can still do asks
    # for stay kept: the log cannot change that.
    M.questDone[2500] = None
    M.questDone[950010] = None
    done = done - {2500, 950010}
    bag_quests(w, [{"title": "Uldaman", "isHeader": True, "isCollapsed": True}])
    quest_checks(sc, w, quests, set(), done, "log headers closed", log_known=False)
    sc.eq(lua_verdict(w, 7667), ("maybe-hidden", "Restoring the Necklace", False),
          "questie: with a header closed the phial is not sure (Restoring the Necklace may be under it)")
    sc.eq(quest_tip(w, 0, 1), [("Not sure: some quest log headers are closed", mu)], "questie: and its tooltip says so")
    s = ns.BagScan()
    sc.eq([(s.quest[i].id, s.quest[i].why, s.quest[i].maybe) for i in range(1, len(s.quest) + 1)],
          [(900505, "maybe", "hidden"), (900501, "maybe", "hidden"), (7667, "maybe", "hidden")],
          "questie: with a header closed the ones that would be done are listed as not sure (by name), none as done; "
          "the ones open quests ask for stay kept")
    M.fire("QUEST_LOG_UPDATE")
    w.settle(0.5)
    sc.check(all(r[1] == "check log" for r in quest_rows(BP)) and len(quest_rows(BP)) == 3,
             "questie panel: with a header closed they say check log (%s)" % quest_rows(BP))
    # C_QuestLog.IsOnQuest knows every quest, closed headers or not; still,
    # the quests under a closed header cannot be read, so done stays not sure.
    w.lua.execute("MOCK.onQuest = {}; C_QuestLog.IsOnQuest = function(q) return MOCK.onQuest[q] == true end")
    quest_checks(sc, w, quests, set(), done, "IsOnQuest", hidden=True)
    sc.eq(lua_verdict(w, 7667), ("keep", "Restoring the Necklace", False),
          "questie: IsOnQuest says Restoring the Necklace is not taken: the phial still calls up the bowl it starts at")
    w.lua.execute("MOCK.onQuest[2500] = true; MOCK.onQuest[2204] = true")
    sc.eq(lua_verdict(w, 7846), ("keep", "Badlands Reagent Run", False), "questie: IsOnQuest finds a quest under a closed header")
    sc.eq(lua_verdict(w, 7667), ("maybe-hidden", "Find the Gems", False),
          "questie: IsOnQuest finds Restoring the Necklace, but a header is closed: the phial is not sure yet")
    # The header opened: Restoring the Necklace is read, the phial is done.
    bag_quests(w, LOG_NECKLACE)
    sc.eq(lua_verdict(w, 7667), ("done", "Find the Gems", False), "questie: the header opened: the phial is done")
    w.lua.execute("C_QuestLog.IsOnQuest = nil")
    n, _ = bagcheck(sc, w, "questie bagcheck")
    sc.check((n.get(8) or "").endswith(", quests from QuestieDB (%d items)" % len(ref_quest_index(quests))),
             "questie bagcheck: line 8 says the quest data is QuestieDB's (%s)" % n.get(8))
    w.settle(10.5)
    M.CloseBags()
    w.settle(0.2)
    sc.clean(w, "questie", ok_chat=BAGCHECK_LINES)

    # Horde (an Orc mage): the Alliance chain is not theirs, the Warrior quest neither.
    wh = World(ref, items, faction="Horde")
    wh.M.race = wh.to_lua(["Orc", "Orc", 2])
    wh.M["class"] = wh.to_lua(["Mage", "MAGE", 8])
    quests = install_questie(wh)
    quest_bags(wh, LOG_FIND_GEMS, done=(2198, 2199, 2200, 2500))
    wh.ns.BagScan()
    wh.settle(0.5)
    sc.eq(wh.ns.QuestIndex.state, "ready", "questie horde: the bag scan started the index")
    hdone = {2198, 2199, 2200, 2500}
    sc.eq(lua_verdict(wh, 7846), ("keep-turnin", "Badlands Reagent Run", False),
          "questie horde: fang with only the Alliance reagent run done: kept for their own")
    sc.eq(quest_tip(wh, 0, 2), [("Keep: turn in for Badlands Reagent Run at Jarkal Mossmeld", QDB_COLORS["buy"])],
          "questie horde: the Horde run is handed in at Jarkal Mossmeld")
    sc.eq(lua_verdict(wh, 7667), None, "questie horde: the Alliance phial chain is not theirs (quest log verdict)")
    sc.eq(lua_verdict(wh, 900504), None, "questie horde: a Warrior quest is not a mage's")
    quest_checks(sc, wh, quests, {2201}, hdone, "horde mage", race=2, cls=8)
    wh.M.questDone[2258] = True
    quest_checks(sc, wh, quests, {2201}, hdone | {2258}, "horde mage, their run done", race=2, cls=8)
    sc.eq(lua_verdict(wh, 7846), ("done", "Badlands Reagent Run", False), "questie horde: fang once their own run is done")
    sc.clean(wh, "questie horde")

    # The legacy client's tooltip script gets the line too.
    wl = World(ref, items, client="legacy")
    quests = install_questie(wl)
    quest_bags(wl, LOG_NECKLACE, done=(2198, 2199, 2200, 2201))
    wl.ns.BagScan()
    wl.settle(0.5)
    sc.eq(quest_tip(wl, 0, 1), [("Can drop: done with Find the Gems", QDB_COLORS["pos"])], "questie legacy: phial tooltip")
    sc.eq(quest_tip(wl, 0, 5), [NO_LISTINGS], "questie legacy: no quest line for an item QuestieDB does not know")
    # /gl tooltip off: no quest line either.
    wl.slash("/gl tooltip")
    sc.eq(quest_tip(wl, 0, 1), [], "questie: /gl tooltip off hides the quest line too")
    sc.clean(wl, "questie legacy")


# Along quest chains (bag-questie-chain): the necklace that starts its quest,
# the phial, and a lamp for a quest that comes after another; the Symbol of
# Life goes in an Undead paladin's bags.
CHAIN_BAG = [
    (0, 1, 7666, 1, "Shattered Necklace", {"classID": 12, "bind": 4, "maxStack": 1, "startsQuest": 2198}),
    (0, 2, 7667, 1, "Talvash's Phial of Scrying", {"classID": 12, "bind": 4, "maxStack": 1, "useSpell": "Create Scrying Bowl"}),
    (0, 3, 900506, 1, "Miner's Lamp", {"classID": 12, "bind": 4, "maxStack": 1}),
]
SYMBOL_BAG = [(0, 1, 6866, 1, "Symbol of Life", {"classID": 12, "bind": 4, "maxStack": 1})]
LOG_ELSEWHERE = [
    {"title": "Elwynn Forest", "isHeader": True},
    {"title": "A Threat Within", "questID": 783, "objectives": ["Speak with Marshal McBride: 0/1"]},
]


def qlog(quest_id, title):
    """A quest log with one quest (and one objective) under a header."""
    return [{"title": "Quests", "isHeader": True}, {"title": title, "questID": quest_id, "objectives": ["Task: 0/1"]}]


def chain_state(sc, w, quests, bag_list, log, done, label, race=1, cls=1, **kw):
    """The quest log and the quests done; every bag item against the model
    (kw: more for quest_checks); returns the old quest items listed: (item,
    why, quest)."""
    bag_quests(w, log)
    w.M.questDone = w.to_lua({q: True for q in done})
    w.M.fire("QUEST_LOG_UPDATE")
    w.settle(0.5)
    in_log = {q["questID"] for q in log if q.get("questID")}
    quest_checks(sc, w, quests, in_log, set(done), label, race, cls, bag_list=bag_list, **kw)
    s = w.ns.BagScan()
    return [(s.quest[i].id, s.quest[i].why, s.quest[i].quest) for i in range(1, len(s.quest) + 1)]


def sc_bag_questie_chain(sc, ref, items):
    """Along quest chains (the player's real QuestieDB rows, and a made-up
    lamp): a quest starter says Starts until its quest is done (QuestieDB
    lists it as the item its quest gives too), then Done; an item stays Keep
    while the next step still needs it, where a dropped one is gone for good:
    the phial after Back to Uldaman, and after Find the Gems until Restoring
    the Necklace is taken at the scrying bowl; the lamp while the quest it
    comes after is in the log; the Symbol of Life between the paladin's
    lessons."""
    w = World(ref, items)
    M, ns = w.M, w.ns
    quests = install_questie(w)
    for bag, slot, iid, count, name, fields in CHAIN_BAG:
        bag_add_item(w, iid, name, 1, 0, **fields)
        bag_put(w, bag, slot, iid, count)
    bag_quests(w, LOG_ELSEWHERE)
    ns.BagScan()
    w.settle(0.5)
    sc.eq(ns.QuestIndex.state, "ready", "chain: the index is ready")
    buy, pos, mu = QDB_COLORS["buy"], QDB_COLORS["pos"], QDB_COLORS["muted"]

    def state(log, done, label):
        return chain_state(sc, w, quests, CHAIN_BAG, log, done, label)

    # Nothing of the chain taken: the necklace starts it.
    rows = state(LOG_ELSEWHERE, (), "chain, nothing taken")
    sc.eq(lua_verdict(w, 7666), ("starts", "The Shattered Necklace", False), "chain: the necklace starts its quest")
    sc.eq(quest_tip(w, 0, 1), [("Starts The Shattered Necklace", buy)], "chain: necklace tooltip, gold Starts line")
    sc.check(7666 not in [r[0] for r in rows], "chain: a quest starter is no old quest item (%s)" % rows)
    out = [plain(x) for x in w.slash("/gl bags")]
    sc.check(not any("Shattered Necklace" in t for t in out), "chain /gl bags: the necklace is not listed (%s)" % out)
    sc.eq(lua_verdict(w, 6866), None, "chain: the Undead paladin's lessons are not a human warrior's")
    # Carrying it to Talvash, then handed in (a second necklace is just an old one).
    state(qlog(2198, "The Shattered Necklace"), (), "chain, necklace taken")
    sc.eq(lua_verdict(w, 7666), ("keep", "The Shattered Necklace", False), "chain: the necklace while its quest is in the log")
    rows = state(qlog(2199, "Lore for a Price"), (2198,), "chain, necklace handed in")
    sc.eq(lua_verdict(w, 7666), ("done", "The Shattered Necklace", False),
          "chain: the necklace once its quest is done (not kept for Lore for a Price)")
    sc.eq(quest_tip(w, 0, 1), [("Can drop: done with The Shattered Necklace", pos)], "chain: necklace tooltip, green done line")
    sc.check((7666, "done", "The Shattered Necklace") in rows, "chain: the necklace is listed as done (%s)" % rows)

    # Back to Uldaman done, Find the Gems not taken (a full log): the phial is
    # still needed, and no new one is given before Find the Gems is done.
    rows = state(LOG_ELSEWHERE, (2198, 2199, 2200), "chain, Find the Gems not taken")
    sc.eq(lua_verdict(w, 7667), ("keep", "Find the Gems", False), "chain: the phial after Back to Uldaman, Find the Gems not taken: keep")
    sc.eq(quest_tip(w, 0, 2), [("Keep: needed for Find the Gems", buy)], "chain: phial tooltip, gold keep line")
    sc.check(7667 not in [r[0] for r in rows], "chain: the phial is not listed (%s)" % rows)
    state(LOG_FIND_GEMS, (2198, 2199, 2200), "chain, on Find the Gems")
    sc.eq(lua_verdict(w, 7667), ("keep", "Find the Gems", False), "chain: the phial on Find the Gems")

    # Find the Gems handed in at the scrying bowl, Restoring the Necklace (it
    # starts at the bowl) not taken there: the phial calls the bowl up again.
    M.OpenBags(1)
    w.settle(0.2)
    BP = ns.BagPanel
    M.click(BP.tab)
    w.settle(0.2)
    rows = state(LOG_ELSEWHERE, (2198, 2199, 2200, 2201), "chain, Restoring the Necklace not taken")
    sc.eq(lua_verdict(w, 7667), ("keep", "Restoring the Necklace", False),
          "chain: the phial until Restoring the Necklace is taken at the bowl: keep")
    sc.eq(quest_tip(w, 0, 2), [("Keep: needed for Restoring the Necklace", buy)], "chain: phial tooltip names Restoring the Necklace")
    sc.check(7667 not in [r[0] for r in rows], "chain: the phial is still not listed (%s)" % rows)
    sc.eq(quest_rows(BP), [(7666, "done", pos)],
          "chain panel: the old necklace; no phial, no lamp (Deeper Down still needs it)")
    out = [plain(x) for x in w.slash("/gl bags")]
    sc.check(any(t.endswith("old quest items: [Shattered Necklace] (done: The Shattered Necklace)") for t in out),
             "chain /gl bags: the same, no phial (%s)" % out)
    # Taken (the player's case): the phial can go.
    rows = state(LOG_NECKLACE, (2198, 2199, 2200, 2201), "chain, Restoring the Necklace taken")
    sc.eq(lua_verdict(w, 7667), ("done", "Find the Gems", False), "chain: Restoring the Necklace in the log: the phial is done")
    sc.eq(quest_tip(w, 0, 2), [("Can drop: done with Find the Gems", pos)], "chain: phial tooltip, green done line")
    sc.eq(quest_rows(BP), [(7666, "done", pos), (7667, "done", pos)],
          "chain panel: the phial is listed as done")
    out = [plain(x) for x in w.slash("/gl bags")]
    sc.check(any("[Talvash's Phial of Scrying] (done: Find the Gems)" in t for t in out),
             "chain /gl bags: the phial is done (%s)" % out)
    state(qlog(2361, "Restoring the Necklace"), (2198, 2199, 2200, 2201, 2204), "chain, Restoring the Necklace done")
    sc.eq(lua_verdict(w, 7667), ("done", "Find the Gems", False), "chain: Restoring the Necklace done: the phial is done")
    # Closed headers and no IsOnQuest: whether it was taken cannot be told, so no verdict.
    bag_quests(w, [{"title": "Uldaman", "isHeader": True, "isCollapsed": True}])
    M.questDone = w.to_lua({q: True for q in (2198, 2199, 2200, 2201)})
    quest_checks(sc, w, quests, set(), {2198, 2199, 2200, 2201}, "chain, headers closed", log_known=False, bag_list=CHAIN_BAG)
    sc.eq(lua_verdict(w, 7667), ("maybe-hidden", "Restoring the Necklace", False),
          "chain: headers closed, Restoring the Necklace may be under one: not sure")
    sc.eq(quest_tip(w, 0, 2), [("Not sure: some quest log headers are closed", mu)], "chain: and the tooltip says so")

    # The lamp: Deeper Down comes after Into the Mine (all of 950039 and 950040,
    # the second as a negative id). In the log: keep; done and Deeper Down not
    # taken: still kept, Deeper Down needs it and you can still do it.
    state(qlog(950040, "Into the Mine"), (), "chain, on Into the Mine")
    sc.eq(lua_verdict(w, 900506), ("keep", "Deeper Down", False), "chain: the lamp while Into the Mine is in the log: keep")
    sc.eq(quest_tip(w, 0, 3), [("Keep: needed for Deeper Down", buy)], "chain: lamp tooltip, gold keep line")
    rows = state(LOG_ELSEWHERE, (950040,), "chain, Into the Mine done")
    sc.eq(lua_verdict(w, 900506), ("keep-later", "Deeper Down", False), "chain: Into the Mine done, Deeper Down not taken: kept")
    sc.eq(quest_tip(w, 0, 3), [("Keep: needed for Deeper Down", buy)], "chain: lamp tooltip, gold keep line")
    sc.check(900506 not in [r[0] for r in rows], "chain: the lamp is not listed (%s)" % rows)
    state(qlog(950041, "Deeper Down"), (950040,), "chain, on Deeper Down")
    sc.eq(lua_verdict(w, 900506), ("keep", "Deeper Down", False), "chain: the lamp on Deeper Down")
    M.CloseBags()
    w.settle(0.2)
    sc.clean(w, "chain")

    # An Undead paladin: the Symbol of Life is the reward of 94435 and needed for
    # 94438, which comes after 94436.
    wp = World(ref, items, faction="Horde")
    wp.M.race = wp.to_lua(["Undead", "Scourge", 5])
    wp.M["class"] = wp.to_lua(["Paladin", "PALADIN", 2])
    quests = install_questie(wp)
    for bag, slot, iid, count, name, fields in SYMBOL_BAG:
        bag_add_item(wp, iid, name, 1, 0, **fields)
        bag_put(wp, bag, slot, iid, count)
    bag_quests(wp, LOG_ELSEWHERE)
    wp.ns.BagScan()
    wp.settle(0.5)

    def pstate(log, done, label):
        return chain_state(sc, wp, quests, SYMBOL_BAG, log, done, label, race=5, cls=2)
    rows = pstate(qlog(94436, "A Lesson in Divinity"), (94434, 94435), "paladin, on 94436")
    sc.eq(lua_verdict(wp, 6866), ("keep", "A Lesson in Divinity", False),
          "paladin: the Symbol of Life on the lesson before the one that needs it: keep")
    sc.eq(quest_tip(wp, 0, 1), [("Keep: needed for A Lesson in Divinity", buy)], "paladin: symbol tooltip, gold keep line")
    sc.eq(rows, [], "paladin: nothing listed on 94436")
    rows = pstate(LOG_ELSEWHERE, (94434, 94435, 94436), "paladin, 94438 not taken")
    sc.eq(lua_verdict(wp, 6866), ("keep", "A Lesson in Divinity", False),
          "paladin: 94436 done, 94438 not taken: a reward you cannot get again is kept")
    sc.eq(rows, [], "paladin: nothing listed before 94438")
    pstate(qlog(94438, "A Lesson in Divinity"), (94434, 94435, 94436), "paladin, on 94438")
    sc.eq(lua_verdict(wp, 6866), ("keep", "A Lesson in Divinity", False), "paladin: the symbol on 94438")
    rows = pstate(LOG_ELSEWHERE, (94434, 94435, 94436, 94438), "paladin, 94438 done")
    sc.eq(lua_verdict(wp, 6866), ("done", "A Lesson in Divinity", False), "paladin: 94438 done: done")
    sc.eq(rows, [(6866, "done", "A Lesson in Divinity")], "paladin: then the symbol is listed as done")
    sc.clean(wp, "chain paladin")


def sc_bag_questie_slicing(sc, ref, items):
    """The index is made over many frames: at most 150 quests a frame, or about
    3 ms when debugprofilestop exists; a few seconds after login, or at once
    when the bag cleanup first needs it."""
    TICK_LOG = r'''
      local M = MOCK
      M.tickReads = {}
      local orig = M.tick
      M.tick = function(dt)
        local r0, ms0 = M.qdb.objectives, M.profileMs
        orig(dt)
        local n = M.qdb.objectives - r0
        if n > 0 then M.tickReads[#M.tickReads + 1] = { n = n, ms = M.profileMs - ms0 } end
      end
    '''
    filler = 2000
    w = World(ref, items)
    quests = install_questie(w, filler=filler)
    total = len(quests)
    w.lua.execute(TICK_LOG)
    QI = w.ns.QuestIndex
    w.settle(4.0)
    sc.eq(QI.state, "idle", "slicing: nothing read in the first seconds after login")
    sc.eq(w.M.qdb.objectives, 0, "slicing: no quest read yet")
    w.settle(0.9)
    sc.eq(QI.state, "building", "slicing: started 5 seconds after login")
    w.settle(5.0)
    sc.eq(QI.state, "ready", "slicing: ready")
    ticks = [(w.M.tickReads[i].n, w.M.tickReads[i].ms) for i in range(1, len(w.M.tickReads) + 1)]
    sc.eq(sum(n for n, _ in ticks), total, "slicing: each quest read once (%d)" % total)
    sc.check(max(n for n, _ in ticks) <= 150, "slicing: at most 150 quests a frame (%d)" % max(n for n, _ in ticks))
    sc.eq(len(ticks), -(-total // 150), "slicing: %d quests over %d frames" % (total, -(-total // 150)))
    sc.eq((QI.ticks, QI.most), (len(ticks), 150), "slicing: the index counts its frames and the most in one")
    sc.eq(QI.size, len(ref_quest_index(quests)), "slicing: every item indexed")
    sc.clean(w, "slicing")

    # debugprofilestop: each read takes 0.02 ms here, so a quest (3 reads)
    # 0.06 ms, and about 50 fit in the 3 ms a frame may take.
    w2 = World(ref, items)
    w2.lua.execute("debugprofilestop = function() return MOCK.profileMs end")
    quests = install_questie(w2, filler=filler)
    w2.lua.execute(TICK_LOG)
    w2.M.qdb.cost = 0.02
    quest_bags(w2, LOG_FIND_GEMS, done=(2198, 2199, 2200))
    # The bag cleanup's first need starts it at once, and /gl bags says it is still reading.
    out = [plain(x) for x in w2.slash("/gl bags")]
    sc.eq(w2.ns.QuestIndex.state, "building", "slicing ms: /gl bags started the index before the login delay")
    sc.check(any("still reading Questie's quests: type /gl bags again in a moment" in t for t in out),
             "slicing ms: /gl bags says it is still reading (%s)" % out)
    w2.settle(6.0)
    sc.eq(w2.ns.QuestIndex.state, "ready", "slicing ms: ready")
    ticks = [(w2.M.tickReads[i].n, w2.M.tickReads[i].ms) for i in range(1, len(w2.M.tickReads) + 1)]
    per = 3 * 0.02
    sc.eq(sum(n for n, _ in ticks), len(quests), "slicing ms: each quest read once")
    sc.check(all(ms <= 3 + per + 1e-6 for _, ms in ticks), "slicing ms: no frame over 3 ms and one quest (%s)"
             % max(ms for _, ms in ticks))
    sc.check(all(n <= 51 for n, _ in ticks) and max(n for n, _ in ticks) >= 49,
             "slicing ms: about 50 quests a frame (%s)" % sorted(set(n for n, _ in ticks)))
    out = [plain(x) for x in w2.slash("/gl bags")]
    sc.check(any(t.endswith("old quest items: [Gnarled Root] x2 (no quest needs it)") for t in out)
             and not any("Crag Coyote Fang" in t for t in out),
             "slicing ms: QuestieDB verdicts once ready: the fang is kept for its quest (%s)" % out)
    sc.check(not any("still reading" in t for t in out), "slicing ms: no reading note once ready")
    sc.clean(w2, "slicing ms")


def sc_bag_questie_saved(sc, ref, items):
    """The index is saved with QuestieDB's version, used again as long as that
    stays, and made again when QuestieDB changes (or our format does)."""
    w = World(ref, items)
    quests = install_questie(w)
    want = ref_quest_index(quests)
    w.settle(6.0)
    sc.eq(w.ns.QuestIndex.state, "ready", "saved: built after login")
    saved = lua_to_py(w.g.ForeverAH_Settings)
    qi = saved.get("questIndex") or {}
    sc.eq(qi.get("stamp"), QDB_STAMP, "saved: the stamp is QuestieDB's version, commit, contract and our format")
    raw = qi.get("items") or {}
    sc.check(all(isinstance(v, (int, float)) or (isinstance(v, str) and re.match(r"^\d+(,\d+)+$", v)) for v in raw.values()),
             "saved: compact, a code or a string of codes per item")
    got = {k: (sorted(int(c) for c in v.split(",")) if isinstance(v, str) else v) for k, v in raw.items()}
    sc.eq(got, {k: (sorted(v) if isinstance(v, list) else v) for k, v in want.items()}, "saved: the index item -> quest codes")
    sc.eq(got.get(7667), 2200 * 4 + 1, "saved: the phial is given by Back to Uldaman")
    sc.eq(raw.get(7846), "9032,10000", "saved: the fang is asked for by both reagent runs (2258, 2500)")

    def again(label, version="1.1.2", commit=QDB_COMMIT, sv=saved):
        w2 = World(ref, items, saved=sv)
        install_questie(w2, version=version, commit=commit)
        quest_bags(w2, LOG_NECKLACE, done=(2198, 2199, 2200, 2201))
        w2.ns.BagScan()
        return w2
    w2 = again("same")
    sc.eq(w2.ns.QuestIndex.state, "ready", "saved: the same QuestieDB uses the saved index at once")
    sc.check(w2.ns.QuestIndex.saved is True, "saved: and says so")
    w2.settle(6.0)
    sc.eq(w2.M.qdb.objectives, 0, "saved: no quest is read again")
    sc.eq(lua_verdict(w2, 7667), ("done", "Find the Gems", False), "saved: the phial's verdict from the saved index")
    sc.eq(lua_verdict(w2, 7846), ("keep-turnin", "Badlands Reagent Run", False),
          "saved: the fang's (two quests in one saved string)")
    n, _ = bagcheck(sc, w2, "saved bagcheck")
    sc.check((n.get(8) or "").endswith(", quests from QuestieDB (%d items, saved)" % len(want)), "saved bagcheck: line 8 (%s)" % n.get(8))
    sc.clean(w2, "saved", ok_chat=BAGCHECK_LINES)
    for label, kw in (("new QuestieDB version", {"version": "1.1.3"}), ("new QuestieDB commit", {"commit": "0123abc"})):
        w3 = again(label, **kw)
        sc.eq(w3.ns.QuestIndex.state, "building", "saved, %s: made again" % label)
        w3.settle(1.0)
        sc.eq(w3.M.qdb.objectives, len(quests), "saved, %s: every quest read again" % label)
        st = lua_to_py(w3.g.ForeverAH_Settings).get("questIndex") or {}
        stamp = "%s|%s|4|1" % (kw.get("version", "1.1.2"), kw.get("commit", QDB_COMMIT))
        sc.eq(st.get("stamp"), stamp, "saved, %s: saved with the new stamp" % label)
        sc.eq(lua_verdict(w3, 7667), ("done", "Find the Gems", False), "saved, %s: verdicts" % label)
        sc.clean(w3, "saved " + label)
    old = dict(saved)
    old["questIndex"] = dict(qi, stamp=QDB_STAMP[:-1] + "0")
    w4 = again("older format", sv=old)
    sc.eq(w4.ns.QuestIndex.state, "building", "saved: an index of an older format is made again")
    w4.settle(1.0)
    sc.eq(w4.ns.QuestIndex.state, "ready", "saved: older format, ready again")
    # QuestieDB that names no version: made each session, not saved.
    w5 = World(ref, items)
    install_questie(w5, version=None, commit=None)
    w5.settle(7.0)
    sc.eq(w5.ns.QuestIndex.state, "ready", "saved: no version stamp, still made")
    sc.check(w5.g.ForeverAH_Settings.questIndex is None, "saved: but not saved without a version stamp")
    sc.clean(w5, "saved no stamp")


def sc_bag_questie_fallback(sc, ref, items):
    """Without QuestieDB, with one whose contract does not match, or one that
    breaks: quest items are judged from the quest log exactly as before."""
    def world(setup=None):
        w = World(ref, items)
        if setup:
            setup(w)
        quest_bags(w, LOG_NECKLACE, done=(2198, 2199, 2200, 2201))
        return w

    def snapshot(w):
        s = w.ns.BagScan()
        w.settle(0.5)
        s = w.ns.BagScan()
        quest = [(s.quest[i].id, s.quest[i].why, bool(s.quest[i].sure), s.quest[i].qdb) for i in range(1, len(s.quest) + 1)]
        tips = [quest_tip(w, bag, slot) for bag, slot, _, _, _, _ in QUEST_BAG]
        return quest, tips
    base = world()
    bq, btips = snapshot(base)
    sc.check(7667 not in [q[0] for q in bq], "no questie: the phial is kept (Restoring the Necklace mentions Talvash): today's silence")
    sc.check(all(q[3] is None for q in bq), "no questie: every verdict is the quest log's")
    sc.eq(btips, [plain_tip(f) for _, _, _, _, _, f in QUEST_BAG], "no questie: no quest line on any tooltip")
    sc.eq(base.ns.QuestIndex.state, "absent", "no questie: the index knows QuestieDB is not loaded")
    base.settle(6.0)
    sc.eq(base.ns.QuestIndex.state, "absent", "no questie: and stays so after the login delay")
    n, _ = bagcheck(sc, base, "no questie bagcheck")
    sc.check(", quests" not in (n.get(8) or "") and "QuestieDB" not in (n.get(8) or ""), "no questie bagcheck: line 8 as before (%s)" % n.get(8))
    sc.clean(base, "no questie", ok_chat=BAGCHECK_LINES)
    cases = [
        ("contract mismatch", lambda w: install_questie(w, contract_fails=True), "contract mismatch"),
        ("no quest list", lambda w: install_questie(w, no_quest_list=True), "no quest reads"),
        ("reads fail", lambda w: (install_questie(w), w.lua.execute("MOCK.qdb.fail = true")), "QuestieDB read failed"),
    ]
    for label, setup, why in cases:
        w = world(setup)
        q, tips = snapshot(w)
        sc.eq(q, bq, "%s: the old quest items are today's" % label)
        sc.eq(tips, btips, "%s: no quest line on any tooltip" % label)
        sc.eq(w.ns.QuestIndex.state, "off", "%s: QuestieDB is not used this session" % label)
        sc.check(why in str(w.ns.QuestIndex.err), "%s: and why (%s)" % (label, w.ns.QuestIndex.err))
        n, _ = bagcheck(sc, w, label + " bagcheck")
        sc.check("QuestieDB not used (" in (n.get(8) or ""), "%s bagcheck: line 8 says QuestieDB is not used (%s)" % (label, n.get(8)))
        sc.clean(w, label, ok_chat=BAGCHECK_LINES + ("QuestieDB not used",))
    # Reads that break after the index was made: back to the quest log, the saved index dropped.
    w = World(ref, items)
    install_questie(w)
    quest_bags(w, LOG_NECKLACE, done=(2198, 2199, 2200, 2201))
    w.settle(6.0)
    sc.check(w.g.ForeverAH_Settings.questIndex is not None, "breaks later: the index was saved")
    w.lua.execute("MOCK.qdb.fail = true")
    q, tips = snapshot(w)
    sc.eq(q, bq, "breaks later: the old quest items are today's")
    sc.eq(tips, btips, "breaks later: no quest line")
    sc.eq(w.ns.QuestIndex.state, "off", "breaks later: QuestieDB is not used")
    sc.check(w.g.ForeverAH_Settings.questIndex is None, "breaks later: the saved index is dropped (made again next time)")
    sc.clean(w, "breaks later")


# A tool and a note from the same chain: the phial (Use: it creates the scrying bowl) and the
# Bloodstained Journal, which Find the Gems gives you: readable, soulbound, no price, and not
# marked as a quest item.
JOURNAL_BAG = [
    (0, 1, 7667, 1, "Talvash's Phial of Scrying", {"classID": 12, "bind": 4, "maxStack": 1, "useSpell": "Create Scrying Bowl"}),
    (0, 2, 7668, 1, "Bloodstained Journal", {"classID": 15, "bind": 1, "maxStack": 1}),
]


def sc_bag_questie_journal(sc, ref, items):
    """With QuestieDB, an item a quest gave you that is not marked as a quest item (the
    Bloodstained Journal) gets the same tooltip line and cleanup row as a quest item. A tool
    you use (the phial) is for the quest after the one that gave it; a note you read (the
    journal) may be for any quest after it: once Find the Gems is done it may be needed for
    Restoring the Necklace (not sure, never can drop), it is kept while that quest is in the
    log, and it can go once that one is done too."""
    w = World(ref, items)
    M, ns, g = w.M, w.ns, w.g
    quests = install_questie(w)
    for bag, slot, iid, count, name, fields in JOURNAL_BAG:
        bag_add_item(w, iid, name, 1, 0, **fields)
        bag_put(w, bag, slot, iid, count)
    pos, buy, mu = QDB_COLORS["pos"], QDB_COLORS["buy"], QDB_COLORS["muted"]

    def state(log, done):
        bag_quests(w, log)
        for q in (2198, 2199, 2200, 2201, 2204):
            M.questDone[q] = q in done
        M.fire("QUEST_LOG_UPDATE")
        w.settle(0.5)
    state(LOG_FIND_GEMS, (2198, 2199, 2200))
    quest_tip(w, 0, 2)                     # the first need starts the index
    w.settle(0.5)
    sc.eq(ns.QuestIndex.state, "ready", "journal: the index is ready")
    # On Find the Gems: both kept for it.
    sc.eq(lua_verdict(w, 7668), ("keep", "Find the Gems", False), "journal: while on Find the Gems: keep")
    sc.eq(lua_verdict(w, 7667), ("keep", "Find the Gems", False), "journal: the phial too")
    sc.eq(quest_tip(w, 0, 2), [("Keep: needed for Find the Gems", buy)], "journal: tooltip, gold keep line")
    quest_checks(sc, w, quests, {2201}, {2198, 2199, 2200}, "journal on Find the Gems", bag_list=JOURNAL_BAG)
    # Find the Gems done, Restoring the Necklace not taken: the journal may be needed for
    # it (not sure, so not can drop); the phial is how you start that quest (its bowl), so
    # it stays.
    state([{"title": "Uldaman", "isHeader": True}], (2198, 2199, 2200, 2201))
    sc.eq(lua_verdict(w, 7668), ("maybe-next", "Restoring the Necklace", False),
          "journal: after Find the Gems: may be needed for Restoring the Necklace")
    sc.eq(lua_verdict(w, 7667), ("keep", "Restoring the Necklace", False), "journal: the phial waits for the next quest")
    sc.eq(quest_tip(w, 0, 2), [("May be needed for Restoring the Necklace", mu)], "journal: tooltip, grey maybe line")
    sc.eq(quest_tip(w, 0, 1), [("Keep: needed for Restoring the Necklace", buy)], "journal: phial tooltip, gold keep line")
    quest_checks(sc, w, quests, set(), {2198, 2199, 2200, 2201}, "journal after Find the Gems", bag_list=JOURNAL_BAG)
    M.OpenBags(1)
    w.settle(0.2)
    BP = ns.BagPanel
    M.click(BP.tab)
    w.settle(0.2)
    sc.eq(quest_rows(BP), [(7668, "maybe", buy)], "journal panel: listed as maybe (gold), not done; the phial is not listed")
    row = bag_row_for(BP, 7668)
    if sc.check(row is not None, "journal panel: the journal has a row"):
        sc.check(row.entry.questItem is True, "journal panel: a click only picks it up (never the drop box)")
        M.enter(row)
        lines = [plain(l) for l, _ in w.all_lines(g.GameTooltip)]
        sc.check("May be needed for Restoring the Necklace. Keep it until that quest is done." in lines,
                 "journal panel: the row tooltip says it may be needed (%s)" % lines)
        sc.check(not any("Can drop" in l or "destroy" in l for l in lines),
                 "journal panel: and never offers it as droppable (%s)" % lines)
        M.leave(row)
    out = [plain(x) for x in w.slash("/gl bags")]
    sc.check(any("[Bloodstained Journal] (maybe needed for Restoring the Necklace)" in t for t in out), "journal /gl bags (%s)" % out)
    # On Restoring the Necklace: the journal is kept for it, the phial can go.
    state(LOG_NECKLACE, (2198, 2199, 2200, 2201))
    sc.eq(lua_verdict(w, 7668), ("keep", "Restoring the Necklace", False), "journal: on Restoring the Necklace: keep")
    sc.eq(lua_verdict(w, 7667), ("done", "Find the Gems", False), "journal: the phial can go")
    quest_checks(sc, w, quests, {2204}, {2198, 2199, 2200, 2201}, "journal on Restoring the Necklace", bag_list=JOURNAL_BAG)
    sc.eq(quest_rows(BP), [(7667, "done", pos)], "journal panel: on Restoring the Necklace only the phial is listed, as done")
    # Restoring the Necklace done (the next one, 2361, not taken): both can go.
    state(qlog(950040, "Into the Mine"), (2198, 2199, 2200, 2201, 2204))
    sc.eq(lua_verdict(w, 7668), ("done", "Find the Gems", False), "journal: Restoring the Necklace done: can drop")
    quest_checks(sc, w, quests, {950040}, {2198, 2199, 2200, 2201, 2204}, "journal after Restoring the Necklace",
                 bag_list=JOURNAL_BAG)
    sc.eq(quest_rows(BP), [(7668, "done", pos), (7667, "done", pos)], "journal panel: both listed as done")
    M.CloseBags()
    w.settle(0.2)
    sc.clean(w, "journal")


def sc_bag_quest_log_fallback(sc, ref, items):
    """Without QuestieDB: when the client gives no objective texts through
    C_QuestLog.GetQuestObjectives, the quest log's own lines are read, so a note its quest
    names is kept; and a quest item no quest names, while a quest in the log lists nothing,
    says it is not sure (never "no quest in your log asks for it" as a fact)."""
    w = World(ref, items)
    M, ns, g = w.M, w.ns, w.g
    bag_add_item(w, 904649, "Bonegrip's Note", 1, 0, classID=12, bind=4, maxStack=1)
    bag_put(w, 0, 1, 904649, 1)
    bag_add_item(w, 904650, "Dusty Key", 1, 0, classID=12, bind=4, maxStack=1)
    bag_put(w, 0, 2, 904650, 1)
    bag_quests(w, [{"title": "Burning Steppes", "isHeader": True},
                   {"title": "The Star, the Hand and the Heart", "questID": 950735, "objectives": ["Bonegrip's Note: 1/1"]},
                   {"title": "Talk to the Smith", "questID": 950736, "objectives": []}])
    M.questObjectivesEmpty = True
    M.OpenBags(1)
    w.settle(0.2)
    BP = ns.BagPanel
    M.click(BP.tab)
    w.settle(0.2)
    ids = [r[0] for r in quest_rows(BP)]
    sc.check(904649 not in ids, "log fallback: the note its quest names (from the quest log lines) is kept (%s)" % ids)
    sc.check(904650 in ids, "log fallback: the key no quest names is listed (%s)" % ids)
    row = bag_row_for(BP, 904650)
    if sc.check(row is not None, "log fallback: the key has a row"):
        sc.eq(row.right._text, "check log", "log fallback: a quest that lists nothing makes it a 'check log'")
        M.enter(row)
        lines = [plain(l) for l, _ in w.all_lines(g.GameTooltip)]
        sc.check(any(l.startswith("Not sure: no quest in your log names it") for l in lines),
                 "log fallback: the row tooltip says it is not sure (%s)" % lines)
        sc.check(not any(l.startswith("This ") or l == "No quest in your log asks for it." for l in lines),
                 "log fallback: and never states it as a fact (%s)" % lines)
        M.leave(row)
    M.CloseBags()
    w.settle(0.2)
    sc.clean(w, "log fallback")


# The owner's Field Marshal's Log (item 267256): "Soulbound, Unique, <Right Click to Read>", no
# Use effect, no price. QuestieDB's real rows (QUEST_MARSHAL, ITEMS_MARSHAL): Saving Marshal Ryan
# gives it; Field Marshal's Log (the quest, started by the other item of that name, 266427) comes
# before, Dying Wish and Delivering Closure after. Broken Tooth: a grey item Drop cheapest may name.
MARSHAL_LOG = (0, 1, 267256, 1, "Field Marshal's Log", {"classID": 15, "bind": 1, "maxStack": 1})
MARSHAL_BAG = [MARSHAL_LOG]
TOOTH = 900601


def farholde(*entries, collapsed=False):
    """A quest log with these (quest id, title) quests under one header (closed: they are hidden)."""
    head = [{"title": "Farholde", "isHeader": True, "isCollapsed": collapsed}]
    if collapsed:
        return head
    return head + [{"title": t, "questID": q, "objectives": []} for q, t in entries]


def marshal_world(ref, items, vendor=0, questie=True):
    """The log and a Broken Tooth in the bags (the log worth `vendor` copper each at a vendor),
    QuestieDB loaded and its index made, the cleanup panel open."""
    w = World(ref, items)
    quests = install_questie(w) if questie else None
    bag, slot, iid, count, name, fields = MARSHAL_LOG
    bag_add_item(w, iid, name, 1, vendor, **fields)
    bag_put(w, bag, slot, iid, count, bound=True)
    bag_add_item(w, TOOTH, "Broken Tooth", 0, 3, classID=15, maxStack=20)
    bag_put(w, 0, 2, TOOTH, 1)
    bag_quests(w, LOG_ELSEWHERE)
    w.settle(6.0)                         # the index is made a few seconds after login
    w.M.OpenBags(1)
    w.settle(0.2)
    w.M.click(w.ns.BagPanel.tab)
    w.settle(0.2)
    return w, quests


def marshal_state(sc, w, quests, log, done, label, **kw):
    """chain_state for the log; returns the cleanup's listed old quest items."""
    return chain_state(sc, w, quests, MARSHAL_BAG, log, done, label, **kw)


def drop_names(sc, w, label, want=TOOTH):
    """The log is never on the cheapest list unless done, and Drop cheapest's box names `want`."""
    ns, M, g = w.ns, w.M, w.g
    BP = ns.BagPanel
    s = ns.BagScan()
    listed = [s.drop[i].id for i in range(1, len(s.drop) + 1)]
    if want != 267256:
        sc.check(267256 not in listed, "%s: the log is not on the cheapest list (%s)" % (label, listed))
    c = BP.Cheapest(BP, s)
    sc.eq(c.id if c is not None else None, want, "%s: Drop cheapest picks %s" % (label, "the log" if want == 267256 else "the Broken Tooth"))
    db = BP.dropButton
    if sc.check(db.IsVisible(db), "%s: Drop cheapest shows" % label):
        M.click(db)
        C = g.ForeverAHBagConfirm
        sc.eq(C.name._text if C is not None else None, "Field Marshal's Log" if want == 267256 else "Broken Tooth",
              "%s: the drop box names it" % label)
        BP.CloseConfirm(BP)
        sc.eq(len(M.destroyed), 0, "%s: nothing destroyed" % label)


def row_lines(sc, w, iid):
    """The cleanup row's tooltip lines for an item, or None without a row."""
    BP = w.ns.BagPanel
    row = bag_row_for(BP, iid)
    if row is None:
        return None
    w.M.enter(row)
    lines = [plain(l) for l, _ in w.all_lines(w.g.GameTooltip)]
    w.M.leave(row)
    return lines


def sc_bag_questie_marshal(sc, ref, items):
    """The owner's case: the Field Marshal's Log said "Can drop: done with Saving Marshal Ryan"
    while they still needed it. A note a quest gave you is kept while a quest after that one is
    in your log (the ones between done), not sure while the quest right after it is not done
    (never Can drop, never on Drop cheapest), and done only once that quest is done too."""
    buy, pos, mu = QDB_COLORS["buy"], QDB_COLORS["pos"], QDB_COLORS["muted"]
    w, quests = marshal_world(ref, items)
    M, ns = w.M, w.ns
    BP = ns.BagPanel
    sc.eq(ns.QuestIndex.state, "ready", "marshal: the index is ready")
    sc.eq(w.lua.eval("MOCK.items[267256].useSpell"), None, "marshal: the log has no Use effect (it is read)")
    # (a) Saving Marshal Ryan done, Dying Wish (the next quest) in the log: keep.
    rows = marshal_state(sc, w, quests, farholde((94892, "Dying Wish")), (94885, 94887), "marshal, on Dying Wish")
    sc.eq(lua_verdict(w, 267256), ("keep", "Dying Wish", False), "marshal: Saving Marshal Ryan done, Dying Wish in the log: keep")
    sc.eq(quest_tip(w, 0, 1), [("Keep: needed for Dying Wish", buy)], "marshal: tooltip, gold keep line (never Can drop)")
    sc.eq(rows, [], "marshal: not listed as an old quest item")
    sc.eq(quest_rows(BP), [], "marshal panel: no old quest item row")
    drop_names(sc, w, "marshal, on Dying Wish")
    out = [plain(x) for x in w.slash("/gl bags")]
    sc.check(not any("Field Marshal's Log" in t for t in out), "marshal /gl bags: the log is not named (%s)" % out)
    # (b) Saving Marshal Ryan done, Dying Wish not taken: not sure, never Can drop.
    rows = marshal_state(sc, w, quests, LOG_ELSEWHERE, (94885, 94887), "marshal, Dying Wish not taken")
    sc.eq(lua_verdict(w, 267256), ("maybe-next", "Dying Wish", False),
          "marshal: Saving Marshal Ryan done, Dying Wish not taken: may be needed for it")
    sc.eq(quest_tip(w, 0, 1), [("May be needed for Dying Wish", mu)], "marshal: tooltip, grey maybe line")
    sc.eq(rows, [(267256, "maybe", "Dying Wish")], "marshal: listed as maybe, not done")
    sc.eq(quest_rows(BP), [(267256, "maybe", buy)], "marshal panel: the row says maybe in gold")
    lines = row_lines(sc, w, 267256) or []
    sc.check("May be needed for Dying Wish. Keep it until that quest is done." in lines,
             "marshal panel: the row tooltip says why (%s)" % lines)
    sc.check(not any("Can drop" in l or "destroy" in l for l in lines), "marshal panel: and never offers it as droppable (%s)" % lines)
    drop_names(sc, w, "marshal, Dying Wish not taken")
    out = [plain(x) for x in w.slash("/gl bags")]
    sc.check(any("old quest items: [Field Marshal's Log] (maybe needed for Dying Wish)" in t for t in out),
             "marshal /gl bags: maybe needed (%s)" % out)
    # (c) Dying Wish done too, Delivering Closure not taken: done.
    rows = marshal_state(sc, w, quests, LOG_ELSEWHERE, (94885, 94887, 94892), "marshal, Dying Wish done")
    sc.eq(lua_verdict(w, 267256), ("done", "Saving Marshal Ryan", False), "marshal: Dying Wish done too: can drop")
    sc.eq(quest_tip(w, 0, 1), [("Can drop: done with Saving Marshal Ryan", pos)], "marshal: tooltip, green can drop line")
    sc.eq(quest_rows(BP), [(267256, "done", pos)], "marshal panel: listed as done")
    drop_names(sc, w, "marshal, done (worth nothing, so still not on the cheapest list)")
    # Dying Wish in the log though the game flags it done: the log wins, keep.
    marshal_state(sc, w, quests, farholde((94892, "Dying Wish")), (94885, 94887, 94892), "marshal, Dying Wish flagged done")
    sc.eq(lua_verdict(w, 267256), ("keep", "Dying Wish", False), "marshal: Dying Wish in the log but flagged done: keep")
    # Further along: kept while Delivering Closure is in the log, done once it is done.
    marshal_state(sc, w, quests, farholde((94893, "Delivering Closure")), (94885, 94887, 94892), "marshal, on Delivering Closure")
    sc.eq(lua_verdict(w, 267256), ("keep", "Delivering Closure", False),
          "marshal: Dying Wish done, Delivering Closure in the log: keep")
    marshal_state(sc, w, quests, LOG_ELSEWHERE, (94885, 94887, 94892, 94893), "marshal, the chain done")
    sc.eq(lua_verdict(w, 267256), ("done", "Saving Marshal Ryan", False), "marshal: the whole chain done: can drop")
    # Before Saving Marshal Ryan is done: on it, kept; on the quest before it, kept for it.
    marshal_state(sc, w, quests, farholde((94887, "Saving Marshal Ryan")), (94885,), "marshal, on Saving Marshal Ryan")
    sc.eq(lua_verdict(w, 267256), ("keep", "Saving Marshal Ryan", False), "marshal: on Saving Marshal Ryan: keep")
    marshal_state(sc, w, quests, farholde((94885, "Field Marshal's Log")), (), "marshal, on Field Marshal's Log")
    sc.eq(lua_verdict(w, 267256), ("keep", "Saving Marshal Ryan", False),
          "marshal: on Field Marshal's Log, the quest before Saving Marshal Ryan: kept for that one")
    M.CloseBags()
    w.settle(0.2)
    sc.clean(w, "marshal")

    # Even if a vendor paid for it, a note that is needed (or may be) is never offered to drop.
    wv, quests = marshal_world(ref, items, vendor=1)
    for log, done, label in ((farholde((94892, "Dying Wish")), (94885, 94887), "on Dying Wish"),
                             (LOG_ELSEWHERE, (94885, 94887), "Dying Wish not taken")):
        marshal_state(sc, wv, quests, log, done, "marshal 1c, " + label)
        drop_names(sc, wv, "marshal worth 1c, " + label)
    sc.eq(quest_rows(wv.ns.BagPanel), [(267256, "maybe", buy)], "marshal worth 1c: listed as maybe, not on the cheapest list")
    marshal_state(sc, wv, quests, LOG_ELSEWHERE, (94885, 94887, 94892), "marshal 1c, done")
    drop_names(sc, wv, "marshal worth 1c, done: then it is fair game", want=267256)
    wv.M.CloseBags()
    wv.settle(0.2)
    sc.clean(wv, "marshal worth 1c")

    # A tool along a chain with no scrying bowl between its quests: kept for the quest after
    # the one that gave it, and while a later one is in the log.
    wt = World(ref, items)
    quests = install_questie(wt)
    lantern = [(0, 1, 900607, 1, "Lantern of the Deep", {"classID": 12, "bind": 4, "maxStack": 1, "useSpell": "Light Lantern"})]
    bag_add_item(wt, 900607, "Lantern of the Deep", 1, 0, **lantern[0][5])
    bag_put(wt, 0, 1, 900607, 1)
    bag_quests(wt, LOG_ELSEWHERE)
    wt.settle(6.0)
    chain_state(sc, wt, quests, lantern, LOG_ELSEWHERE, (950070,), "lantern, Into the Dark not taken")
    sc.eq(lua_verdict(wt, 900607), ("keep", "Into the Dark", False), "lantern: the tool is kept for the quest after its own")
    chain_state(sc, wt, quests, lantern, qlog(950072, "Deeper Still"), (950070, 950071), "lantern, on Deeper Still")
    sc.eq(lua_verdict(wt, 900607), ("keep", "Deeper Still", False), "lantern: and while a later quest of the chain is in the log")
    chain_state(sc, wt, quests, lantern, LOG_ELSEWHERE, (950070, 950071), "lantern, Into the Dark done")
    sc.eq(lua_verdict(wt, 900607), ("done", "Into the Dark", False), "lantern: Into the Dark done, Deeper Still not taken: can drop")
    sc.clean(wt, "marshal lantern")

    # A Horde character: the chain is the Alliance's, QuestieDB has no verdict.
    wh = World(ref, items, faction="Horde")
    wh.M.race = wh.to_lua(["Orc", "Orc", 2])
    install_questie(wh)
    bag_add_item(wh, 267256, "Field Marshal's Log", 1, 0, **MARSHAL_LOG[5])
    bag_put(wh, 0, 1, 267256, 1, bound=True)
    bag_quests(wh, LOG_ELSEWHERE)
    wh.ns.BagScan()
    wh.settle(0.5)
    wh.M.questDone = wh.to_lua({94885: True, 94887: True})
    sc.eq(lua_verdict(wh, 267256), None, "marshal horde: not their chain, no verdict")
    sc.clean(wh, "marshal horde")


def sc_bag_quest_log_names(sc, ref, items):
    """Your quest log beats QuestieDB: with QuestieDB saying the Field Marshal's Log is done, a
    quest in the log titled Field Marshal's Log, one whose own text names it, or one whose
    objective names it keeps it (an item objective must name that very item). The text is read
    with the quest selected: the player's selection is put back, headers are never opened or
    closed, each quest is read once, and a client whose selection cannot be read is not touched."""
    buy, pos = QDB_COLORS["buy"], QDB_COLORS["pos"]
    done = (94885, 94887, 94892)
    w, quests = marshal_world(ref, items)
    M, ns = w.M, w.ns
    BP = ns.BagPanel
    marshal_state(sc, w, quests, LOG_ELSEWHERE, done, "names, none")
    sc.eq(lua_verdict(w, 267256), ("done", "Saving Marshal Ryan", False), "names: no quest names it: QuestieDB's done")
    # A quest titled with the item's name (QuestieDB ties that quest to the other log).
    rows = marshal_state(sc, w, quests, farholde((94885, "Field Marshal's Log")), (94887, 94892), "names, title",
                         named={267256: "Field Marshal's Log"})
    sc.eq(lua_verdict(w, 267256), ("keep", "Field Marshal's Log", False), "names: a quest titled Field Marshal's Log keeps it")
    sc.eq(quest_tip(w, 0, 1), [("Keep: needed for Field Marshal's Log", buy)], "names: gold keep line")
    sc.eq(rows, [], "names: not listed")
    # A quest QuestieDB does not know whose own text names it; the selection is put back.
    seal = [{"title": "Farholde", "isHeader": True},
            {"title": "A Seal for Farholde", "questID": 950050, "objectives": [],
             "text": "Abigail Lawson wants the field marshal's log back, seal and all.", "objText": "Speak with Abigail Lawson."},
            {"title": "Wanted: Gath'Ilzogg", "questID": 950051, "objectives": ["Gath'Ilzogg slain: 0/1"], "kinds": ["monster"],
             "text": "Gath'Ilzogg leads the ogres.", "objText": "Kill Gath'Ilzogg."}]
    bag_quests(w, seal)
    M.questSel = 2                       # the player looks at A Seal for Farholde; the last one read is 3
    n0 = M.questSelects
    sc.eq(lua_verdict(w, 267256), ("keep", "A Seal for Farholde", False), "names: a quest whose text names it keeps it")
    sc.eq(M.questSel, 2, "names: the player's selection is put back")
    n1 = M.questSelects
    sc.check(n1 > n0, "names: the quest was selected to read its text (%d selects)" % (n1 - n0))
    sc.eq(lua_verdict(w, 267256), ("keep", "A Seal for Farholde", False), "names: again")
    sc.eq(M.questSelects, n1, "names: a quest's text is read once")
    sc.eq(M.questSel, 2, "names: the selection is still the player's")
    marshal_state(sc, w, quests, seal, done, "names, text", named={267256: "A Seal for Farholde"})
    sc.eq(quest_rows(BP), [], "names panel: not listed")
    # An objective that names it (not an item objective): kept. An item objective names one
    # item, so one for another item that starts with the same words does not.
    proof = [{"title": "Farholde", "isHeader": True},
             {"title": "Proof of Loyalty", "questID": 950052, "objectives": ["Field Marshal's Log shown to Abigail: 0/1"],
              "kinds": ["event"]}]
    marshal_state(sc, w, quests, proof, done, "names, objective", named={267256: "Proof of Loyalty"})
    sc.eq(lua_verdict(w, 267256), ("keep", "Proof of Loyalty", False), "names: an objective that names it keeps it")
    case = [{"title": "Farholde", "isHeader": True},
            {"title": "Locked Away", "questID": 950053, "objectives": ["Field Marshal's Log Case: 0/1"], "kinds": ["item"]}]
    marshal_state(sc, w, quests, case, done, "names, other item")
    sc.eq(lua_verdict(w, 267256), ("done", "Saving Marshal Ryan", False),
          "names: an item objective for another item (Field Marshal's Log Case) does not keep it")
    sc.eq(quest_rows(BP), [(267256, "done", pos)], "names panel: then it is listed as done")
    # Whole words only (a logbook is not the log); a curly apostrophe counts as a plain one.
    book = [{"title": "Farholde", "isHeader": True},
            {"title": "Old Records", "questID": 950056, "objectives": [], "text": "The field marshal's logbook is lost.",
             "objText": ""}]
    marshal_state(sc, w, quests, book, done, "names, logbook")
    sc.eq(lua_verdict(w, 267256), ("done", "Saving Marshal Ryan", False), "names: a logbook is not the log")
    curly = [{"title": "Farholde", "isHeader": True},
             {"title": "A Quiet Word", "questID": 950055, "objectives": [], "text": "Keep the Field Marshal\u2019s Log safe.",
              "objText": ""}]
    marshal_state(sc, w, quests, curly, done, "names, curly apostrophe", named={267256: "A Quiet Word"})
    sc.eq(lua_verdict(w, 267256), ("keep", "A Quiet Word", False), "names: written with a curly apostrophe, it still names it")
    # A client that fires QUEST_LOG_UPDATE on a selection: one read, no loop.
    M.selectFires = True
    loop = [{"title": "Farholde", "isHeader": True},
            {"title": "The Last Seal", "questID": 950054, "objectives": [], "text": "Return the Field Marshal's Log.", "objText": ""}]
    bag_quests(w, loop)
    M.fire("QUEST_LOG_UPDATE")
    w.settle(1.0)
    n2 = M.questSelects
    w.settle(2.0)
    sc.eq(M.questSelects, n2, "names: a selection that fires QUEST_LOG_UPDATE does not read again and again")
    sc.eq(quest_rows(BP), [], "names panel: The Last Seal keeps it")
    M.selectFires = False
    M.CloseBags()
    w.settle(0.2)
    sc.clean(w, "names")

    # A newer client: selection by quest id, the text read by log line; the selected quest is put back.
    wm, quests = marshal_world(ref, items)
    wm.lua.execute('''
      GetQuestLogSelection, SelectQuestLogEntry = nil, nil
      MOCK.selQ, MOCK.selQSets = 950050, 0
      C_QuestLog.GetSelectedQuest = function() return MOCK.selQ end
      C_QuestLog.SetSelectedQuest = function(q) MOCK.selQSets = MOCK.selQSets + 1; MOCK.selQ = q end
      GetQuestLogQuestText = function(i)
        local q = MOCK.quests[i]
        if not q or q.isHeader then return "", "" end
        return q.text or "", q.objText or ""
      end
    ''')
    marshal_state(sc, wm, quests, seal, done, "names newer client", named={267256: "A Seal for Farholde"})
    sc.eq(lua_verdict(wm, 267256), ("keep", "A Seal for Farholde", False), "names newer client: the text keeps it")
    sc.eq(wm.M.selQ, 950050, "names newer client: the selected quest is put back")
    sc.check(wm.M.selQSets > 0, "names newer client: quests were selected to read them")
    wm.M.CloseBags()
    wm.settle(0.2)
    sc.clean(wm, "names newer client")

    # A client whose selection cannot be read: nothing is selected (it could not be put back);
    # titles and objectives still count.
    wn, quests = marshal_world(ref, items)
    wn.lua.execute("GetQuestLogSelection = nil")
    n0 = wn.M.questSelects
    bag_quests(wn, seal)
    wn.M.questDone = wn.to_lua({q: True for q in done})
    sc.eq(lua_verdict(wn, 267256), ("done", "Saving Marshal Ryan", False), "names, no selection: the text is not read")
    sc.eq(wn.M.questSelects, n0, "names, no selection: no quest is selected")
    bag_quests(wn, farholde((94885, "Field Marshal's Log")))
    sc.eq(lua_verdict(wn, 267256), ("keep", "Field Marshal's Log", False), "names, no selection: a title still keeps it")
    wn.M.CloseBags()
    wn.settle(0.2)
    sc.clean(wn, "names no selection")


def sc_bag_quest_hidden(sc, ref, items):
    """Closed quest log headers and no C_QuestLog.IsOnQuest: what is under them cannot be read,
    so the Field Marshal's Log is never Can drop: the quest after Saving Marshal Ryan may be
    hidden there, and even with the chain done a hidden quest may name it. IsOnQuest finds
    Dying Wish under a closed header; done waits until the headers are open."""
    buy, pos, mu = QDB_COLORS["buy"], QDB_COLORS["pos"], QDB_COLORS["muted"]
    w, quests = marshal_world(ref, items)
    M, ns = w.M, w.ns
    BP = ns.BagPanel
    closed = farholde(collapsed=True)

    def state(done, label, log=closed, log_known=False, in_log=()):
        bag_quests(w, log)
        M.questDone = w.to_lua({q: True for q in done})
        M.fire("QUEST_LOG_UPDATE")
        w.settle(0.5)
        quest_checks(sc, w, quests, set(in_log), set(done), label, log_known=log_known, hidden=True, bag_list=MARSHAL_BAG)
    state((94885, 94887), "hidden, Dying Wish may be under it")
    sc.eq(lua_verdict(w, 267256), ("maybe-hidden", "Dying Wish", False), "hidden: Dying Wish may be under a closed header: not sure")
    sc.eq(quest_tip(w, 0, 1), [("Not sure: some quest log headers are closed", mu)], "hidden: grey not sure line")
    sc.eq(quest_rows(BP), [(267256, "check log", buy)], "hidden panel: the row says check log")
    lines = row_lines(sc, w, 267256) or []
    sc.check("Not sure: some quest log headers are closed. Open them so it can be checked." in lines,
             "hidden panel: the row tooltip says why (%s)" % lines)
    sc.check(not any("Can drop" in l or "destroy" in l for l in lines), "hidden panel: never offered as droppable (%s)" % lines)
    sc.check(BP.note.IsShown(BP.note) and "quest log headers are closed" in BP.note._text, "hidden panel: the footer says so too")
    drop_names(sc, w, "hidden")
    out = [plain(x) for x in w.slash("/gl bags")]
    sc.check(any("[Field Marshal's Log] (check your quest log)" in t for t in out), "hidden /gl bags (%s)" % out)
    sc.check(any("some quest log headers are closed" in t for t in out), "hidden /gl bags: and why (%s)" % out)
    state((94885, 94887, 94892), "hidden, Dying Wish done")
    sc.eq(lua_verdict(w, 267256), ("maybe-hidden", "Delivering Closure", False),
          "hidden: Dying Wish done, Delivering Closure may be under the header: not sure")
    sc.eq(quest_rows(BP), [(267256, "check log", buy)], "hidden panel: still check log, not done")
    # IsOnQuest knows every quest: Dying Wish found under the closed header.
    w.lua.execute("MOCK.onQuest = {}; C_QuestLog.IsOnQuest = function(q) return MOCK.onQuest[q] == true end")
    w.lua.execute("MOCK.onQuest[94892] = true")
    state((94885, 94887), "hidden, IsOnQuest", log_known=True, in_log=(94892,))
    sc.eq(lua_verdict(w, 267256), ("keep", "Dying Wish", False), "hidden: IsOnQuest finds Dying Wish: keep")
    w.lua.execute("MOCK.onQuest[94892] = nil")
    state((94885, 94887, 94892), "hidden, IsOnQuest, Dying Wish done", log_known=True)
    sc.eq(lua_verdict(w, 267256), ("maybe-hidden", "Saving Marshal Ryan", False),
          "hidden: IsOnQuest says Delivering Closure is not taken, but a quest under the closed header may name it: not sure")
    # The header opened, nothing under it names the log: done.
    bag_quests(w, farholde((950051, "Wanted: Gath'Ilzogg")))
    M.fire("QUEST_LOG_UPDATE")
    w.settle(0.5)
    sc.eq(lua_verdict(w, 267256), ("done", "Saving Marshal Ryan", False), "hidden: headers open: can drop")
    sc.eq(quest_rows(BP), [(267256, "done", pos)], "hidden panel: then listed as done")
    w.lua.execute("C_QuestLog.IsOnQuest = nil")
    M.CloseBags()
    w.settle(0.2)
    sc.clean(w, "hidden")


def sc_bag_quest_unsure(sc, ref, items):
    """Where it is not sure, the cleanup never offers a quest item to drop or sell: the Field
    Marshal's Log worth 1c (and a grey one) on Saving Marshal Ryan under a closed header with
    no IsOnQuest; the log while QuestieDB's quests are still being read, and an item QuestieDB
    does not know that a quest's title names; the log while a quest's own text is not in yet
    (not sure yet, read again a moment later; given up after a few tries); a note whose next
    quest QuestieDB has no row for; without QuestieDB, a finished quest's starter under a closed
    header. A trade good a done quest asked for stays on the cheapest list with a header closed
    (it can be had again), and is no old quest item."""
    buy, pos, mu = QDB_COLORS["buy"], QDB_COLORS["pos"], QDB_COLORS["muted"]

    def ids(lst):
        return [lst[i].id for i in range(1, len(lst) + 1)]

    # (1) On Saving Marshal Ryan, its header closed, no IsOnQuest; the log worth 1c.
    w, quests = marshal_world(ref, items, vendor=1)
    M, ns = w.M, w.ns
    BP = ns.BagPanel
    bag_quests(w, farholde(collapsed=True))
    M.questDone = w.to_lua({94885: True})
    M.fire("QUEST_LOG_UPDATE")
    w.settle(0.5)
    sc.eq(lua_verdict(w, 267256), ("maybe-hidden", "Saving Marshal Ryan", False),
          "unsure: Saving Marshal Ryan may be under the closed header: not sure (it was no verdict)")
    sc.eq(quest_tip(w, 0, 1), [("Not sure: some quest log headers are closed", mu)], "unsure: the tooltip says so")
    drop_names(sc, w, "unsure 1c, header closed")
    sc.eq(quest_rows(BP), [(267256, "check log", buy)], "unsure panel: listed as check log")
    # A grey copy: never sold as junk.
    M["items"][267256].quality = 0
    M.bags[0][1].quality = 0
    s = ns.BagScan()
    sc.eq(ids(s.junk), [TOOTH], "unsure grey: the log is not junk (%s)" % ids(s.junk))
    M.OpenMerchant()
    w.settle(0.5)
    sb = BP.sellButton
    sc.eq(sb.text._text if sb.IsVisible(sb) else None, "Sell junk (1, 3c)", "unsure grey: Sell junk counts only the tooth")
    if sb.IsVisible(sb):
        M.click(sb)
        w.settle(0.5)
    sc.eq(sorted(M.sold[i] for i in range(1, len(M.sold) + 1)), [TOOTH], "unsure grey: Sell junk sells the tooth, not the log")
    sc.check(M.bags[0][1] is not None, "unsure grey: the log is still in the bag")
    M.CloseMerchant()
    M.CloseBags()
    w.settle(0.2)
    sc.clean(w, "unsure")

    # (2) QuestieDB's quests still being read (a new QuestieDB, nothing saved): the soulbound log
    # waits; unbound cloth does not; an item QuestieDB does not know stays when a quest's title
    # names it.
    wb = World(ref, items)
    install_questie(wb)
    bag_add_item(wb, 267256, "Field Marshal's Log", 1, 1, **MARSHAL_LOG[5])
    bag_put(wb, 0, 1, 267256, 1, bound=True)
    bag_add_item(wb, TOOTH, "Broken Tooth", 0, 3, classID=15, maxStack=20)
    bag_put(wb, 0, 2, TOOTH, 1)
    bag_add_item(wb, 900610, "Woven Cloth", 1, 25, classID=7, maxStack=20)
    bag_put(wb, 0, 3, 900610, 5)
    bag_quests(wb, LOG_ELSEWHERE)
    s = wb.ns.BagScan()
    sc.eq(wb.ns.QuestIndex.state, "building", "unsure building: the bag scan starts the index")
    s = wb.ns.BagScan()
    sc.check(267256 not in ids(s.drop), "unsure building: the soulbound log is not on the cheapest list (%s)" % ids(s.drop))
    sc.check(900610 in ids(s.drop), "unsure building: unbound cloth still is (%s)" % ids(s.drop))
    sc.check(s.questBuilding is True, "unsure building: the scan says QuestieDB is still being read")
    c = wb.ns.BagPanel.Cheapest(wb.ns.BagPanel, s)
    sc.eq(c.id if c is not None else None, TOOTH, "unsure building: Drop cheapest picks the Broken Tooth")
    out = [plain(x) for x in wb.slash("/gl bags")]
    sc.check(any("still reading Questie's quests" in t for t in out), "unsure building /gl bags: says so (%s)" % out)
    wb.settle(1.0)
    sc.eq(wb.ns.QuestIndex.state, "ready", "unsure building: then the index is ready")
    bag_add_item(wb, 900611, "Sealed Orders", 1, 2, classID=15, maxStack=1)
    bag_put(wb, 0, 4, 900611, 1)
    bag_quests(wb, [{"title": "Farholde", "isHeader": True},
                    {"title": "The Sealed Orders", "questID": 950058, "objectives": []}])
    s = wb.ns.BagScan()
    sc.check(900611 not in ids(s.drop), "unsure: an item QuestieDB does not know, a quest titled with it: kept (%s)" % ids(s.drop))
    bag_quests(wb, LOG_ELSEWHERE)
    s = wb.ns.BagScan()
    sc.check(900611 in ids(s.drop), "unsure: with no quest naming it, it is on the cheapest list (%s)" % ids(s.drop))
    sc.clean(wb, "unsure building")

    # (3) A quest's own text not in yet (right after login): not sure yet, never Can drop; read
    # again a moment later, by itself, and then the quest that names it keeps it.
    w3, quests = marshal_world(ref, items)
    BP3 = w3.ns.BagPanel
    late = [{"title": "Farholde", "isHeader": True},
            {"title": "A Seal for Farholde", "questID": 950050, "objectives": [], "text": "", "objText": ""}]
    bag_quests(w3, late)
    w3.M.questDone = w3.to_lua({q: True for q in (94885, 94887, 94892)})
    w3.M.questSel = 2
    w3.M.fire("QUEST_LOG_UPDATE")
    w3.settle(0.5)
    sc.eq(lua_verdict(w3, 267256), ("maybe-reading", "Saving Marshal Ryan", False),
          "late text: QuestieDB says done, a quest's text is not in yet: not sure yet")
    sc.eq(quest_tip(w3, 0, 1), [("Not sure yet: still reading your quest log", mu)], "late text: the tooltip says so")
    sc.eq(quest_rows(BP3), [(267256, "wait", buy)], "late text panel: the row says wait")
    lines = row_lines(sc, w3, 267256) or []
    sc.check("Not sure yet: still reading your quest log. Check again in a moment." in lines,
             "late text panel: the row tooltip says why (%s)" % lines)
    sc.check(not any("Can drop" in l or "destroy" in l for l in lines), "late text panel: never offered as droppable (%s)" % lines)
    out = [plain(x) for x in w3.slash("/gl bags")]
    sc.check(any("[Field Marshal's Log] (still reading your quest log)" in t for t in out), "late text /gl bags (%s)" % out)
    body = questcheck(sc, w3, "267256", "late text questcheck")
    sc.eq(body[-2:], ["quest log: no quest names it; 1 quest read, some quest text not in yet",
                      "verdict: Not sure yet: still reading your quest log"], "late text: /gl questcheck says so")
    sc.eq(w3.M.questSel, 2, "late text: the player's selection is put back")
    w3.M.quests[2].text = "Abigail Lawson wants the Field Marshal's Log back."
    w3.settle(3.0)
    sc.eq(quest_rows(BP3), [], "late text panel: it looked again by itself; the quest's text keeps the log")
    sc.eq(lua_verdict(w3, 267256), ("keep", "A Seal for Farholde", False), "late text: once the text is in, kept")
    sc.eq(w3.M.questSel, 2, "late text: the selection is still the player's")
    # A quest whose text never comes: read a few times, a few seconds apart, then given up.
    bag_quests(w3, [{"title": "Farholde", "isHeader": True},
                    {"title": "Silent Orders", "questID": 950057, "objectives": [], "text": "", "objText": ""}])
    n0 = w3.M.questSelects
    for _ in range(6):
        lua_verdict(w3, 267256)
        w3.settle(2.1)
    sc.eq(lua_verdict(w3, 267256), ("done", "Saving Marshal Ryan", False),
          "late text: a quest whose text never comes in is given up after a few tries: can drop")
    sc.check(w3.M.questSelects - n0 <= 10, "late text: at most 5 tries (%d selects)" % (w3.M.questSelects - n0))
    w3.M.CloseBags()
    w3.settle(0.2)
    sc.clean(w3, "late text")

    # (4) A note whose next quest QuestieDB has no row for: counted by its id.
    w4 = World(ref, items)
    quests = install_questie(w4)
    torn = [(0, 1, 900608, 1, "Torn Page", {"classID": 15, "bind": 1, "maxStack": 1})]
    bag_add_item(w4, 900608, "Torn Page", 1, 0, **torn[0][5])
    bag_put(w4, 0, 1, 900608, 1, bound=True)
    bag_quests(w4, LOG_ELSEWHERE)
    w4.settle(6.0)
    errand = [{"title": "Zone", "isHeader": True}, {"title": "Mystery Errand", "questID": 950099, "objectives": []}]
    chain_state(sc, w4, quests, torn, errand, (950080,), "torn page, next quest in the log", titles={950099: "Mystery Errand"})
    sc.eq(lua_verdict(w4, 900608), ("keep", "Mystery Errand", False), "torn page: the next quest (no QuestieDB row) in the log: keep")
    sc.eq(quest_tip(w4, 0, 1), [("Keep: needed for Mystery Errand", buy)], "torn page: named from the quest log")
    chain_state(sc, w4, quests, torn, LOG_ELSEWHERE, (950080,), "torn page, next quest not taken")
    sc.eq(lua_verdict(w4, 900608), ("maybe-next", None, False), "torn page: the next quest not taken: may be needed")
    sc.eq(quest_tip(w4, 0, 1), [("May be needed for the next quest", mu)], "torn page: grey maybe line")
    chain_state(sc, w4, quests, torn, LOG_ELSEWHERE, (950080, 950099), "torn page, next quest done")
    sc.eq(lua_verdict(w4, 900608), ("done", "The Torn Page", False), "torn page: the next quest done: can drop")
    sc.clean(w4, "torn page")

    # (5) Without QuestieDB: the letter whose quest is done is listed, but not under a closed header.
    w5 = World(ref, items)
    bag_add_item(w5, 900501, "Sealed Letter", 1, 0, classID=12, bind=4, maxStack=1, startsQuest=950001)
    bag_put(w5, 0, 1, 900501, 1)
    w5.M.questDone[950001] = True
    bag_quests(w5, [{"title": "Uldaman", "isHeader": True}])
    s = w5.ns.BagScan()
    sc.eq([(s.quest[i].id, s.quest[i].why) for i in range(1, len(s.quest) + 1)], [(900501, "done")],
          "no questie: the letter whose quest is done is listed")
    bag_quests(w5, [{"title": "Uldaman", "isHeader": True, "isCollapsed": True}])
    s = w5.ns.BagScan()
    sc.check(s.questPartial is True and len(s.quest) == 0,
             "no questie: under a closed header it is not listed as done (%s)" % [s.quest[i].id for i in range(1, len(s.quest) + 1)])
    # A quest whose text is not in yet: not listed as done until it is (it may name the letter).
    bag_quests(w5, [{"title": "Uldaman", "isHeader": True},
                    {"title": "The Courier", "questID": 950059, "objectives": [], "text": "", "objText": ""}])
    s = w5.ns.BagScan()
    sc.eq(len(s.quest), 0, "no questie: a quest's text not in yet: the letter is not listed as done")
    sc.check(s.questReading is True, "no questie: the scan says quest text is still being read")
    w5.M.quests[2].text = "Speak with the courier in Ironforge."
    w5.settle(2.5)
    s = w5.ns.BagScan()
    sc.eq([(s.quest[i].id, s.quest[i].why) for i in range(1, len(s.quest) + 1)], [(900501, "done")],
          "no questie: once the text is in (it does not name the letter), the letter is listed as done")
    sc.clean(w5, "unsure no questie")

    # (5b) A Horde character: no quest QuestieDB knows uses the log for them, but a quest in
    # their log titled with it still keeps it.
    wh = World(ref, items, faction="Horde")
    wh.M.race = wh.to_lua(["Orc", "Orc", 2])
    install_questie(wh)
    bag_add_item(wh, 267256, "Field Marshal's Log", 1, 0, **MARSHAL_LOG[5])
    bag_put(wh, 0, 1, 267256, 1, bound=True)
    bag_quests(wh, LOG_ELSEWHERE)
    wh.settle(6.0)
    sc.eq(lua_verdict(wh, 267256), None, "unsure horde: not their chain, no verdict")
    bag_quests(wh, farholde((960001, "Field Marshal's Log")))
    sc.eq(lua_verdict(wh, 267256), ("keep", "Field Marshal's Log", False),
          "unsure horde: a quest in their log titled with it keeps it")
    sc.clean(wh, "unsure horde")

    # (6) Cloth a done quest asked for, a header closed: not sure, but it can be had again, so it
    # stays on the cheapest list and is no old quest item; the log (a quest gave it) is held.
    w6, quests = marshal_world(ref, items)
    bag_add_item(w6, 900610, "Woven Cloth", 1, 25, classID=7, maxStack=20)
    bag_put(w6, 0, 3, 900610, 5)
    bag_quests(w6, farholde(collapsed=True))
    w6.M.questDone = w6.to_lua({q: True for q in (950095, 94885, 94887, 94892)})
    w6.M.fire("QUEST_LOG_UPDATE")
    w6.settle(0.5)
    sc.eq(lua_verdict(w6, 900610), ("maybe-hidden", "Cloth for the Guard", False), "cloth: a header closed: not sure")
    s = w6.ns.BagScan()
    sc.check(900610 in ids(s.drop), "cloth: still on the cheapest list (%s)" % ids(s.drop))
    sc.eq([(s.quest[i].id, s.quest[i].why, s.quest[i].maybe) for i in range(1, len(s.quest) + 1)], [(267256, "maybe", "hidden")],
          "cloth: no old quest item; the log is listed as not sure")
    bag_quests(w6, farholde((950051, "Wanted: Gath'Ilzogg")))
    s = w6.ns.BagScan()
    sc.check(900610 in ids(s.drop), "cloth: headers open, done: on the cheapest list")
    sc.eq([(s.quest[i].id, s.quest[i].why) for i in range(1, len(s.quest) + 1)], [(267256, "done")],
          "cloth: headers open: only the log is listed, as done")
    w6.M.CloseBags()
    w6.settle(0.2)
    sc.clean(w6, "cloth")


# The owner's case (bag-questie-books): the cleanup listed Conjurer's Codex and RwlRwlRwlRwl! as
# "check log" old quest items. They are Stormwind library books: soulbound, unique, worth
# nothing and not marked as quest items; you find them in the world and hand them in to a
# librarian, so their quests are never in your log. The Field Marshal's Log (Saving Marshal Ryan
# done, Dying Wish not taken) is the item whose answer does depend on the log.
BOOK_BAG = [
    (0, 1, 220353, 1, "Conjurer's Codex", {"classID": 15, "bind": 1, "maxStack": 1}),
    (0, 2, 215822, 1, "RwlRwlRwlRwl!", {"classID": 15, "bind": 1, "maxStack": 1}),
    (0, 3, 267256, 1, "Field Marshal's Log", {"classID": 15, "bind": 1, "maxStack": 1}),
]
BOOKS = {220353: ("Conjurer's Codex", 81956, 45, 1), 215822: ("RwlRwlRwlRwl!", 79952, 35, 2)}
BOOK_HUMAN, BOOK_ORC, BOOK_MAGE = ["Human", "Human", 1], ["Orc", "Orc", 2], ["Mage", "MAGE", 8]
# Made up turn-ins (QDB_QUESTS 950200-950207): only a mage's, only the Alliance's, one another quest
# shuts, a breadcrumb's, one with a top level (39), and a letter its own quest gives you.
TURNIN_BAG = [
    (0, 1, 900620, 1, "Mage's Folio", {"classID": 12, "bind": 4, "maxStack": 1}),
    (0, 2, 900621, 1, "Archive Notes", {"classID": 12, "bind": 4, "maxStack": 1}),
    (0, 3, 900622, 1, "Lost Page", {"classID": 12, "bind": 4, "maxStack": 1}),
    (0, 4, 900623, 1, "Librarian's Note", {"classID": 12, "bind": 4, "maxStack": 1}),
    (0, 5, 900624, 3, "Novice Token", {"classID": 12, "bind": 4, "maxStack": 20}),
    (0, 6, 900625, 1, "Letter for Brant", {"classID": 12, "bind": 4, "maxStack": 1}),
]


def books_world(ref, items, level, race=BOOK_HUMAN, cls=BOOK_MAGE, faction="Alliance", vendor=0, bag_list=BOOK_BAG,
                no_npcs=False, lua=None, extra=None):
    """A character of `level` with these items (books worth `vendor` copper), a Broken Tooth,
    QuestieDB loaded (with the `extra` quest rows, then the `lua` code run) and its index made,
    the cleanup panel open."""
    w = World(ref, items, faction=faction)
    w.M.race, w.M["class"], w.M.level = w.to_lua(race), w.to_lua(cls), level
    quests = install_questie(w, no_npcs=no_npcs, extra=extra)
    if lua:
        w.lua.execute(lua)
    for bag, slot, iid, count, name, fields in bag_list:
        bag_add_item(w, iid, name, 1, vendor if iid in BOOKS else 0, **fields)
        bag_put(w, bag, slot, iid, count, bound=fields.get("bind") == 1)
    bag_add_item(w, TOOTH, "Broken Tooth", 0, 3, classID=15, maxStack=20)
    bag_put(w, 0, 8, TOOTH, 1)
    bag_quests(w, LOG_ELSEWHERE)
    w.settle(6.0)
    w.M.OpenBags(1)
    w.settle(0.2)
    w.M.click(w.ns.BagPanel.tab)
    w.settle(0.2)
    return w, quests


def scan_ids(s, key):
    lst = s[key]
    return [lst[i].id for i in range(1, len(lst) + 1)]


def sc_bag_questie_books(sc, ref, items):
    """The Stormwind library books (the owner's screenshot): a quest you can still do asks for
    them, so they are Keep (turn in for the quest, at the librarian), never on the old quest
    items list or the cheapest list, closed quest log headers or not, for a level 30, 40 or 60
    mage (a level 45 quest is for later); /gl questcheck says why. Once handed in: Can drop
    (not sure again under closed headers, as any done item). A Horde mage hands them in at Owen
    Thadd; a QuestieDB without NPC reads says no one. The Field Marshal's Log beside them still
    depends on the log (check log under closed headers)."""
    buy, pos, mu = QDB_COLORS["buy"], QDB_COLORS["pos"], QDB_COLORS["muted"]
    chain_done = (94885, 94887)
    for level in (30, 40, 60):
        lab = "books, level %d" % level
        w, quests = books_world(ref, items, level)
        M, ns = w.M, w.ns
        BP = ns.BagPanel
        sc.eq(ns.QuestIndex.state, "ready", "%s: the index is ready" % lab)

        def state(log, done, label, **kw):
            return chain_state(sc, w, quests, BOOK_BAG, log, done, label, race=1, cls=8, level=level, **kw)

        def books_kept(label):
            s = ns.BagScan()
            for iid, (name, q, ql, slot) in BOOKS.items():
                sc.eq(lua_verdict(w, iid), ("keep-turnin", name, False), "%s: %s is Keep (a turn-in)" % (label, name))
                tip = quest_tip(w, 0, slot)
                sc.eq(tip, [("Keep: turn in for %s at Garion Wendell" % name, buy)],
                      "%s: %s tooltip, gold turn in line" % (label, name))
                sc.check(not any("Not sure" in t or "Can drop" in t for t, _ in tip),
                         "%s: %s tooltip never says not sure or can drop" % (label, name))
                sc.check(iid not in scan_ids(s, "quest"), "%s: %s is no old quest item" % (label, name))
                sc.check(iid not in scan_ids(s, "drop"), "%s: %s is not on the cheapest list" % (label, name))
                sc.check(bag_row_for(BP, iid) is None, "%s: %s has no row in the panel" % (label, name))
            out = [plain(x) for x in w.slash("/gl bags")]
            sc.check(not any("Conjurer's Codex" in t or "RwlRwlRwlRwl!" in t for t in out),
                     "%s: /gl bags names neither book (%s)" % (label, out))
        # Headers open: the books are kept; the log may be needed for Dying Wish.
        rows = state(LOG_ELSEWHERE, chain_done, lab + ", headers open")
        books_kept(lab + ", headers open")
        sc.eq(rows, [(267256, "maybe", "Dying Wish")], "%s, headers open: only the log is listed (maybe)" % lab)
        sc.eq(quest_rows(BP), [(267256, "maybe", buy)], "%s, headers open: the panel shows the log only" % lab)
        body = questcheck(sc, w, "220353", lab + " questcheck")
        later = " (level 45: for later)" if level < 45 else ""
        sc.eq(body, ["quest check: [Conjurer's Codex] (item 220353, Use effect no), Bags.lua 2026-11-19b",
                     "QuestieDB: 81956 Conjurer's Codex (needs it): not started",
                     "quest log: no quest names it; 1 quest read",
                     "verdict: Keep: turn in for Conjurer's Codex at Garion Wendell",
                     "why: 81956 Conjurer's Codex is not done and you can still do it%s, so it is kept; "
                     "your quest log does not change that" % later], "%s: /gl questcheck says why it is kept" % lab)
        # Headers closed, no IsOnQuest (the owner's screenshot): the books stay Keep; the log is check log.
        closed = farholde(collapsed=True)
        rows = state(closed, chain_done, lab + ", headers closed", log_known=False, hidden=True)
        books_kept(lab + ", headers closed")
        sc.eq(rows, [(267256, "maybe", "Dying Wish")], "%s, headers closed: only the log is listed" % lab)
        sc.eq(lua_verdict(w, 267256), ("maybe-hidden", "Dying Wish", False), "%s, headers closed: the log is not sure" % lab)
        sc.eq(quest_rows(BP), [(267256, "check log", buy)], "%s, headers closed: the panel says check log for the log only" % lab)
        later = " (level 35: for later)" if level < 35 else ""
        sc.eq(questcheck(sc, w, "RwlRwlRwlRwl!", lab + " questcheck closed"),
              ["quest check: [RwlRwlRwlRwl!] (item 215822, Use effect no), Bags.lua 2026-11-19b",
               "QuestieDB: 79952 RwlRwlRwlRwl! (needs it): headers closed",
               "quest log: no quest names it; 0 quests read, some headers closed",
               "verdict: Keep: turn in for RwlRwlRwlRwl! at Garion Wendell",
               "why: 79952 RwlRwlRwlRwl! is not done and you can still do it%s, so it is kept; "
               "your quest log does not change that" % later], "%s: /gl questcheck with headers closed" % lab)
        # Handed in: Can drop, and listed as done.
        handed = chain_done + (81956, 79952)
        rows = state(LOG_ELSEWHERE, handed, lab + ", handed in")
        for iid, (name, q, ql, slot) in BOOKS.items():
            sc.eq(lua_verdict(w, iid), ("done", name, False), "%s, handed in: %s can drop" % (lab, name))
            sc.eq(quest_tip(w, 0, slot), [("Can drop: done with %s" % name, pos)], "%s, handed in: %s tooltip" % (lab, name))
            sc.check((iid, "done", name) in rows, "%s, handed in: %s is listed as done (%s)" % (lab, name, rows))
        sc.eq(quest_rows(BP)[:2], [(220353, "done", pos), (215822, "done", pos)],
              "%s, handed in: the panel lists both books as done" % lab)
        sc.eq(questcheck(sc, w, "220353", lab + " questcheck done")[1:],
              ["QuestieDB: 81956 Conjurer's Codex (needs it): done",
               "quest log: no quest names it; 1 quest read",
               "verdict: Can drop: done with Conjurer's Codex"], "%s: /gl questcheck once handed in" % lab)
        # Handed in, headers closed: a hidden quest may name them, so not sure (as any done item).
        state(closed, handed, lab + ", handed in, headers closed", log_known=False, hidden=True)
        for iid, (name, q, ql, slot) in BOOKS.items():
            sc.eq(lua_verdict(w, iid), ("maybe-hidden", name, False), "%s, handed in, headers closed: %s not sure" % (lab, name))
        M.CloseBags()
        w.settle(0.2)
        sc.clean(w, lab)

    # A Horde (Orc) mage hands them in at Owen Thadd; the Field Marshal's Log is not their chain.
    wh, quests = books_world(ref, items, 40, race=BOOK_ORC, faction="Horde")
    chain_state(sc, wh, quests, BOOK_BAG, farholde(collapsed=True), (), "books, horde, headers closed", race=2, cls=8,
                level=40, log_known=False, hidden=True)
    for iid, (name, q, ql, slot) in BOOKS.items():
        sc.eq(quest_tip(wh, 0, slot), [("Keep: turn in for %s at Owen Thadd" % name, buy)], "books, horde: %s at Owen Thadd" % name)
    sc.eq(lua_verdict(wh, 267256), None, "books, horde: the log is not their chain")
    wh.M.CloseBags()
    wh.settle(0.2)
    sc.clean(wh, "books horde")

    # A QuestieDB with no NPC reads: still Keep, without naming who takes it.
    wn, quests = books_world(ref, items, 40, no_npcs=True)
    chain_state(sc, wn, quests, BOOK_BAG, LOG_ELSEWHERE, (), "books, no NPC reads", race=1, cls=8, level=40, npcs=False)
    sc.eq(quest_tip(wn, 0, 1), [("Keep: turn in for Conjurer's Codex", buy)], "books, no NPC reads: no one named")
    wn.M.CloseBags()
    wn.settle(0.2)
    sc.clean(wn, "books no npcs")

    # An NPC read that fails: still Keep, no one named, and QuestieDB stays in use.
    we, quests = books_world(ref, items, 40, lua='LibQuestieDB.Npc.Get = function() error("npc read failed") end')
    chain_state(sc, we, quests, BOOK_BAG, LOG_ELSEWHERE, (), "books, NPC read fails", race=1, cls=8, level=40, npcs=False)
    sc.eq(quest_tip(we, 0, 1), [("Keep: turn in for Conjurer's Codex", buy)], "books, NPC read fails: no one named")
    sc.eq(we.ns.QuestIndex.state, "ready", "books, NPC read fails: QuestieDB is still used")
    we.M.CloseBags()
    we.settle(0.2)
    sc.clean(we, "books npc read fails")

    # Worth 1c at a vendor: still never on the cheapest list while kept (soulbound: it cannot be
    # had again); once handed in it is fair game there.
    wv, quests = books_world(ref, items, 60, vendor=1)
    chain_state(sc, wv, quests, BOOK_BAG, farholde(collapsed=True), chain_done, "books 1c, headers closed", race=1, cls=8,
                level=60, log_known=False, hidden=True)
    s = wv.ns.BagScan()
    sc.check(not any(i in scan_ids(s, "drop") for i in BOOKS), "books 1c: not on the cheapest list (%s)" % scan_ids(s, "drop"))
    c = wv.ns.BagPanel.Cheapest(wv.ns.BagPanel, s)
    sc.eq(c.id if c is not None else None, TOOTH, "books 1c: Drop cheapest picks the Broken Tooth")
    chain_state(sc, wv, quests, BOOK_BAG, LOG_ELSEWHERE, chain_done + (81956, 79952), "books 1c, handed in", race=1, cls=8,
                level=60)
    s = wv.ns.BagScan()
    sc.check(all(i in scan_ids(s, "drop") for i in BOOKS), "books 1c, handed in: on the cheapest list (%s)" % scan_ids(s, "drop"))
    wv.M.CloseBags()
    wv.settle(0.2)
    sc.clean(wv, "books 1c")


def sc_bag_questie_turnins(sc, ref, items):
    """Turn-ins a quest you can still do asks for are Keep; Can drop says plainly whether its
    quest is done or shut for you (another quest shut it, its breadcrumb's quest is done, you
    are past its top level); a turn-in only a mage (or only the Alliance) can do has no
    QuestieDB verdict for a warrior (or a Horde character) and is listed by the quest log's
    words; a letter its own quest gives you is not kept (taking the quest gives a new one)."""
    buy, pos, mu = QDB_COLORS["buy"], QDB_COLORS["pos"], QDB_COLORS["muted"]
    # A human warrior, level 30.
    w, quests = books_world(ref, items, 30, cls=["Warrior", "WARRIOR", 1], bag_list=TURNIN_BAG)
    M, ns = w.M, w.ns
    BP = ns.BagPanel

    def state(log, done, label, level=30, **kw):
        M.level = level
        return chain_state(sc, w, quests, TURNIN_BAG, log, done, label, race=1, cls=1, level=level, **kw)
    rows = state(LOG_ELSEWHERE, (), "turn-ins, warrior 30")
    sc.eq(lua_verdict(w, 900620), None, "turn-ins: a mage's folio has no verdict for a warrior")
    sc.eq(quest_tip(w, 0, 1), [], "turn-ins: and no quest line")
    sc.eq(lua_verdict(w, 900621), ("keep-turnin", "Archive Notes", False), "turn-ins: an Alliance turn-in for a human: keep")
    sc.eq(quest_tip(w, 0, 2), [("Keep: turn in for Archive Notes at Garion Wendell", buy)], "turn-ins: at the Alliance librarian")
    sc.eq(quest_tip(w, 0, 3), [("Keep: turn in for The Lost Page at Archive Lectern", buy)],
          "turn-ins: handed in at an object, it names the object")
    sc.eq(quest_tip(w, 0, 4), [("Keep: turn in for A Note for the Librarian", buy)], "turn-ins: a breadcrumb's note, no one named")
    sc.eq(quest_tip(w, 0, 5), [("Keep: turn in for Novice Tokens", buy)], "turn-ins: under the top level: keep")
    sc.eq(lua_verdict(w, 900625), ("open-fresh", "A Letter for Brant", False), "turn-ins: a letter its own quest gives you")
    sc.eq(quest_tip(w, 0, 6), [("Can drop: taking A Letter for Brant gives you a new one", mu)], "turn-ins: the letter's line")
    sc.eq(sorted(rows), sorted([(900620, "none", None), (900625, "open", "A Letter for Brant")]),
          "turn-ins: only the folio (quest log words) and the letter are listed (%s)" % rows)
    qr = dict((r[0], r[1:]) for r in quest_rows(BP))
    sc.eq(qr.get(900620), ("not needed", mu), "turn-ins panel: the folio, not needed (from the quest log)")
    sc.eq(qr.get(900625), ("not started", mu), "turn-ins panel: the letter, not started")
    lines = row_lines(sc, w, 900625) or []
    sc.check("Can drop: taking A Letter for Brant gives you a new one." in lines, "turn-ins panel: the letter's row says why (%s)" % lines)
    sc.check("Can drop: taking A Letter for Brant gives you a new one" not in lines,
             "turn-ins panel: the item tooltip's own quest line is left out of the row's (%s)" % lines)
    # Burn the Pages done (it shuts The Lost Page), The Librarian's Request done (the breadcrumb is shut).
    rows = state(LOG_ELSEWHERE, (950203, 950205), "turn-ins, shut")
    sc.eq(lua_verdict(w, 900622), ("done-shut", "The Lost Page", False), "turn-ins: an exclusive quest done shuts it: can drop")
    sc.eq(quest_tip(w, 0, 3), [("Can drop: The Lost Page is no longer open to you", pos)], "turn-ins: it says shut, not done")
    sc.eq(lua_verdict(w, 900623), ("done-shut", "A Note for the Librarian", False), "turn-ins: the breadcrumb's quest done: can drop")
    sc.check((900622, "done", "The Lost Page") in rows and (900623, "done", "A Note for the Librarian") in rows,
             "turn-ins: both listed (%s)" % rows)
    qr = dict((r[0], r[1:]) for r in quest_rows(BP))
    sc.eq(qr.get(900622), ("shut", pos), "turn-ins panel: the page says shut")
    lines = row_lines(sc, w, 900622) or []
    sc.check("Can drop: The Lost Page is no longer open to you." in lines, "turn-ins panel: the page's row says why (%s)" % lines)
    out = [plain(x) for x in w.slash("/gl bags")]
    sc.check(any("[Lost Page] (no longer open: The Lost Page)" in t for t in out), "turn-ins /gl bags: shut (%s)" % out)
    body = questcheck(sc, w, "900622", "turn-ins questcheck shut")
    sc.eq(body[1:], ["QuestieDB: 950202 The Lost Page (needs it): no longer open to you",
                     "quest log: no quest names it; 1 quest read",
                     "verdict: Can drop: The Lost Page is no longer open to you"], "turn-ins: /gl questcheck says shut")
    # Level 39: at Novice Tokens' top level it is still open (QuestieDB: the highest level it can be done at).
    state(LOG_ELSEWHERE, (), "turn-ins, warrior 39", level=39)
    sc.eq(lua_verdict(w, 900624), ("keep-turnin", "Novice Tokens", False), "turn-ins: at its top level: still keep")
    # Level 40: past Novice Tokens' top level (39).
    state(LOG_ELSEWHERE, (), "turn-ins, warrior 40", level=40)
    sc.eq(lua_verdict(w, 900624), ("done-shut", "Novice Tokens", False), "turn-ins: past its top level: can drop")
    # The letter's quest taken: kept for it.
    state(qlog(950207, "A Letter for Brant"), (), "turn-ins, letter taken")
    sc.eq(lua_verdict(w, 900625), ("keep", "A Letter for Brant", False), "turn-ins: the letter while its quest is in the log")
    M.CloseBags()
    w.settle(0.2)
    sc.clean(w, "turn-ins")

    # A human mage: the folio is theirs.
    wm, quests = books_world(ref, items, 30, bag_list=TURNIN_BAG)
    chain_state(sc, wm, quests, TURNIN_BAG, LOG_ELSEWHERE, (), "turn-ins, mage", race=1, cls=8, level=30)
    sc.eq(quest_tip(wm, 0, 1), [("Keep: turn in for A Mage's Folio at Garion Wendell", buy)], "turn-ins: a mage keeps the folio")
    wm.M.CloseBags()
    wm.settle(0.2)
    sc.clean(wm, "turn-ins mage")

    # Cloth a quest you have not taken asks for: Keep, but cloth the auction house trades can be
    # had again, so it stays on the cheapest list; a weave nobody sells there is held, and so is
    # traded cloth that is soulbound or binds when picked up (worth 10c each at a vendor).
    priced = [i for i in other_items(ref, items, 40, avoid=SIDEBAR_WATCH) if ref.items[i]["cheapest"] >= 3]
    if sc.check(len(priced) >= 3, "turn-ins cloth: priced items to test with"):
        p, pb, pp = priced[:3]
        wc = World(ref, items)
        quests = install_questie(wc, extra={950208: {"name": "Cloth for the Quartermaster",
                                                     "objectives": qobj(p, 900612, pb, pp)}})
        bag_add_item(wc, 900612, "Unpriced Weave", 1, 25, classID=7, maxStack=20)
        bag_put(wc, 0, 1, 900612, 5)
        bag_put(wc, 0, 2, p, 5)
        wc.M["items"][pb].vendor, wc.M["items"][pp].vendor = 10, 10
        wc.M["items"][pp].bind = 1
        bag_put(wc, 0, 3, pb, 5, bound=True)
        bag_put(wc, 0, 4, pp, 5)
        bag_quests(wc, LOG_ELSEWHERE)
        wc.settle(6.0)
        s = wc.ns.BagScan()
        for i, how in ((pb, "soulbound"), (pp, "binds when picked up")):
            sc.eq(lua_verdict(wc, i), ("keep-turnin", "Cloth for the Quartermaster", False), "turn-ins cloth: %s cloth is Keep" % how)
            sc.check(i not in scan_ids(s, "drop") and i not in scan_ids(s, "quest"),
                     "turn-ins cloth: %s traded cloth is held (%s)" % (how, scan_ids(s, "drop")))
        sc.eq(lua_verdict(wc, p), ("keep-turnin", "Cloth for the Quartermaster", False), "turn-ins cloth: the priced cloth is Keep")
        sc.eq(lua_verdict(wc, 900612), ("keep-turnin", "Cloth for the Quartermaster", False), "turn-ins cloth: the weave too")
        sc.check(p in scan_ids(s, "drop"), "turn-ins cloth: cloth the auction house trades stays on the cheapest list (%s)"
                 % scan_ids(s, "drop"))
        sc.check(900612 not in scan_ids(s, "drop") and 900612 not in scan_ids(s, "quest"),
                 "turn-ins cloth: the weave nobody sells is held (%s)" % scan_ids(s, "drop"))
        sc.eq(quest_tip(wc, 0, 1), [NO_LISTINGS, ("Keep: turn in for Cloth for the Quartermaster", buy)],
              "turn-ins cloth: the weave's tooltip says keep")
        wc.M.questDone[950208] = True
        s = wc.ns.BagScan()
        sc.check(900612 in scan_ids(s, "drop"), "turn-ins cloth: once handed in, the weave is on the cheapest list")
        sc.check(pb in scan_ids(s, "drop") and pp in scan_ids(s, "drop"),
                 "turn-ins cloth: once handed in, the bound cloth is on the cheapest list too (%s)" % scan_ids(s, "drop"))
        sc.clean(wc, "turn-ins cloth")

    # An Orc mage: the Alliance's archive notes are not theirs.
    wo, quests = books_world(ref, items, 30, race=BOOK_ORC, faction="Horde", bag_list=TURNIN_BAG)
    rows = chain_state(sc, wo, quests, TURNIN_BAG, LOG_ELSEWHERE, (), "turn-ins, orc mage", race=2, cls=8, level=30)
    sc.eq(lua_verdict(wo, 900621), None, "turn-ins: an Alliance turn-in has no verdict for a Horde character")
    sc.check((900621, "none", None) in rows, "turn-ins: it is listed by the quest log's words (%s)" % rows)
    wo.M.CloseBags()
    wo.settle(0.2)
    sc.clean(wo, "turn-ins orc")



