def en_fits(key, subs):
    """Whether a list entry's recipe takes every one of these weapon subclasses."""
    spell = EN_KEY_SPELL.get(key) or int(key[1:])
    mask = EN_SPELL_SUBS[spell]
    return all(mask >> x & 1 for x in subs)


# Ranged weapons of a class that only pulls with them: Top 5 only, with this grey note under the scopes.
EN_PULL = {("ranged", "melee"), ("ranged", "agility"), ("ranged", "tank")}
EN_PULL_NOTE = "(pulling only)"

def en_pick(group, role, cls, tab, sub=None, loc=None):
    """The reviewed list for a slot group and role: role/CLASStab, then role/CLASS, then role/dagger
    (a dagger, subclass 15, that is not off-hand only), then the role's own (as Enchants.lua's
    pickFor). (list, up, at, key) or None."""
    g = EN_LISTS.get(group)
    if not g:
        return None
    keys = []
    if cls and tab:
        keys.append("%s/%s%s" % (role, cls, tab))
    if cls:
        keys.append("%s/%s" % (role, cls))
    if sub == 15 and loc != "INVTYPE_WEAPONOFFHAND":
        keys.append(role + "/dagger")
    keys.append(role)
    for rk in keys:
        if rk in g:
            return g[rk], EN_UP.get(group, {}).get(rk, []), EN_AT.get(group, {}).get(rk, {}), rk
    return None


def en_usable(key, level, skills, sub, ilvl=None):
    lvl, prof, rank, subs = EN_REQ.get(key, (None, None, None, None))
    if lvl and level < lvl:
        return False
    if prof and (skills or {}).get(prof, 0) < rank:
        return False
    if key in EN_ILVL and ilvl is not None and ilvl < EN_ILVL[key]:
        return False
    if EN_HOW.get(key) == "lw" and sub is not None and sub not in (1, 2, 3, 4):
        return False
    if subs and sub is not None and sub not in subs:
        return False
    return True


def en_spec(group, role, cls, tab, level=60, skills=None, sub=None, current=None, ilvl=None, loc=None):
    """The options the product asks for, best first, before any cut to Top 2 or Top 5: the usable
    entries of the role's list above the item's enchant (current), nothing for an "up" enchant or
    the first entry, an "at" enchant cuts before its place, any other: the whole list."""
    rec = en_pick(group, role, cls, tab, sub, loc)
    if rec is None:
        return []
    lst, up, at, _ = rec
    stop = None
    if current:
        ids = [EN_IDS[k] for k in lst]
        if current in up:
            return []
        if current in ids:
            stop = ids.index(current) + 1
        elif current in at:
            stop = at[current]
    out = []
    for i, k in enumerate(lst, 1):
        if stop is not None and i >= stop:
            break
        if en_usable(k, level, skills, sub, ilvl):
            out.append(k)
    return out


def en_note(group, role, cls, tab):
    """The grey note under a list's lines (a pull list's), or None."""
    rec = en_pick(group, role, cls, tab)
    return EN_PULL_NOTE if rec and (group, rec[3]) in EN_PULL else None


def en_copper(prices, key):
    """(copper, every mat priced) as Enchants.lua's costOf: an upgrade item's own AH value, else (a
    blacksmith's item nobody lists, an enchant) its mats' and fee."""
    item = EN_ITEM_OF.get(key)
    if item is not None:
        v = prices.get(item, 0)
        if v > 0 or key not in EN_M:
            return max(v, 0), True
    copper, full = EN_FEE.get(key, 0), True
    for mid, n in EN_M.get(key, []):
        v = prices.get(mid, 0)
        if v > 0:
            copper += v * n
        else:
            full = False
    return copper, full


def en_five(keys, prices, n=5):
    """Top n of the options (best first): Top 2 the first two; Top 5 the first two, then up to three
    later ones that cost less than both of them with every mat priced (budget options: the 2nd's full
    price is the limit when it is lower than the best's), while the best has an AH price. prices False:
    no price data (the list order)."""
    if prices is None:
        raise AssertionError("en_five: pass the world's prices (False: no price data)")
    if n <= 2 or not prices or not keys:
        return keys[:n]
    limit = en_copper(prices, keys[0])[0]
    if limit <= 0:
        return keys[:n]
    if len(keys) > 1:
        c2, full2 = en_copper(prices, keys[1])
        if full2 and 0 < c2 < limit:
            limit = c2
    out = keys[:2]
    for k in keys[2:]:
        c, full = en_copper(prices, k)
        if len(out) < n and full and 0 < c < limit:
            out.append(k)
    return out


def en_top(group, role, cls, tab, n=2, prices=None, **kw):
    """What the tooltip shows: a pull list its best only, else en_five of the options (Top 5 needs
    the prices)."""
    spec = en_spec(group, role, cls, tab, **kw)
    rec = en_pick(group, role, cls, tab, kw.get("sub"), kw.get("loc"))
    if rec and (group, rec[3]) in EN_PULL:
        return spec[:1]
    return spec[:n] if n <= 2 else en_five(spec, prices, n)


def en_source_mats():
    """Enchants.lua's mat names, read from the source (id -> name)."""
    src = open(os.path.join(ADDON, "Enchants.lua"), "rb").read().decode("ascii")
    block = src.split("local MATS = {", 1)[1].split("\n}", 1)[0]
    return {int(m.group(1)): m.group(2) for m in re.finditer(r'\[(\d+)\]\s*=\s*"([^"]*)"', block)}


# Quest turn-ins and other bind-on-pickup mats: never on the auction house.
EN_BOUND = (12938, 12753, 12735, 11951, 11563, 8411, 11952, 11752, 8424)


def en_test_price(mid):
    return 500 + (mid * 7919) % 40000   # made up, copper


def en_set_market(text, mid, value):
    pat = re.compile(r'(\[%d\]\s*=\s*")((?:[^"\\\n]|\\.)*)"' % mid)

    def one(m):
        f = m.group(2).split("|")
        f[2] = str(value)
        if value == 0:
            f[1] = "0"
        return m.group(1) + "|".join(f) + '"'
    span = block_span(text, "items")
    a, b = span
    return text[:a] + pat.sub(one, text[a:b], count=1) + text[b:]


_EN_DATA = {}


def en_data(ref, unlisted=()):
    """The data text with every enchant mat and upgrade item priced (made-up prices where the data has
    none) except the unlisted ones, and {item id: AH value} as the addon reads it."""
    unlisted = tuple(sorted(set(unlisted) | set(EN_BOUND)))
    key = (DATA_FILE, unlisted)
    if key in _EN_DATA:
        return _EN_DATA[key]
    text = open(DATA_FILE, "rb").read().decode("utf-8")
    prices, add = {}, []
    names = dict(en_source_mats())
    names.update(EN_ITEMS)
    for mid, name in sorted(names.items()):
        it = ref.items.get(mid)
        if mid in unlisted:
            prices[mid] = 0
            if it:
                text = en_set_market(text, mid, 0)
            continue
        if it and it["market"] > 0:
            prices[mid] = it["market"]
            continue
        v = en_test_price(mid)
        prices[mid] = v
        if it:
            text = en_set_market(text, mid, v)
        else:
            add.append('[%d] = "%s|%d|%d|5|1|%d|0|;;|;;",' % (mid, name, v, v, v))
    text = re.sub(r"(?m)^([ \t]*items[ \t]*=[ \t]*\{[ \t]*\r?\n)",
                  lambda m: m.group(1) + "".join("    %s\n" % ln for ln in add), text, count=1)
    _EN_DATA[key] = (text, prices)
    return text, prices


def en_round(c):
    if c >= 100000:
        return (c + 5000) // 10000 * 10000
    if c >= 100:
        return (c + 50) // 100 * 100
    return c


def en_entry(w, key):
    """An entry as Enchants.lua has it."""
    e = w.ns.Enchants.DATA.enchants[key]
    m = [int(e.m[i]) for i in range(1, len(e.m) + 1)] if e.m else []
    subs = [int(e.subs[i]) for i in range(1, len(e.subs) + 1)] if e.subs else None
    return {"n": e.n, "id": e.id, "m": list(zip(m[0::2], m[1::2])), "lvl": e.lvl, "fee": e.fee, "item": e.item,
            "how": e.how, "prof": e.prof, "rank": e.rank, "subs": subs, "ilvl": e.ilvl}


def en_by_mats(prices, key):
    """Whether an option's cost is its mats' (an enchant, or a blacksmith's item nobody lists)."""
    item = EN_ITEM_OF.get(key)
    if item is None:
        return True
    return key in EN_M and (prices or {}).get(item, 0) <= 0


def en_cost(prices, key):
    """(right text, right colour) of an option's line."""
    names = en_source_mats()
    if not en_by_mats(prices, key):
        v = prices.get(EN_ITEM_OF[key], 0)
        if v <= 0:
            return "not on AH", "muted"
        return "~" + money_icons(en_round(v)), "white"
    copper, missing = EN_FEE.get(key, 0), []
    for mid, n in EN_M.get(key, []):
        v = prices.get(mid, 0)
        if v > 0:
            copper += v * n
        else:
            missing.append("%d %s" % (n, names[mid]))
    if copper <= 0:
        return "no AH price", "muted"
    s = "~" + money_icons(en_round(copper))
    if len(missing) == 1:
        s += " + " + missing[0]
    elif missing:
        s += " + more"
    return s, "white"


def en_mats(key):
    names = en_source_mats()
    parts = ["%d %s" % (n, names[mid]) for mid, n in EN_M.get(key, [])]
    if EN_FEE.get(key):
        parts.append(money_text(EN_FEE[key]) + " quest fee")
    return ", ".join(parts)


EN_HOW_TEXT = {"lw": "Leatherworking kit, use it on the item", "eng": "Engineering scope, use it on the item",
               "bs": "Your Blacksmithing: use it on the item"}


def en_detail(prices, key):
    """The grey line under an option: the mats, or how you get the upgrade."""
    how = EN_HOW.get(key)
    if how is None:
        return en_mats(key)
    if how == "bs" and en_by_mats(prices, key):
        return "Your Blacksmithing: make it from " + en_mats(key)
    return EN_HOW_TEXT[how]


def en_want(w, prices, keys, full=True, note=None):
    """The enchant lines for these options: [(left, right)]; prices None = no price data; the note
    (a pull list's) goes under them, in compact mode too."""
    out = []
    for label, key in zip(EN_LABELS, keys):
        out.append((label + EN_NAMES[key], en_cost(prices, key)[0] if prices is not None else None))
        if full:
            out.append(("  " + en_detail(prices, key), None))
    if note and keys:
        out.append((note, None))
    return out


def en_want_for(w, prices, keys, group, role, cls, tab, full=True):
    """en_want with the list's note (a warrior's or rogue's ranged weapon)."""
    return en_want(w, prices, keys, full, en_note(group, role, cls, tab))


def en_is_label(l):
    return bool(l) and l.startswith(EN_LABELS)


def en_block(w, tt):
    """Our enchant lines: from the first Best enchant / 2nd / ... line to the end."""
    lines = w.lines(tt)
    for i, (l, r) in enumerate(lines):
        if en_is_label(l):
            return lines[i:]
    return []


def en_count(w, tt):
    """How many options the tooltip names."""
    return sum(1 for l, _ in w.all_lines(tt) if en_is_label(l))


def en_world(ref, items, unlisted=(), cls="WARRIOR", points=(31, 5, 0), level=60, mode="forever", bags=True, top=2, **kw):
    """bags: the checks on bag, bank and link tooltips (and the older client's) run with those places
    added to the addon's E.SHOW (in the game only worn gear gets the lines); False: the game's own
    places, worn gear only (enchants-worn-only). top: the checks run with Top 2 set (as after /gl
    enchants top2: they were written for the two best) unless the saved settings say; None: the
    addon's own default, Top 5 (enchants-top-default)."""
    if kw.get("data_src") is None:
        kw["data_src"], prices = en_data(ref, unlisted)
    else:
        prices = None
    w = World(ref, items, **kw)
    for iid, (name, loc, cid, sub, q, _) in EN_GEAR.items():
        bag_add_item(w, iid, name, q, 125, classID=cid, subclassID=sub, equipLoc=loc, maxStack=1, bind=1,
                     itemLevel=EN_GEAR_ILVL.get(iid, 60))
    w.M.equipped = w.lua.table()
    w.M.inspected = w.lua.table()
    if bags:
        for where in ("bag", "link", "script"):
            w.ns.Enchants.SHOW[where] = True
    if top is not None and "enchantsTop" not in (kw.get("saved") or {}):
        w.ns.settings.enchantsTop = top
        w.ns.Enchants.RefreshToggle()   # the Top button's words
    en_player(w, cls, points, mode, level)
    return w, prices



def en_player(w, cls, points, mode="forever", level=60):
    M = w.M
    M["class"] = w.to_lua([EN_CLASS[cls][0], cls, EN_CLASS[cls][1]])
    M.talents.mode = mode
    M.talents.points = w.to_lua(list(points))
    M.level = level
    w.ns.Enchants.Invalidate()


def en_skills(w, ranks, mode="forever", collapsed=False, event=True):
    """The player's skill lines (professions by skill line id: rank), as the Skills tab lists them."""
    names = {164: "Blacksmithing", 202: "Engineering", 165: "Leatherworking", 333: "Enchanting", 186: "Mining"}
    rows = [{"name": "Class Skills", "header": True}, {"id": 44, "name": "Axes", "rank": 150},
            {"name": "Professions", "header": True}]
    for sid, rank in sorted(ranks.items()):
        rows.append({"id": sid, "name": names.get(sid, "Skill %d" % sid), "rank": rank})
    w.M.skills = w.to_lua(rows)
    w.M.skillMode = mode
    w.M.skillsCollapsed = collapsed
    if event:
        w.M.fire("SKILL_LINES_CHANGED")


def en_hover(w, how, iid, enchant=None, slot=None):
    """Shows an item's tooltip the way the game does from a place; returns the tooltip."""
    M, g = w.M, w.g
    tt = g.GameTooltip
    if how == "link":
        tt = g.ItemRefTooltip
    elif how == "shopping":
        tt = g.ShoppingTooltip1
    tt.SetOwner(tt, g.UIParent, "ANCHOR_NONE")
    if how == "bag":
        bag_put(w, 0, 1, iid, 1, enchant=enchant, bound=True)
        tt.SetBagItem(tt, 0, 1)
    elif how in ("equipped", "bank", "inspect"):
        slot = slot or (40 if how == "bank" else EN_GEAR[iid][5])
        s = w.to_lua({"itemID": iid, "bound": True})
        s.enchant = enchant
        (M.inspected if how == "inspect" else M.equipped)[slot] = s
        tt.SetInventoryItem(tt, "target" if how == "inspect" else "player", slot)
    elif how in ("link", "gamelink", "shopping"):
        tt.SetHyperlink(tt, M.ItemLink(iid, None, None, enchant))
    elif how == "byid":
        tt.SetItemByID(tt, iid)
    elif how == "ahrow":   # an auction house browse row
        tt.SetItemKey(tt, iid)
    else:
        raise AssertionError(how)
    return tt


def en_styles_ok(sc, w, tt, label, stale=False):
    """Our enchant lines: the text colour (cost white, or grey with no AH price or old prices),
    mats grey and wrapped, all on the game's normal font."""
    st = tooltip_styles(w, tt)
    n = len(tt._lines)
    start = None
    for i in range(1, n + 1):
        if en_is_label(tt._lines[i].left or ""):
            start = i
            break
    if not sc.check(start is not None, "%s: has enchant lines" % label):
        return
    bad = []
    for i in range(start, n + 1):
        ln, s = tt._lines[i], st[i - 1]
        is_mats = (ln.left or "").startswith("  ") or ln.left == EN_PULL_NOTE
        want_l = "muted" if is_mats else "text"
        want_r = None if ln.right is None else ("muted" if stale or ln.right in ("no AH price", "not on AH") else "white")
        if s is None or (s[0], s[1]) != (want_l, want_r) or s[2] != "GameTooltipText" or s[3] != 12:
            bad.append((i, ln.left, s))
        if is_mats and ln.wrap is not True:
            bad.append((i, ln.left, "not wrapped"))
    sc.eq(bad, [], "%s: enchant line colours, wrap and font" % label)


def en_lua_list(t):
    return [t[i] for i in range(1, len(t) + 1)] if t is not None else []


def en_value_families(keys):
    """Pairs (earlier, later) in a list whose Forever stats have the same kinds (so they compare
    stat by stat) where the later one has more of every stat: a list out of value order."""
    bad = []
    for i, a in enumerate(keys):
        for b in keys[i + 1:]:
            sa, sb = EN_STATS.get(a), EN_STATS.get(b)
            if not sa or not sb or set(sa) != set(sb):
                continue
            if all(sb[k] >= sa[k] for k in sa) and any(sb[k] > sa[k] for k in sa):
                bad.append((a, b))
    return bad


# rankedboost's Forever stat weights (its enchant pages for wowf 1.60.1, "Scored for <spec>: +N <stat> x W"),
# averaged over the specs of a role: attack power units for melee and hunters, spell power for casters
# and healers, Stamina for tanks. melee: Arms, Fury, Retribution, Enhancement; agility: the rogues (feral
# druids have their own weapon lists); tank: Protection warrior first (Stamina 1, Strength 0.5); armor
# 0.06 a point (Superior Defense's 70 armor scores 3.43). Weapon damage: 14 / weapon speed (2H 3.6s:
# 3.89, rankedboost's Superior Impact 35 for 9), rogues 5.19 (rankedboost). Weapon procs: proc_dps
# (EN_PROCS, 14 attack power a damage a second). Haste, dodge, resistances and spikes have no weight:
# they are placed by hand and not checked here. Tanks keep rankedboost's weapon damage 1.0 (at 2.6 sec;
# 14 x 0.25 / 2.6 = 1.35 by the attack power model) and the 2H tank list (mostly bears) 0: nothing a
# Top 5 shows changes with it.
EN_WEIGHTS = {
    "melee": {"str": 2.05, "agi": 0.92, "int": 0.37, "spi": 0.015, "sta": 0.2, "ap": 1, "armor": 0, "health": 0.02,
              "mana": 0, "sp": 0, "heal": 0, "spelldmg": 0, "def": 0, "weapondmg": 5.4, "rangeddmg": 0},
    "agility": {"str": 1.0, "agi": 1.56, "int": 0, "spi": 0, "sta": 0.18, "ap": 1, "armor": 0, "health": 0.018,
                "mana": 0, "sp": 0, "heal": 0, "spelldmg": 0, "def": 0, "weapondmg": 5.19, "rangeddmg": 0},
    "hunter": {"str": 0, "agi": 2.39, "int": 1.12, "spi": 0.04, "sta": 0.2, "ap": 1, "armor": 0, "health": 0.02,
               "mana": 0.05, "sp": 0, "heal": 0, "spelldmg": 0, "def": 0, "weapondmg": 0, "rangeddmg": 4.67},
    "tank": {"str": 0.5, "agi": 0.35, "int": 0, "spi": 0, "sta": 1.0, "ap": 0.25, "armor": 0.06, "health": 0.1,
             "mana": 0, "sp": 0.08, "heal": 0, "spelldmg": 0, "def": 1.38, "weapondmg": 1.0, "rangeddmg": 0},
    "caster": {"str": 0, "agi": 0, "int": 0.47, "spi": 0.03, "sta": 0.15, "ap": 0, "armor": 0, "health": 0.015,
               "mana": 0.025, "sp": 1.0, "heal": 0, "spelldmg": 1.0, "def": 0, "weapondmg": 0, "rangeddmg": 0},
    "healer": {"str": 0, "agi": 0, "int": 0.93, "spi": 0.2, "sta": 0.12, "ap": 0, "armor": 0, "health": 0.012,
               "mana": 0.05, "sp": 1.0, "heal": 1.0, "spelldmg": 0, "def": 0, "weapondmg": 0, "rangeddmg": 0},
}
EN_TOL = 1.10   # the weights are estimates: an entry may trail one below it by up to 10%
# Rage users: warriors in every role (the /WARRIOR lists) and bears (tank/DRUID; the 2H tank list is
# checked as theirs too). Rage comes from the melee damage they deal (7.5 x damage / 176 at level 47,
# / 230.6 at 60: a point from about 23 to 31 damage) and a point buys about 6 to 8 damage (Heroic
# Strike, Mortal Strike, Maul): melee damage is worth about a quarter more. Strength, Agility, attack
# power and weapon damage bring that rage; a proc's fire or shadow damage none: it counts 1 / 1.25.
# Rogues and cats (energy), paladins, shamans and hunters (mana): no rage, no change.
EN_RAGE_FACTOR = 1.25


def en_rage(rk):
    """Whether a list key is a rage user's: role/WARRIOR (any role, a tree too) or tank/DRUID."""
    m = re.match(r"^([a-z]+)/([A-Z]+)", rk)
    return bool(m) and (m.group(2) == "WARRIOR" or (m.group(2) == "DRUID" and m.group(1) == "tank"))


def en_weights(group, rk, speed=None):
    """The role's weights for a slot group; speed: weapon damage on a weapon of this speed (the
    weight x the group's reference speed / speed: +N weapon damage adds N / speed a second)."""
    role = rk.split("/")[0]
    w = dict(EN_WEIGHTS[role])
    if group == "weapon2h":
        w["weapondmg"] = 3.89 if role == "melee" else 0
    if (role in ("agility", "tank") and rk.endswith("/DRUID")) or (group == "weapon2h" and role == "agility"):
        w["weapondmg"] = 0   # feral forms do not use the weapon's damage
        if role == "agility":
            w.update({"str": 2.2, "agi": 1.91, "sta": 0.2})   # Feral Cat
        else:
            w.update({"str": 0.4, "agi": 0.342, "sta": 1.0, "armor": 0.11})   # Feral Bear
    if role == "healer" and (group == "shield" or "/PALADIN" in rk or "/SHAMAN" in rk):
        w["spi"] = 0.03   # paladins and shamans (who carry the shields) get little from Spirit
    # A proc's damage a second at 14 attack power each, for the roles that fight in melee (feral forms
    # too: Blizzard said on September 30, 2026 that weapon procs work while shapeshifted). Hunters,
    # casters and healers: 0 (their weapon damage counts 0 as well).
    w["proc_dps"] = EN_AP_PER_DPS * w["ap"] if role in ("melee", "agility", "tank") else 0
    if en_rage(rk):
        w["proc_dps"] /= EN_RAGE_FACTOR   # no rage from a proc's damage
    if speed is not None and w["weapondmg"] and group in EN_REF_SPEED:
        w["weapondmg"] *= EN_REF_SPEED[group] / speed
    return w


def en_score(stats, w):
    if not stats:
        return None
    total = 0.0
    for k, v in stats.items():
        if k not in w:
            return None
        total += w[k] * v
    return total


def en_value_problems(group, rk, keys, up, at, speed=None):
    """Where a list breaks value order for its role (EN_WEIGHTS, with EN_TOL slack): a later entry worth
    more than an earlier one, an at place on the wrong side of an entry, an up enchant worth less than
    the best, or an enchant the slot can take (EN_KNOWN) that is not placed and beats a listed one.
    speed: a weapon list valued on a weapon of this speed (weapon damage and per-hit procs); a
    dagger list without one: on a 1.8 sec dagger."""
    if speed is None and rk.endswith("/dagger"):
        speed = EN_DAGGER_REF
    w = en_weights(group, rk, speed)
    known = en_known(group, speed)
    ids = [EN_IDS[k] for k in keys]
    sc = [en_score(known.get(i) or EN_STATS.get(k), w) for i, k in zip(ids, keys)]
    bad = []
    for i in range(len(keys)):
        for j in range(i + 1, len(keys)):
            if sc[i] is not None and sc[j] is not None and sc[j] > sc[i] * EN_TOL + 1e-9:
                bad.append("%s (%.2f) above %s (%.2f)" % (keys[i], sc[i], keys[j], sc[j]))
    for aid, n in sorted(at.items()):
        s = en_score(known.get(aid), w)
        if s is None:
            continue
        for i, k in enumerate(keys):
            if sc[i] is None:
                continue
            if i < n - 1 and s > sc[i] * EN_TOL + 1e-9:
                bad.append("at %d = %d (%.2f) is worth more than %s (%.2f)" % (aid, n, s, k, sc[i]))
            if i >= n - 1 and sc[i] > s * EN_TOL + 1e-9:
                bad.append("at %d = %d (%.2f) is worth less than %s (%.2f)" % (aid, n, s, k, sc[i]))
    scored = [x for x in sc if x is not None]
    for u in up:
        s = en_score(known.get(u), w)
        if s is not None and scored and s * EN_TOL + 1e-9 < max(scored):
            bad.append("up %d (%.2f) is worth less than the best (%.2f)" % (u, s, max(scored)))
    for c in sorted(set(known) - set(ids) - set(up) - set(at)):
        s = en_score(known[c], w)
        if s is not None and scored and s > min(scored) * EN_TOL + 1e-9:
            bad.append("%d (%.2f) is not placed but beats a listed one (%.2f)" % (c, s, min(scored)))
    return bad


def sc_enchants_data(sc, ref, items):
    """The enchant table: every pick exists and is the reviewed one, every mat has the game's name,
    nothing doubled, value order, plain ASCII."""
    w, _ = en_world(ref, items)
    D = w.ns.Enchants.DATA
    names = en_source_mats()
    lua_mats = {int(k): v for k, v in D.mats.items()}
    sc.eq(lua_mats, names, "enchants data: the source's mat table is the one the addon loads")
    sc.check(len(lua_mats) >= 60, "enchants data: %d mats" % len(lua_mats))
    sc.eq(len(set(lua_mats.values())), len(lua_mats), "enchants data: no two mat ids share a name")
    for mid, nm in lua_mats.items():
        sc.check(nm and all(32 <= ord(c) < 127 for c in nm) and nm == nm.strip(), "enchants data: mat %d name %r" % (mid, nm))
    # The game's names: the price data's and the AH item list's, where they have the item.
    seen = 0
    for mid, nm in sorted(list(lua_mats.items()) + list(EN_ITEMS.items())):
        js = items.get(str(mid))
        if js and js.get("name"):
            seen += 1
            sc.eq(nm, js["name"], "enchants data: item %d has the auction house's name" % mid)
        it = ref.items.get(mid)
        if it and known_name(it["name"]):
            seen += 1
            sc.eq(nm, it["name"], "enchants data: item %d has the price data's name" % mid)
    sc.check(seen >= 1, "enchants data: %d item names checked against the item lists" % seen)
    ench = {k: en_entry(w, k) for k in D.enchants.keys()}
    sc.eq(sorted(ench), sorted(EN_NAMES), "enchants data: exactly the enchants the picks use")
    used_mats = set()
    for k, e in sorted(ench.items()):
        sc.eq(e["n"], EN_NAMES.get(k), "enchants data: %s's name" % k)
        sc.eq(e["id"], EN_IDS.get(k), "enchants data: %s is enchant %s in item links" % (k, EN_IDS.get(k)))
        sc.eq(e["m"], [tuple(x) for x in EN_M.get(k, [])], "enchants data: %s's mats and counts" % k)
        sc.check(all(mid in lua_mats and n >= 1 for mid, n in e["m"]), "enchants data: %s's mats are in MATS" % k)
        used_mats.update(mid for mid, _ in e["m"])
        sc.eq(len(set(mid for mid, _ in e["m"])), len(e["m"]), "enchants data: %s lists each mat once" % k)
        sc.eq((e["lvl"], e["prof"], e["rank"], e["subs"]), EN_REQ.get(k, (None, None, None, None)),
              "enchants data: %s's level, profession and weapons" % k)
        sc.eq(e["fee"], EN_FEE.get(k), "enchants data: %s's quest fee" % k)
        sc.eq(e["ilvl"], EN_ILVL.get(k), "enchants data: %s's lowest item level" % k)
        sc.eq((e["item"], e["how"]), (EN_ITEM_OF.get(k), EN_HOW.get(k)), "enchants data: %s's upgrade item" % k)
        sc.check(e["item"] is not None or e["m"], "enchants data: %s has mats or is an item" % k)
        sc.check(e["lvl"] is None or 1 <= e["lvl"] <= 60, "enchants data: %s level %r" % (k, e["lvl"]))
        sc.check((e["prof"] is None) == (e["rank"] is None) and (e["prof"] is None or e["how"] == "bs"),
                 "enchants data: %s: a profession comes with its rank, on Blacksmithing items" % k)
    sc.eq(sorted(used_mats), sorted(lua_mats), "enchants data: every mat in MATS is used")
    # The level each quest asks: Mathredis's Lesser Arcanums 50, Lydros's (7483-7485 in Forever's QuestieDB) 58.
    sc.eq({k: ench[k]["lvl"] for k in ench if k.startswith("a")},
          {"a11622": 50, "a11642": 50, "a11645": 50, "a11647": 50, "a11648": 50, "a18329": 58, "a18330": 58,
           "a18331": 58}, "enchants data: the Arcanums' levels are their quests'")
    # The armor kits' and scopes' levels are their items' (ItemSparse.RequiredLevel), the spikes need Blacksmithing.
    sc.eq({k: ench[k]["lvl"] for k in ench if k[0] in "ki"},
          {"k2304": 1, "k2313": 5, "k4265": 20, "k8173": 30, "k15564": 40, "k252436": 15, "k252437": 15, "k252452": 30,
           "k252453": 30, "k252462": 40, "k252463": 40, "k252487": 50, "k252488": 50, "i4405": 5, "i4406": 10,
           "i4407": 20, "i10546": 30, "i10548": 40}, "enchants data: kits and scopes need their items' levels")
    # The kits' item-level floors (SpellItemEnchantment.ItemLevelMin): Heavy 15, Thick 25, Rugged 35, the
    # Mystic and Forceful kits of each tier the same; Light and Medium have none.
    sc.eq({k: ench[k]["ilvl"] for k in ench if ench[k]["ilvl"] is not None},
          {"k4265": 15, "k252452": 15, "k252453": 15, "k8173": 25, "k252462": 25, "k252463": 25, "k15564": 35,
           "k252487": 35, "k252488": 35}, "enchants data: the armor kits' item-level floors")
    sc.eq({k: (ench[k]["prof"], ench[k]["rank"]) for k in ench if k[0] == "b"},
          {"b6042": (164, 150), "b7967": (164, 215), "b12645": (164, 250), "b6043": (164, 165)},
          "enchants data: shield spikes and the counterweight need their Blacksmithing ranks")
    sigs = [(e["id"], tuple(e["m"]), e["item"]) for e in ench.values()]
    sc.eq(len(set(sigs)), len(sigs), "enchants data: no enchant listed twice")
    used = set()
    for g, recs in D.picks.items():
        sc.check(g in EN_GROUPS, "enchants data: group %s" % g)
        for rk, rec in recs.items():
            m = re.match(r"^([a-z]+)(?:/([A-Z]+)([1-3])?|/dagger)?$", rk)
            sc.check(m and m.group(1) in EN_ROLES and (m.group(2) is None or m.group(2) in EN_CLASS),
                     "enchants data: %s.%s is a role (and class, tree)" % (g, rk))
            keys = en_lua_list(rec)
            sc.eq(keys, EN_LISTS.get(g, {}).get(rk), "enchants data: %s.%s is the reviewed list" % (g, rk))
            sc.check(keys and all(k in ench for k in keys), "enchants data: %s.%s picks exist (%s)" % (g, rk, keys))
            used.update(keys)
            ids = [ench[k]["id"] for k in keys if k in ench]
            sc.eq(len(set(ids)), len(ids), "enchants data: %s.%s: no enchant id twice" % (g, rk))
            sc.eq([i for i in ids if i in EN_OUT_IDS], [], "enchants data: %s.%s: only formulas in the game now" % (g, rk))
            up = en_lua_list(rec.up)
            at = {int(a): int(b) for a, b in rec.at.items()} if rec.at else {}
            sc.eq(up, EN_UP.get(g, {}).get(rk, []), "enchants data: %s.%s's up" % (g, rk))
            sc.eq(at, EN_AT.get(g, {}).get(rk, {}), "enchants data: %s.%s's at" % (g, rk))
            sc.check(not (set(up) & set(ids)) and not (set(at) & set(ids)) and not (set(up) & set(at)),
                     "enchants data: %s.%s up / at / picks do not overlap" % (g, rk))
            sc.check(all(1 <= p <= len(keys) + 1 for p in at.values()), "enchants data: %s.%s at places %s" % (g, rk, at))
            sc.eq(en_value_families(keys), [], "enchants data: %s.%s is in value order" % (g, rk))
            sc.eq(en_value_problems(g, rk, keys, up, at), [],
                  "enchants data: %s.%s is in value order for the role's stat weights" % (g, rk))
            sc.eq(rec.pull is True, (g, rk) in EN_PULL, "enchants data: %s.%s is a pull list or not" % (g, rk))
            if g in ("weapon", "weapon2h", "ranged"):
                need = {"weapon": EN_1H_SUBS, "weapon2h": EN_2H_SUBS, "ranged": (2, 3, 18)}[g]
                sc.eq([k for k in keys if not en_fits(k, need) and EN_REQ.get(k, (0, 0, 0, None))[3] is None], [],
                      "enchants data: %s.%s: every recipe takes these weapons (SpellEquippedItems)" % (g, rk))
            sc.check(not rk.endswith("/dagger") or (g == "weapon" and rk.split("/")[0] in EN_WEIGHTS),
                     "enchants data: %s.%s: dagger lists are one-hand weapon lists for a role" % (g, rk))
            for speed in en_speeds(g, rk):
                sc.eq(en_value_problems(g, rk, keys, up, at, speed), [],
                      "enchants data: %s.%s is in value order on a %.1f sec weapon" % (g, rk, speed))
    sc.eq(sorted(used), sorted(ench), "enchants data: every enchant is a pick")
    sc.eq(sorted(D.picks.keys()), sorted(EN_LISTS), "enchants data: every slot group")
    for g in sorted(EN_LISTS):
        sc.eq(sorted(D.picks[g].keys()) if D.picks[g] else [], sorted(EN_LISTS[g]),
              "enchants data: %s has every reviewed list (and no other)" % g)
    # Every slot group and role picks the list the product asks for (one class per role and tree).
    pick = w.lua.eval("function(E, g, r, c, t) local P = E.DATA.picks[g]; if not P then return nil end "
                      "return P[r .. '/' .. c .. t] or P[r .. '/' .. c] or P[r] end")
    for cls, trees in EN_TREES.items():
        for tab, (_, role) in enumerate(trees, 1):
            for g in EN_GROUPS:
                got = en_lua_list(pick(w.ns.Enchants, g, role, cls, tab))
                rec = en_pick(g, role, cls, tab)
                sc.eq(got, rec[0] if rec else [], "enchants data: %s %s (%s) %s" % (cls, trees[tab - 1][0], role, g))
    # Slots with no option and the groups the slots map to.
    for iid in EN_NONE:
        sc.eq(w.ns.Enchants.SlotGroup(iid) if EN_GEAR[iid][4] != 0 else None, None,
              "enchants data: %s gets no group" % EN_GEAR[iid][0])
    for g, iid in EN_GROUP_ITEM:
        sc.eq(w.ns.Enchants.SlotGroup(iid), g, "enchants data: %s is in %s" % (EN_GEAR[iid][0], g))
    sc.eq(w.ns.Enchants.SlotGroup(R.LINEN), None, "enchants data: cloth is not gear")
    src = open(os.path.join(ADDON, "Enchants.lua"), "rb").read()
    sc.check(all(b < 128 for b in src) and b"\xe2\x80" not in src, "enchants data: Enchants.lua is plain ASCII")
    sc.clean(w)


def en_sub(iid):
    return EN_GEAR[iid][3]


def en_ilvl(iid):
    return EN_GEAR_ILVL.get(iid, 60)


def en_arms(iid, **kw):
    """An Arms warrior's options on a test item (the harness's default player)."""
    g = w_group(iid)
    return en_spec(g, "melee", "WARRIOR", 1, sub=en_sub(iid), ilvl=en_ilvl(iid), **kw)


def w_group(iid):
    for g, i in EN_GROUP_ITEM:
        if i == iid:
            return g
    raise AssertionError(iid)


def sc_enchants_bag(sc, ref, items):
    """Bags show the two best enchants (their mats and their AH value); only upgrades; nothing when the best is on."""
    w, prices = en_world(ref, items)
    g = w.g
    E = w.ns.Enchants
    sc.check(not any(iid in ref.items for iid in EN_GEAR), "enchants bag: the test gear has no price data")
    top2 = en_arms(990102)[:2]
    sc.eq(top2, ["s20034", "s13898"], "enchants bag: an Arms warrior's Greatsword: Crusader, then Fiery Weapon (rage)")
    for enchant, want, why in ((None, top2, "no enchant"), (1898, top2, "Lifestealing on (the 4th)"),
                               (1900, [], "Crusader on: nothing"), (8215, [], "2H Strength +25 counts as the best"),
                               (803, ["s20034"], "Fiery Weapon on (the 2nd): the best only"),
                               (963, top2, "Greater Impact on (the 6th)"), (15, top2, "another enchant"),
                               (2646, top2, "Agility +25 (placed above Lesser Impact +5)"),
                               (2564, top2, "Agility +15 (placed below Minor Impact +4)"),
                               (36, top2, "Enchant: Fiery Blaze (every entry beats it)")):
        sc.eq(en_arms(990102, current=enchant)[:2], want, "enchants bag: the rule's own answer, %s" % why)
        tt = en_hover(w, "bag", 990102, enchant)
        sc.eq(en_block(w, tt), en_want(w, prices, want), "enchants bag: Greatsword, %s" % why)
        # Soulbound gear with no prices: our lines are the only ones (no Goblin Ledger header).
        sc.eq(w.lines(tt), en_want(w, prices, want), "enchants bag: soulbound gear, %s: only our lines" % why)
    tt = en_hover(w, "bag", 990102)
    en_styles_ok(sc, w, tt, "enchants bag: Greatsword")
    # One build a show: hovering again, refreshing and re-setting reuse the lines.
    b0 = E.builds
    for _ in range(5):
        tt = en_hover(w, "bag", 990102)
        tt.RefreshData(tt)
    sc.eq(en_count(w, tt), 2, "enchants bag: a refresh does not add the lines twice")
    sc.eq(E.builds, b0, "enchants bag: the lines are built once and reused")
    for iid in EN_NONE:
        tt = en_hover(w, "bag", iid)
        sc.eq(en_count(w, tt), 0, "enchants bag: nothing on %s" % EN_GEAR[iid][0])
    for iid in sorted(ref.items)[:SAMPLE]:
        tt = g.GameTooltip
        tt.SetOwner(tt, g.UIParent, "ANCHOR_NONE")
        w.put_bag(0, 2, iid, 1)
        tt.SetBagItem(tt, 0, 2)
        if en_count(w, tt):
            sc.check(False, "enchants bag: no enchant lines on non-gear item %d" % iid)
            break
    else:
        sc.check(True, "enchants bag: no enchant lines on any non-gear item")
    # Tradeable gear with no prices: the "no recent listings" line, then ours.
    cloak = ["s1219587", "s13419"]
    w.M["items"][990108].bind = 2
    bag_put(w, 0, 3, 990108, 1)
    tt = g.GameTooltip
    tt.SetOwner(tt, g.UIParent, "ANCHOR_NONE")
    tt.SetBagItem(tt, 0, 3)
    sc.eq(w.lines(tt), [("Goblin Ledger: no recent listings", None)] + en_want(w, prices, cloak),
          "enchants bag: unpriced tradeable cloak: no recent listings, then the two best")
    # Priced gear with the bigger verdict lines: our price lines are as before, ours follow at the normal size.
    big = None
    for iid in sorted(ref.items):
        if iid in ROLE_IDS() or iid in en_source_mats() or iid in EN_ITEMS:
            continue
        tt.SetOwner(tt, g.UIParent, "ANCHOR_NONE")
        tt.SetItemByID(tt, iid)
        if big_fontstrings(w, tt):
            big = iid
            break
    if sc.check(big is not None, "enchants bag: a priced item with big verdict lines"):
        w.put_bag(1, 1, big, 1)
        tt.SetOwner(tt, g.UIParent, "ANCHOR_NONE")
        tt.SetBagItem(tt, 1, 1)
        before, st_before, big_before = w.lines(tt), tooltip_styles(w, tt), big_fontstrings(w, tt)
        it = w.M["items"][big]
        it.equipLoc, it.classID, it.subclassID = "INVTYPE_CLOAK", 4, 1
        w.ns.Enchants.Invalidate()   # an item's slot never changes in game: it is remembered
        tt.SetOwner(tt, g.UIParent, "ANCHOR_NONE")
        tt.SetBagItem(tt, 1, 1)
        after = w.lines(tt)
        sc.eq(after[:len(before)], before, "enchants bag: priced cloak keeps its price lines")
        sc.eq(after[len(before):], en_want(w, prices, cloak), "enchants bag: priced cloak: then the two best")
        sc.eq(tooltip_styles(w, tt)[:len(st_before)], st_before, "enchants bag: priced cloak: price line styles unchanged")
        sc.eq(big_fontstrings(w, tt), big_before, "enchants bag: priced cloak: the same lines are big")
        en_styles_ok(sc, w, tt, "enchants bag: priced cloak")
        it.equipLoc, it.classID, it.subclassID = None, None, None
    sc.clean(w)


def sc_enchants_equipped(sc, ref, items):
    """Worn gear: the same options as in the bags; nothing for someone you inspect."""
    w, prices = en_world(ref, items)
    for enchant in (None, 2563, 1900, 803, 36, 8215, 1896, 2646, 15, 0):
        want = en_arms(990102, current=enchant or None)[:2]
        tt = en_hover(w, "equipped", 990102, enchant)
        sc.eq(w.lines(tt), en_want(w, prices, want), "enchants worn: Greatsword, enchant %s" % enchant)
        tb = en_hover(w, "bag", 990102, enchant)
        sc.eq(en_block(w, tb), en_want(w, prices, want), "enchants worn: Greatsword, enchant %s: the same in a bag" % enchant)
    tt = en_hover(w, "equipped", 990102)
    en_styles_ok(sc, w, tt, "enchants worn: Greatsword")
    tt = en_hover(w, "inspect", 990102)
    sc.check(len(w.all_lines(tt)) > 0 and en_count(w, tt) == 0, "enchants worn: an inspected Greatsword gets nothing")
    tt = en_hover(w, "bank", 990102)
    sc.eq(en_block(w, tt), en_want(w, prices, en_arms(990102)[:2]), "enchants worn: a bank slot")
    # Shield and off-hand weapon (slot 17); a Prot warrior.
    en_player(w, "WARRIOR", (5, 5, 31))
    tt = en_hover(w, "equipped", 990105)
    sc.eq(w.lines(tt), en_want(w, prices, ["s20017", "s13817"]), "enchants worn: a tank's shield (no blacksmith)")
    tt = en_hover(w, "equipped", 990105, 929)
    sc.eq(w.lines(tt), en_want(w, prices, ["s20017"]), "enchants worn: shield with Stamina +7: the best only")
    tt = en_hover(w, "equipped", 990102)
    sc.eq(w.lines(tt), en_want(w, prices, ["s20034", "s13898"]), "enchants worn: a tank's 2H: Crusader, then Fiery Weapon (rage)")
    # A rogue's off-hand dagger.
    en_player(w, "ROGUE", (0, 31, 20))
    tt = en_hover(w, "equipped", 990104)
    sc.eq(w.lines(tt), en_want(w, prices, ["s13898", "s20032"]), "enchants worn: rogue off-hand dagger: Fiery Weapon, Lifestealing")
    tt = en_hover(w, "equipped", 990104, 803)
    sc.eq(en_count(w, tt), 0, "enchants worn: rogue dagger with Fiery Weapon: nothing")
    tt = en_hover(w, "equipped", 990104, 1898)
    sc.eq(w.lines(tt), en_want(w, prices, ["s13898"]), "enchants worn: rogue dagger with Lifestealing: the best only")
    tt = en_hover(w, "equipped", 990104, 1900)
    sc.eq(w.lines(tt), en_want(w, prices, ["s13898", "s20032"]), "enchants worn: rogue dagger with Crusader (the 4th)")
    tt = en_hover(w, "equipped", 990105)
    sc.eq(en_count(w, tt), 0, "enchants worn: a rogue's shield (cannot carry one): nothing")
    for iid in EN_NONE:
        tt = en_hover(w, "equipped", iid)
        sc.eq(en_count(w, tt), 0, "enchants worn: nothing on %s" % EN_GEAR[iid][0])
    # Every class and tree, Top 2 and Top 5: the picks on each slot of worn gear and in the bags.
    for top in (2, 5):
        w.slash("/gl enchants top%d" % top)
        for cls, trees in EN_TREES.items():
            for tab, (tname, role) in enumerate(trees, 1):
                pts = [0, 0, 0]
                pts[tab - 1] = 31
                pts[tab % 3] = 11
                en_player(w, cls, pts)
                for g, iid in EN_GROUP_ITEM:
                    want = en_top(g, role, cls, tab, top, prices=prices, sub=en_sub(iid), ilvl=en_ilvl(iid), loc=EN_GEAR[iid][1])
                    if g == "ranged" and EN_GEAR[iid][3] not in (2, 3, 18):
                        want = []
                    if not en_can_use(cls, iid):
                        want = []
                    lines = en_want_for(w, prices, want, g, role, cls, tab)
                    tt = en_hover(w, "equipped", iid)
                    sc.eq(w.lines(tt), lines, "enchants worn: Top %d, %s %s, %s" % (top, cls, tname, EN_GEAR[iid][0]))
                    tt = en_hover(w, "bag", iid)
                    sc.eq(en_block(w, tt), lines, "enchants bag: Top %d, %s %s, %s" % (top, cls, tname, EN_GEAR[iid][0]))
    w.slash("/gl enchants top2")
    # Weapons the class cannot use (no weapon skill, or off-hand only without dual wield): nothing,
    # in the bags and from links too. Forever's rogues use one-hand axes; its shamans cannot dual wield.
    for cls, pts, how, iid, want in (
            ("MAGE", (0, 0, 31), "bag", 990102, []), ("MAGE", (0, 0, 31), "link", 990102, []),
            ("MAGE", (0, 0, 31), "bag", 990104, []), ("MAGE", (0, 0, 31), "bag", 990101, ["s23804", "s1248805"]),
            ("MAGE", (0, 0, 31), "bag", 990103, ["s1219580", "s1248607"]),
            ("ROGUE", (0, 31, 20), "bag", 990102, []), ("ROGUE", (0, 31, 20), "bag", 990103, []),
            ("ROGUE", (0, 31, 20), "bag", 990130, ["s13898", "s20032"]), ("ROGUE", (0, 31, 20), "bag", 990104, ["s13898", "s20032"]),
            ("PRIEST", (0, 31, 0), "bag", 990101, []), ("PRIEST", (0, 31, 0), "bag", 990131, ["s23804", "s23803"]),
            ("DRUID", (0, 31, 0), "bag", 990102, []), ("DRUID", (0, 31, 0), "bag", 990103, ["s13898", "s27837"]),
            ("DRUID", (0, 31, 0), "bag", 990131, ["s13898", "s20034"]),
            ("SHAMAN", (31, 0, 0), "bag", 990104, []), ("SHAMAN", (31, 0, 0), "bag", 990102, []),
            ("SHAMAN", (31, 0, 0), "bag", 990130, ["s23804", "s1248805"]), ("PALADIN", (0, 0, 31), "bag", 990103, []),
            ("PALADIN", (0, 0, 31), "bag", 990104, []), ("PALADIN", (0, 0, 31), "bag", 990102, ["s13898", "s20034"]),
            ("HUNTER", (0, 31, 0), "bag", 990131, []), ("HUNTER", (0, 31, 0), "bag", 990104, ["s23800"]),
            ("WARRIOR", (31, 5, 0), "bag", 990104, ["s20034", "s13898"])):
        en_player(w, cls, pts)
        tt = en_hover(w, how, iid)
        sc.eq(en_block(w, tt), en_want(w, prices, want), "enchants worn: %s, %s %s" % (cls, how, EN_GEAR[iid][0]))
    # A healer's weapon with a strong enchant that is not in the list: only what beats it.
    en_player(w, "PRIEST", (0, 31, 0))
    w.slash("/gl enchants top5")
    for iid, enchant, want, why in (
            (990131, None, ["s23804", "s23803", "s1248757"], "no enchant"), (990131, 2568, [], "Mighty Intellect on"),
            (990131, 2567, ["s23804"], "Mighty Spirit on"), (990131, 8216, ["s23804", "s23803"], "Insight on"),
            (990131, 2505, [], "Healing Power +55 on"),
            (990103, None, ["s1248636", "s1219580", "s20036", "s7793", "s20035"], "no enchant"),
            (990103, 8212, [], "Mighty Healing Power on"), (990103, 7662, ["s1248636"], "Spellblasting on"),
            (990103, 8211, ["s1248636", "s1219580"], "Mighty Spell Power on (placed above Major Intellect)"),
            (990103, 2568, ["s1248636", "s1219580"], "Mighty Intellect on"),
            (990103, 2567, ["s1248636", "s1219580", "s20036", "s7793"], "Mighty Spirit on (placed above Major Spirit)"),
            (990103, 1904, ["s1248636", "s1219580"], "Major Intellect on (the 3rd)"),
            (990103, 723, ["s1248636", "s1219580", "s20036"], "Lesser Intellect on (the 4th)"),
            (990103, 1903, ["s1248636", "s1219580", "s20036", "s7793"], "Major Spirit on (the 5th)")):
        spec = en_spec("weapon2h" if iid == 990103 else "weapon", "healer", "PRIEST", 2, sub=en_sub(iid), current=enchant)
        sc.eq(spec[:5], want, "enchants worn: the rule's own answer, Holy priest %s, %s" % (EN_GEAR[iid][0], why))
        tt = en_hover(w, "equipped", iid, enchant)
        sc.eq(w.lines(tt), en_want(w, prices, en_five(spec, prices)), "enchants worn: Holy priest %s, %s" % (EN_GEAR[iid][0], why))
    w.slash("/gl enchants top2")
    # A tank's necklace: Strength +5, then Agility +5; one with Deflection on is left alone (its value is not known).
    en_player(w, "WARRIOR", (5, 5, 31))
    for enchant, want, why in ((None, ["s1249019", "s1249059"], "no enchant"), (856, [], "Strength +5 on"),
                               (925, [], "Deflection on"), (904, ["s1249019"], "Agility +5 on (the 2nd)")):
        tt = en_hover(w, "equipped", 990112, enchant)
        sc.eq(w.lines(tt), en_want(w, prices, want), "enchants worn: a tank's necklace, %s" % why)
    # Armor the class cannot wear gets nothing; armor it can, does.
    en_player(w, "MAGE", (0, 0, 31))
    tt = en_hover(w, "equipped", 990126)
    sc.eq(en_count(w, tt), 0, "enchants worn: a mage's plate chest: nothing")
    tt = en_hover(w, "equipped", 990107)
    sc.eq(w.lines(tt), en_want(w, prices, ["k252487", "k252462"]), "enchants worn: a mage's cloth robe")
    tt = en_hover(w, "equipped", 990129)
    sc.eq(en_count(w, tt), 0, "enchants worn: a mage's mail gloves: nothing")
    en_player(w, "HUNTER", (31, 0, 0))
    tt = en_hover(w, "equipped", 990129)
    sc.eq(w.lines(tt), en_want(w, prices, ["s20012", "s13815"]), "enchants worn: a hunter's mail gloves")
    en_player(w, "PALADIN", (0, 0, 31))
    tt = en_hover(w, "equipped", 990126)
    sc.eq(w.lines(tt), en_want(w, prices, ["s20025", "s13941"]), "enchants worn: a paladin's plate chest")
    sc.clean(w)


def sc_enchants_rule(sc, ref, items):
    """Only upgrades: with the k-th option on, the ones before it; nothing with the best or an up
    enchant; an "at" enchant cuts the list at its place; labels number the options the player can use."""
    w, prices = en_world(ref, items, cls="WARRIOR", points=(31, 5, 0))
    w.slash("/gl enchants top5")
    full = en_arms(990102)
    sc.eq(full, ["s20034", "s13898", "s20030", "s20032", "s1248511", "s13937", "s13695", "s13529", "s7745"],
          "rule: an Arms warrior's 2H list (no blacksmith)")
    for k in range(1, len(full) + 1):
        cur = EN_IDS[full[k - 1]]
        want = en_five(full[:k - 1], prices)
        tt = en_hover(w, "equipped", 990102, cur)
        sc.eq(w.lines(tt), en_want(w, prices, want), "rule: 2H with the %d. option on (%s): the %d before it" % (k, EN_NAMES[full[k - 1]], k - 1))
    tt = en_hover(w, "equipped", 990102, 803)
    sc.eq(w.lines(tt), en_want(w, prices, ["s20034"]), "rule: with the 2nd on, the best only")
    tt = en_hover(w, "equipped", 990102, 1896)
    sc.eq(w.lines(tt), en_want(w, prices, ["s20034", "s13898"]), "rule: with the 3rd on, the best and the 2nd")
    sc.eq([l for l, _ in w.lines(tt)][0::2], ["Best enchant: Crusader", "2nd: Fiery Weapon"], "rule: the labels")
    tt = en_hover(w, "equipped", 990102, 1900)
    sc.eq(en_count(w, tt), 0, "rule: with the best on, nothing")
    tt = en_hover(w, "equipped", 990102, 8215)
    sc.eq(en_count(w, tt), 0, "rule: with an up enchant on (Strength +25), nothing")
    # An at = { } enchant: Agility +25 on a 2H ranks just above Lesser Impact +5 (the list's 9th, with the
    # counterweight): the seven before it a non-blacksmith can use (Top 5: the first five); Agility +15
    # and Enchant: Fiery Blaze rank below Minor Impact +4: the whole list.
    sc.eq(en_arms(990102, current=2646), full[:7], "rule: Agility +25 on (at 9 of the list): the seven before Lesser Impact")
    sc.eq(en_arms(990102, current=2564), full, "rule: Agility +15 on (at 11): the whole list")
    sc.eq(en_arms(990102, current=36), full, "rule: Enchant: Fiery Blaze on (at 11): the whole list")
    for cur in (2646, 2564, 36):
        tt = en_hover(w, "equipped", 990102, cur)
        sc.eq(w.lines(tt), en_want(w, prices, en_five(en_arms(990102, current=cur), prices)), "rule: enchant %d on: Top 5 of the entries above it" % cur)
    # Every at place in every list, for one class per role: the entries before the place.
    w.slash("/gl enchants top5")
    for cls, tab, role in (("WARRIOR", 1, "melee"), ("ROGUE", 2, "agility"), ("WARRIOR", 3, "tank"),
                           ("MAGE", 1, "caster"), ("PRIEST", 2, "healer"), ("HUNTER", 2, "hunter")):
        pts = [0, 0, 0]
        pts[tab - 1] = 31
        en_player(w, cls, pts)
        for g, iid in EN_GROUP_ITEM:
            rec = en_pick(g, role, cls, tab, en_sub(iid), EN_GEAR[iid][1])
            if not rec or not en_can_use(cls, iid) or (g == "ranged" and EN_GEAR[iid][3] not in (2, 3, 18)):
                continue
            lst, up, at, rk = rec
            for cur in sorted(at) + sorted(up):
                want = en_top(g, role, cls, tab, 5, prices=prices, sub=en_sub(iid), current=cur, ilvl=en_ilvl(iid),
                              loc=EN_GEAR[iid][1])
                if cur in at:
                    sc.check(all(lst.index(k) + 1 < at[cur] for k in want), "rule: %s %s at %d cuts before %d" % (g, rk, cur, at[cur]))
                tt = en_hover(w, "equipped", iid, cur)
                sc.eq(w.lines(tt), en_want_for(w, prices, want, g, role, cls, tab), "rule: %s %s with %d on" % (g, rk, cur))
    # Level gates drop entries and the labels stay in order (Best, 2nd, 3rd...).
    w.slash("/gl enchants top5")
    en_player(w, "WARRIOR", (31, 0, 0), level=35)
    sc.eq(en_spec("legs", "melee", "WARRIOR", 1, level=35, sub=1)[:5], ["k252453", "k252437", "k8173", "k4265", "k2313"],
          "rule: level 35 warrior legs: the kits a 35 can use")
    want = en_top("legs", "melee", "WARRIOR", 1, 5, prices=prices, level=35, sub=1)
    tt = en_hover(w, "equipped", 990114)
    got = [l for l, _ in w.lines(tt)][0::2]
    sc.eq(got[:2], ["Best enchant: Forceful Heavy Armor Kit", "2nd: Forceful Medium Armor Kit"],
          "rule: level 35 legs: the two best a 35 can use")
    sc.eq(got, [EN_LABELS[i] + EN_NAMES[k] for i, k in enumerate(want)], "rule: level 35 legs: the labels number what is shown")
    sc.eq(w.lines(tt), en_want(w, prices, want), "rule: level 35 legs, their costs and lines")
    w.slash("/gl enchants top2")
    sc.clean(w)


def sc_enchants_levels(sc, ref, items):
    """Lesser Arcanums from level 50, Dire Maul's Arcanums from 58 (what their quests ask), armor
    kits and scopes by the level their items need; scopes for hunters only."""
    w, prices = en_world(ref, items, cls="WARRIOR", points=(31, 0, 0), level=49)
    tt = en_hover(w, "equipped", 990113)
    sc.eq(en_count(w, tt), 0, "enchants levels: no Arcanum at level 49 (head)")
    tt = en_hover(w, "equipped", 990114)
    sc.eq(w.lines(tt), en_want(w, prices, ["k252463", "k252453"]), "enchants levels: level 49 legs: the best kits a 49 can use")
    tt = en_hover(w, "equipped", 990122)
    sc.eq(en_count(w, tt), 0, "enchants levels: shoulders never")
    for level in (50, 57):
        en_player(w, "WARRIOR", (31, 0, 0), level=level)
        tt = en_hover(w, "equipped", 990113)
        sc.eq(w.lines(tt), en_want(w, prices, ["a11645"]),
              "enchants levels: level %d head: the Lesser Arcanum only (Rapidity's quest needs 58)" % level)
        sc.check(any("30g quest fee" in (l or "") for l, _ in w.lines(tt)), "enchants levels: the Lesser Arcanum's fee is named")
        tt = en_hover(w, "equipped", 990114, 1506)
        sc.eq(en_count(w, tt), 0, "enchants levels: level %d legs with the Lesser Arcanum: nothing" % level)
        tt = en_hover(w, "equipped", 990114, 2543)
        sc.eq(en_count(w, tt), 0, "enchants levels: level %d legs with Rapidity (bought on): nothing" % level)
        tt = en_hover(w, "equipped", 990114)
        sc.eq(w.lines(tt), en_want(w, prices, ["a11645", "k252488"]), "enchants levels: level %d legs: Lesser Arcanum, then the kit" % level)
        tt = en_hover(w, "bag", 990113)
        sc.eq(en_block(w, tt), en_want(w, prices, ["a11645"]), "enchants levels: level %d head in a bag" % level)
    en_player(w, "WARRIOR", (31, 0, 0), level=58)
    tt = en_hover(w, "equipped", 990113)
    sc.eq(w.lines(tt), en_want(w, prices, ["a18329", "a11645"]), "enchants levels: level 58 head: Arcanums")
    tt = en_hover(w, "equipped", 990114, 1506)
    sc.eq(w.lines(tt), en_want(w, prices, ["a18329"]), "enchants levels: legs with the Lesser Arcanum: the best only")
    tt = en_hover(w, "equipped", 990114, 2543)
    sc.eq(en_count(w, tt), 0, "enchants levels: legs with Rapidity: nothing")
    # Hunters: Forever's Arcanum of Rapidity hastes ranged attacks too (spell 22841: auras 319 and 140),
    # so it is their best head and legs enchant from 58; at 57 the Lesser Arcanum (Agi +8).
    for level, want in ((57, ["a11647"]), (58, ["a18329", "a11647"])):
        en_player(w, "HUNTER", (0, 31, 0), level=level)
        tt = en_hover(w, "equipped", 990113)
        sc.eq(w.lines(tt), en_want(w, prices, want), "enchants levels: hunter %d head" % level)
    tt = en_hover(w, "equipped", 990114, 1508)
    sc.eq(w.lines(tt), en_want(w, prices, ["a18329"]), "enchants levels: hunter 58 legs with the Lesser Arcanum: Rapidity")
    tt = en_hover(w, "equipped", 990113, 2543)
    sc.eq(en_count(w, tt), 0, "enchants levels: hunter head with Rapidity: nothing")
    en_player(w, "WARRIOR", (31, 0, 0), level=58)
    # Every role and tree, around the quest and kit levels, head and legs, Top 2 and Top 5.
    for top in (2, 5):
        w.slash("/gl enchants top%d" % top)
        for level in (1, 10, 15, 20, 25, 30, 35, 40, 45, 49, 50, 57, 58, 60):
            for cls, trees in EN_TREES.items():
                for tab, (tname, role) in enumerate(trees, 1):
                    pts = [0, 0, 0]
                    pts[tab - 1] = 31
                    en_player(w, cls, pts, level=level)
                    for iid in (990113, 990114, 990132):
                        if not en_can_use(cls, iid) or (iid == 990132 and cls in ("PRIEST", "MAGE", "WARLOCK")):
                            continue
                        g = "head" if iid == 990113 else "legs"
                        want = en_top(g, role, cls, tab, top, prices=prices, level=level, sub=en_sub(iid), ilvl=en_ilvl(iid))
                        tt = en_hover(w, "equipped", iid)
                        sc.eq(w.lines(tt), en_want(w, prices, want), "enchants levels: Top %d, %s %s level %d %s" % (top, cls, tname, level, EN_GEAR[iid][0]))
    w.slash("/gl enchants top2")
    for level, want in ((60, ["i10548", "i10546"]), (40, ["i10548", "i10546"]), (39, ["i10546", "i4407"]),
                        (25, ["i4407", "i4406"]), (9, ["i4405"]), (4, [])):
        en_player(w, "HUNTER", (0, 31, 0), level=level)
        for iid in (990115, 990116, 990128):
            tt = en_hover(w, "equipped", iid)
            sc.eq(w.lines(tt), en_want(w, prices, want), "enchants levels: hunter level %d, %s" % (level, EN_GEAR[iid][0]))
    en_player(w, "HUNTER", (0, 31, 0), level=35)
    for enchant, want, why in ((664, [], "Sniper Scope on (above what level 35 uses)"), (663, [], "Deadly Scope on"),
                               (33, ["i10546"], "Accurate Scope on: the best only"), (32, ["i10546", "i4407"], "a lower scope"),
                               (8720, [], "the new SAF-T scope"), (2523, [], "Biznicks Accurascope")):
        tt = en_hover(w, "equipped", 990116, enchant)
        sc.eq(w.lines(tt), en_want(w, prices, want), "enchants levels: hunter 35 gun, %s" % why)
    w.slash("/gl enchants top5")
    tt = en_hover(w, "equipped", 990115)
    sc.eq(w.lines(tt), en_want(w, prices, ["i10546", "i4407", "i4406", "i4405"]), "enchants levels: Top 5, hunter 35 bow: four scopes")
    tt = en_hover(w, "equipped", 990115, 32)
    sc.eq(w.lines(tt), en_want(w, prices, ["i10546", "i4407"]), "enchants levels: Top 5, hunter 35 bow with a Standard Scope")
    sc.check(all(r == "Engineering scope, use it on the item" for r in [l.strip() for l, _ in w.lines(tt)][1::2]),
             "enchants levels: a scope's grey line says how you get it")
    w.slash("/gl enchants top2")
    tt = en_hover(w, "equipped", 990117)
    sc.eq(en_count(w, tt), 0, "enchants levels: a wand: nothing")
    en_player(w, "WARRIOR", (31, 0, 0))
    tt = en_hover(w, "equipped", 990116)
    sc.eq(w.lines(tt), en_want(w, prices, ["i10548"], note=EN_PULL_NOTE),
          "enchants levels: a warrior's gun in Top 2: the best scope, then the pull note")
    sc.clean(w)


def sc_enchants_links(sc, ref, items):
    """Chat links and other item tooltips: the same options; never on comparison or other tooltips."""
    w, prices = en_world(ref, items)
    tt = en_hover(w, "link", 990102)
    sc.eq(w.lines(tt), en_want(w, prices, ["s20034", "s13898"]), "enchants links: a linked Greatsword")
    tt = en_hover(w, "link", 990102, 1900)
    sc.eq(en_count(w, tt), 0, "enchants links: a linked Greatsword with Crusader")
    tt = en_hover(w, "gamelink", 990108)
    sc.eq(w.lines(tt), en_want(w, prices, ["s1219587", "s13419"]), "enchants links: a link shown on GameTooltip")
    tt = en_hover(w, "shopping", 990102)
    sc.check(len(w.all_lines(tt)) > 0 and en_count(w, tt) == 0, "enchants links: the comparison tooltip gets nothing")
    tt = en_hover(w, "byid", 990102)
    sc.check(len(w.all_lines(tt)) > 0 and en_count(w, tt) == 0, "enchants links: an item shown by id (merchant, loot) gets nothing")
    # Links as Forever writes them (|cnIQ2: colour, crafter fields): the enchant field is read.
    E = w.ns.Enchants
    for link, want in (("|cnIQ2:|Hitem:3473:15:::::::15:1491::::::::Player-6798-00C7A9D7:|h[Runed Copper Pants]|h|r", 15),
                       ("|cnIQ2:|Hitem:3166::::::::15:1491::11:::::::|h[Ironheart Chain]|h|r", None),
                       ("|cffffffff|Hitem:990102:1900::::::::60:::::::::|h[x]|h|r", 1900),
                       ("|cffffffff|Hitem:990102:0:::::::60|h[x]|h|r", None), ("garbage", None), (None, None)):
        sc.eq(E.LinkEnchant(link), want, "enchants links: enchant of %s" % (link or "nil")[:40])
    sc.clean(w)


def sc_enchants_roles(sc, ref, items):
    """Role from the talents (every client's way of giving them), the class default, the cache."""
    w, prices = en_world(ref, items)
    E, M = w.ns.Enchants, w.M

    def role():
        r = E.DetectRole()
        return tuple(r) if isinstance(r, tuple) else (r,)
    for mode in ("forever", "specinfo", "tabs-name", "tabs-id"):
        for cls, trees in EN_TREES.items():
            for tab, (tname, want) in enumerate(trees, 1):
                pts = [0, 0, 0]
                pts[tab - 1] = 21
                pts[(tab + 1) % 3] = 9
                en_player(w, cls, pts, mode)
                sc.eq(role()[:4], (want, "talents", tab, 21), "enchants roles: %s %s %s" % (mode, cls, tname))
            en_player(w, cls, (3, 1, 0), mode, level=12)
            sc.eq(role()[:2], (EN_DEFAULT[cls], "class"), "enchants roles: %s %s with 4 points: the class default" % (mode, cls))
    en_player(w, "PALADIN", (10, 10, 0))
    sc.eq(role()[:2], ("melee", "class"), "enchants roles: a Holy / Protection tie: the class default")
    en_player(w, "WARRIOR", (10, 10, 0))
    sc.eq(role()[:3], ("melee", "talents", 1), "enchants roles: an Arms / Fury tie is still melee")
    # The Legacy group never counts; Forever's starter spec alone (0 points) is never trusted.
    en_player(w, "PALADIN", (6, 0, 0))
    M.talents.legacy = 40
    E.Invalidate()
    sc.eq(role()[:3], ("healer", "talents", 1), "enchants roles: Forever's groups by their order, the Legacy group not counted")
    for mode in ("starter", "none"):
        en_player(w, "PALADIN", (31, 0, 0), mode)
        sc.eq(role()[:2], ("melee", "class"), "enchants roles: %s: the class default, not Holy" % mode)
    # No talent API at all, no class.
    en_player(w, "DRUID", (0, 31, 0))
    for name in ("C_Traits", "C_ClassTalents", "C_SpecializationInfo", "GetTalentTabInfo", "GetNumTalentTabs"):
        w.g[name] = None
    E.Invalidate()
    sc.eq(role()[:2], ("agility", "class"), "enchants roles: no talent API: the class default")
    w.g.UnitClass = None
    E.Invalidate()
    sc.eq(role()[0], None, "enchants roles: no class: no role")
    tt = en_hover(w, "equipped", 990102)
    sc.eq(en_count(w, tt), 0, "enchants roles: no role: no lines")
    w.slash("/gl enchants healer")
    tt = en_hover(w, "equipped", 990102)
    sc.eq(w.lines(tt), en_want(w, prices, ["s1248636", "s1219580"]), "enchants roles: no class, a role picked by hand")
    sc.clean(w)

    # The cache: one talent read for many hovers, again after an event or 10 seconds.
    w, prices = en_world(ref, items, cls="WARRIOR", points=(31, 5, 0))
    E, M = w.ns.Enchants, w.M
    arms, prot = ["s20010", "s13939"], ["s1248665", "s13931"]   # bracers: Arms and Protection differ
    tt = en_hover(w, "equipped", 990109)
    r0, s0, c0 = E.reads, E.skillReads, M.skillCalls
    for _ in range(25):
        en_hover(w, "equipped", 990102)
        en_hover(w, "bag", 990108)
        en_hover(w, "equipped", 990105)
    sc.eq(E.reads, r0, "enchants roles: no talent reads while hovering")
    sc.eq((E.skillReads - s0, M.skillCalls - c0), (0, 0), "enchants roles: no profession reads while hovering")
    M.talents.points = w.to_lua([0, 5, 31])
    tt = en_hover(w, "equipped", 990109)
    sc.eq(w.lines(tt), en_want(w, prices, arms), "enchants roles: a respec waits for its event (cached)")
    for ev in ("CHARACTER_POINTS_CHANGED", "PLAYER_TALENT_UPDATE", "ACTIVE_TALENT_GROUP_CHANGED", "TRAIT_CONFIG_UPDATED",
               "PLAYER_LEVEL_UP"):
        M.talents.points = w.to_lua([0, 5, 31])
        n = E.reads
        M.fire(ev)
        tt = en_hover(w, "equipped", 990109)
        sc.eq((E.reads - n, w.lines(tt)), (1, en_want(w, prices, prot)),
              "enchants roles: %s reads the talents again (Protection)" % ev)
        M.talents.points = w.to_lua([31, 5, 0])
        M.fire(ev)
        tt = en_hover(w, "equipped", 990109)
        sc.eq(w.lines(tt), en_want(w, prices, arms), "enchants roles: %s, back to Arms" % ev)
    # A skill point (weapon skills too) re-reads only the professions, not the talents.
    n = E.reads
    M.fire("SKILL_LINES_CHANGED")
    en_hover(w, "equipped", 990102)
    sc.eq(E.reads, n, "enchants roles: SKILL_LINES_CHANGED does not read the talents again")
    n = E.reads
    M.talents.points = w.to_lua([0, 5, 31])
    M.t = M.t + 9
    en_hover(w, "equipped", 990102)
    sc.eq(E.reads, n, "enchants roles: still cached after 9 seconds")
    M.t = M.t + 2
    tt = en_hover(w, "equipped", 990109)
    sc.eq((E.reads - n, w.lines(tt)), (1, en_want(w, prices, prot)), "enchants roles: read again after 10 seconds")
    # Level 60 with nothing spent (talents not loaded yet): kept only 2 seconds.
    M.talents.points = w.to_lua([0, 0, 0])
    E.Invalidate()
    en_hover(w, "equipped", 990102)
    n = E.reads
    M.t = M.t + 2.5
    en_hover(w, "equipped", 990102)
    sc.eq(E.reads, n + 1, "enchants roles: an unsure answer (no points at 60) is read again soon")
    sc.clean(w)


EN_TOP2_TAIL = " Top 2: the two best (/gl enchants top5 adds cheaper budget options)."
EN_TOP5_TAIL = " Top 5: the best, then cheaper budget options (/gl enchants top2 for the two best)."


def sc_enchants_slash(sc, ref, items):
    """/gl enchants: status, a role by hand, off, auto, top2 and top5; kept in the saved settings; in /gl help."""
    w, prices = en_world(ref, items, cls="WARRIOR", points=(31, 5, 0), bags=False)
    S = w.ns.settings
    out = [strip_codes(x) for x in w.slash("/gl enchants")]
    sc.eq(out, ["Goblin Ledger: enchant tips: auto, melee (Arms, 31 points)." + EN_TOP2_TAIL], "enchants slash: status")
    out = [strip_codes(x) for x in w.slash("/gl enchants tank")]
    sc.eq((out, S.enchants), (["Goblin Ledger: enchant tips are now for tank."], "tank"), "enchants slash: tank")
    tt = en_hover(w, "equipped", 990109)
    sc.eq(w.lines(tt), en_want(w, prices, ["s1248665", "s13931"]), "enchants slash: tank picks on the bracers")
    out = [strip_codes(x) for x in w.slash("/gl enchants")]
    sc.eq(out, ["Goblin Ledger: enchant tips are for tank (picked by hand; your talents say melee (Arms, 31 points)). "
                "/gl enchants auto follows your talents." + EN_TOP2_TAIL], "enchants slash: status with a pick")
    out = [strip_codes(x) for x in w.slash("/gl enchant HEALER")]
    sc.eq((out, S.enchants), (["Goblin Ledger: enchant tips are now for healer."], "healer"), "enchants slash: /gl enchant alias")
    out = [strip_codes(x) for x in w.slash("/gl enchants wizard")]
    sc.eq((out, S.enchants), (["Goblin Ledger: unknown choice. Use /gl enchants auto, melee, agility, tank, caster, "
                               "healer, hunter, off, top2 or top5."], "healer"), "enchants slash: unknown choice")
    out = [strip_codes(x) for x in w.slash("/gl enchants off")]
    sc.eq((out, S.enchants), (["Goblin Ledger: enchant tips are off. /gl enchants auto turns them back on."], "off"),
          "enchants slash: off")
    tt = en_hover(w, "equipped", 990102)
    sc.eq(en_count(w, tt), 0, "enchants slash: off hides the lines")
    out = [strip_codes(x) for x in w.slash("/gl enchants")]
    sc.eq(out, ["Goblin Ledger: enchant tips are off. /gl enchants auto turns them back on."], "enchants slash: status when off")
    # top2 / top5 while off: the count changes, off and the kept role do not, and the reply says the
    # tips are still off (and how to turn them on), so it is not read as "they show now".
    out = [strip_codes(x) for x in w.slash("/gl enchants top5")]
    sc.eq((out, S.enchants, S.enchantsBeforeOff, S.enchantsTop),
          (["Goblin Ledger: enchant tips show the top 5: the best, then cheaper budget options. "
            "(the tips are off now: /gl enchants auto turns them on)"], "off", "healer", 5),
          "enchants slash: top5 while off keeps off and the role, and says the tips are off")
    tt = en_hover(w, "equipped", 990102)
    sc.eq(en_count(w, tt), 0, "enchants slash: top5 while off: still no lines")
    out = [strip_codes(x) for x in w.slash("/gl enchants 2")]
    sc.eq((out, S.enchants, S.enchantsTop),
          (["Goblin Ledger: enchant tips show the top 2: the two best. "
            "(the tips are off now: /gl enchants auto turns them on)"], "off", 2),
          "enchants slash: 2 while off says the tips are off")
    out = [strip_codes(x) for x in w.slash("/gl enchants 5")]
    sc.eq(S.enchantsTop, 5, "enchants slash: 5 while off")
    out = [strip_codes(x) for x in w.slash("/gl enchants auto")]
    sc.eq((out, S.enchants, S.enchantsTop), (["Goblin Ledger: enchant tips follow your talents: melee (Arms, 31 points)."], None, 5),
          "enchants slash: auto keeps Top 5")
    tt = en_hover(w, "equipped", 990102)
    sc.eq(w.lines(tt), en_want(w, prices, en_five(en_arms(990102), prices)), "enchants slash: auto, Top 5")
    out = [strip_codes(x) for x in w.slash("/gl enchants")]
    sc.eq(out, ["Goblin Ledger: enchant tips: auto, melee (Arms, 31 points)." + EN_TOP5_TAIL], "enchants slash: status says Top 5")
    for word, n in (("top2", 2), ("5", 5), ("2", 2), ("TOP5", 5), ("top 2", 2)):
        out = [strip_codes(x) for x in w.slash("/gl enchants " + word)]
        msg = ("enchant tips show the top 5: the best, then cheaper budget options." if n == 5
               else "enchant tips show the top 2: the two best.")
        sc.eq((out, S.enchantsTop, S.enchants), (["Goblin Ledger: " + msg], n, None), "enchants slash: /gl enchants %s" % word)
        tt = en_hover(w, "equipped", 990102)
        sc.eq(w.lines(tt), en_want(w, prices, en_five(en_arms(990102), prices, n)), "enchants slash: /gl enchants %s: Top %d" % (word, n))
    w.slash("/gl enchants tank")
    w.slash("/gl enchants top5")
    sc.eq((S.enchants, S.enchantsTop), ("tank", 5), "enchants slash: top5 keeps a role picked by hand")
    w.slash("/gl enchants auto")
    w.slash("/gl enchants top2")
    tt = en_hover(w, "equipped", 990102)
    sc.eq(w.lines(tt), en_want(w, prices, ["s20034", "s13898"]), "enchants slash: auto again")
    # /gl tooltip off hides them with the prices.
    w.slash("/gl tooltip")
    tt = en_hover(w, "equipped", 990102)
    sc.eq(en_count(w, tt), 0, "enchants slash: /gl tooltip off hides the enchant lines too")
    w.slash("/gl tooltip")
    en_player(w, "WARRIOR", (3, 0, 0), level=12)
    out = [strip_codes(x) for x in w.slash("/gl enchants")]
    sc.eq(out, ["Goblin Ledger: enchant tips: auto, melee (the warrior default: fewer than 5 points in one talent tree)."
                + EN_TOP2_TAIL], "enchants slash: status at low level")
    out = [strip_codes(x) for x in w.slash("/gl help")]
    sc.check(any(t.endswith("/gl enchants : the best enchants on the gear you wear, for your role: auto, melee, agility, tank, "
                            "caster, healer, hunter or off (auto follows your talents); top2 shows the two best, top5 adds "
                            "cheaper budget options") for t in out),
             "enchants slash: /gl help lists /gl enchants, top2 and top5")
    sc.check(any(t.endswith("the price is the mats at AH value (a kit, scope or other upgrade: its own); an enchant needs an enchanter")
                 for t in out), "enchants slash: /gl help says what the price is")
    sc.check(any("/gl compact" in t for t in out) and any("/gl bags" in t for t in out) and any("/gl watch" in t for t in out),
             "enchants slash: /gl help still lists the other commands")
    sc.eq(sum(1 for t in out if "/gl enchants" in t), 1, "enchants slash: listed once")
    sc.check(not any("bags on" in t or "worn gear only" in t for t in out), "enchants slash: /gl help has no bags opt-in")
    sc.check(not any("2nd best" in t for t in out), "enchants slash: /gl help no longer says 2nd best")
    out = [strip_codes(x) for x in w.slash("/gl")]
    sc.check(not any("enchant" in t for t in out), "enchants slash: /gl status is unchanged")
    sc.clean(w)
    for saved, want, top, label in (({"enchants": "tank"}, "tank", None, "a saved pick"),
                                    ({"enchants": "off"}, "off", None, "saved off"),
                                    ({"enchants": "wizard"}, None, None, "an unknown saved value"),
                                    ({"enchants": 5}, None, None, "a number"),
                                    ({"enchantsTop": 5}, None, 5, "Top 5"), ({"enchantsTop": 2}, None, 2, "Top 2"),
                                    ({"enchantsTop": 3}, None, None, "an unknown Top"),
                                    ({"enchantsTop": "top5"}, None, None, "Top as words"),
                                    ({"enchants": "off", "enchantsTop": 5}, "off", 5, "off with Top 5")):
        text, prices = en_data(ref)
        w = World(ref, items, data_src=text, saved=saved)
        sc.eq((w.ns.settings.enchants, w.ns.settings.enchantsTop), (want, top), "enchants slash: %s after login" % label)
        sc.eq(w.ns.Enchants.TopN(), top or 5, "enchants slash: %s: Top %d" % (label, top or 5))
        sc.check(w.same(w.g.ForeverAH_Settings, w.ns.settings), "enchants slash: %s is in the saved settings" % label)
        sc.clean(w, "enchants slash " + label)


# Places that never get enchant lines, also with the tests' wider E.SHOW (en_world bags=True), and
# the places that get them only there (in the game: worn gear only).
EN_NEVER = ("inspect", "ahrow", "byid", "shopping")
EN_BAG_PLACES = ("bag", "bank", "link", "gamelink")


def en_panel_hover(w, iid, owner, slot=None, enchant=None, bag=False):
    """A tooltip owned by a frame (the character panel's slot button, say), the older client's way:
    worn gear (SetInventoryItem) or, bag=True, the item in bag 0 slot 1."""
    g, M = w.g, w.M
    tt = g.GameTooltip
    tt.SetOwner(tt, owner, "ANCHOR_RIGHT")
    if bag:
        bag_put(w, 0, 1, iid, 1, enchant=enchant, bound=True)
        tt.SetBagItem(tt, 0, 1)
    else:
        slot = slot or EN_GEAR[iid][5]
        s = w.to_lua({"itemID": iid, "bound": True})
        s.enchant = enchant
        M.equipped[slot] = s
        tt.SetInventoryItem(tt, "player", slot)
    return tt


def en_button(w, name, slot):
    """A button with this name and id (the character panel's Character<Slot>Slot: its id is the slot)."""
    return w.lua.eval("function(n, id) local b = _G[n] or CreateFrame('Button', n, UIParent); b:SetID(id); return b end")(name, slot)


def en_priced_gear(w, ref):
    """A priced item made into a cloak (in the mock), as the gear in the user's screenshot: returns its id."""
    g = w.g
    tt = g.GameTooltip
    for iid in sorted(ref.items):
        if iid in ROLE_IDS() or iid in en_source_mats() or iid in EN_ITEMS:
            continue
        tt.SetOwner(tt, g.UIParent, "ANCHOR_NONE")
        tt.SetItemByID(tt, iid)
        if big_fontstrings(w, tt):
            it = w.M["items"][iid]
            it.equipLoc, it.classID, it.subclassID = "INVTYPE_CLOAK", 4, 1
            w.ns.Enchants.Invalidate()   # an item's slot never changes in game: it is remembered
            return iid
    return None


def sc_enchants_worn_only(sc, ref, items):
    """Enchant tips on your own worn gear only (the character panel's slots); none on bag and bank
    items, chat links, auction house rows or gear you inspect. Their price lines stay."""
    w, prices = en_world(ref, items, bags=False)
    g, S = w.g, w.ns.settings
    for iid, want in ((990102, ["s20034", "s13898"]), (990108, ["s1219587", "s13419"]), (990109, ["s20010", "s13939"])):
        tt = en_hover(w, "equipped", iid)
        sc.eq(w.lines(tt), en_want(w, prices, want), "worn only: worn %s: the two best" % EN_GEAR[iid][0])
        en_styles_ok(sc, w, tt, "worn only: worn %s" % EN_GEAR[iid][0])
        for how in EN_BAG_PLACES + EN_NEVER:
            tt = en_hover(w, how, iid)
            sc.check(len(w.all_lines(tt)) > 0 and en_count(w, tt) == 0, "worn only: %s %s: no enchant lines (%s)"
                     % (how, EN_GEAR[iid][0], [strip_codes(l or "") for l, _ in w.all_lines(tt)]))
    # Every slot group: worn gets what the rule says, the same item in a bag nothing.
    for gname, iid in EN_GROUP_ITEM:
        want = en_top(gname, "melee", "WARRIOR", 1, 2, prices=prices, sub=en_sub(iid), ilvl=en_ilvl(iid), loc=EN_GEAR[iid][1])
        if (gname == "ranged" and EN_GEAR[iid][3] not in (2, 3, 18)) or not en_can_use("WARRIOR", iid):
            want = []
        tt = en_hover(w, "equipped", iid)
        sc.eq(w.lines(tt), en_want_for(w, prices, want, gname, "melee", "WARRIOR", 1), "worn only: worn %s" % EN_GEAR[iid][0])
        tt = en_hover(w, "bag", iid)
        sc.eq(en_count(w, tt), 0, "worn only: %s in a bag: nothing" % EN_GEAR[iid][0])
    # The screenshot: priced gear in a bag keeps its price lines and gets no enchant lines; worn: both.
    pid = en_priced_gear(w, ref)
    if sc.check(pid is not None, "worn only: a priced item with verdict lines"):
        tt = g.GameTooltip
        w.put_bag(1, 1, pid, 1)
        tt.SetOwner(tt, g.UIParent, "ANCHOR_NONE")
        tt.SetBagItem(tt, 1, 1)
        got = w.lines(tt)
        sc.check(len(got) > 0 and en_count(w, tt) == 0 and big_fontstrings(w, tt),
                 "worn only: priced cloak in a bag: price lines, no enchant lines (%s)" % got)
        w.M.equipped[15] = w.to_lua({"itemID": pid})
        tt.SetOwner(tt, g.UIParent, "ANCHOR_NONE")
        tt.SetInventoryItem(tt, "player", 15)
        sc.eq(en_block(w, tt), en_want(w, prices, ["s1219587", "s13419"]), "worn only: the priced cloak worn: the two best")
        sc.check(len(w.lines(tt)) > len(en_block(w, tt)), "worn only: the priced cloak worn: its price lines first")
        tt = en_hover(w, "link", pid)
        sc.eq(en_count(w, tt), 0, "worn only: the priced cloak's chat link: nothing")
        it = w.M["items"][pid]
        it.equipLoc, it.classID, it.subclassID = None, None, None
        w.M.equipped[15] = None
        w.ns.Enchants.Invalidate()
    # Top 2 / Top 5 and off still work on worn gear; bags stay empty.
    w.slash("/gl enchants top5")
    five = en_five(en_arms(990102), prices)
    tt = en_hover(w, "equipped", 990102)
    sc.eq(w.lines(tt), en_want(w, prices, five), "worn only: Top 5 on worn gear")
    tt = en_hover(w, "bag", 990102)
    sc.eq(en_count(w, tt), 0, "worn only: Top 5: a bag still nothing")
    w.slash("/gl enchants off")
    tt = en_hover(w, "equipped", 990102)
    sc.eq(en_count(w, tt), 0, "worn only: off: worn gear nothing")
    w.slash("/gl enchants auto")
    w.slash("/gl enchants top2")
    tt = en_hover(w, "equipped", 990102)
    sc.eq(w.lines(tt), en_want(w, prices, ["s20034", "s13898"]), "worn only: auto, Top 2 again")
    # No way to put them back on bags: /gl enchants bags on is not a choice and changes nothing.
    before = lua_to_py(S)
    out = [strip_codes(x) for x in w.slash("/gl enchants bags on")]
    sc.eq(out, ["Goblin Ledger: unknown choice. Use /gl enchants auto, melee, agility, tank, caster, healer, hunter, off, "
                "top2 or top5."], "worn only: bags on is not a choice")
    sc.eq(lua_to_py(S), before, "worn only: bags on changes no setting")
    tt = en_hover(w, "bag", 990102)
    sc.eq(en_count(w, tt), 0, "worn only: after bags on: a bag still nothing")
    sc.clean(w)
    # The character panel's box and Top button: worn gear only.
    w, prices = char_world(ref, items, bags=False)
    g, M = w.g, w.M
    char_show(w)
    cb, tb = tg(w), g.GoblinLedgerEnchantTop
    M.click(cb)
    tt = en_hover(w, "equipped", 990102)
    sc.eq(en_count(w, tt), 0, "worn only: the box cleared: worn gear nothing")
    M.click(cb)
    tt = en_hover(w, "equipped", 990102)
    sc.eq(w.lines(tt), en_want(w, prices, ["s20034", "s13898"]), "worn only: the box ticked: worn gear the two best")
    M.click(tb)
    tt = en_hover(w, "equipped", 990102)
    sc.eq(w.lines(tt), en_want(w, prices, en_five(en_arms(990102), prices)), "worn only: the Top button: Top 5 on worn gear")
    tt = en_hover(w, "bag", 990102)
    sc.eq(en_count(w, tt), 0, "worn only: the Top button: a bag still nothing")
    M.click(tb)
    sc.eq(w.ns.settings.enchantsTop, 2, "worn only: the Top button back to Top 2")
    sc.clean(w, "worn only: character panel")
    # The older client (OnTooltipSetItem does not say where): worn gear from the character panel's
    # slot buttons only.
    w, prices = en_world(ref, items, client="legacy", mode="tabs-name", points=(31, 0, 0), bags=False)
    sc.eq(w.ns.tooltipMode, "script", "worn only: legacy: script hooks")
    g = w.g
    main = en_button(w, "CharacterMainHandSlot", 16)
    cloak = en_button(w, "CharacterBackSlot", 15)
    for iid, btn, want in ((990102, main, ["s20034", "s13898"]), (990108, cloak, ["s1219587", "s13419"])):
        tt = en_panel_hover(w, iid, btn)
        sc.eq(en_block(w, tt), en_want(w, prices, want), "worn only: legacy: worn %s from its slot button" % EN_GEAR[iid][0])
        tt = en_panel_hover(w, iid, g.UIParent)
        sc.eq(en_count(w, tt), 0, "worn only: legacy: worn %s, the owner not a slot button: nothing" % EN_GEAR[iid][0])
        tt = en_hover(w, "bag", iid)
        sc.eq(en_count(w, tt), 0, "worn only: legacy: %s in a bag: nothing" % EN_GEAR[iid][0])
        tt = en_hover(w, "link", iid)
        sc.eq(en_count(w, tt), 0, "worn only: legacy: %s's chat link: nothing" % EN_GEAR[iid][0])
    tt = en_panel_hover(w, 990102, main, enchant=1900)
    sc.eq(en_count(w, tt), 0, "worn only: legacy: worn Greatsword with Crusader: nothing")
    # A bag slot's button (its id is the bag slot) and the bag bar's (inventory slot 20): nothing,
    # also when the worn item is the same one.
    en_panel_hover(w, 990102, main)
    tt = en_panel_hover(w, 990102, g.ContainerFrame1Item16, bag=True)
    sc.eq(en_count(w, tt), 0, "worn only: legacy: the same Greatsword from a bag button: nothing")
    tt = en_panel_hover(w, 990102, en_button(w, "CharacterBag0Slot", 20), slot=20)
    sc.eq(en_count(w, tt), 0, "worn only: legacy: the bag bar's slot (20): nothing")
    head = en_button(w, "CharacterHeadSlot", 1)
    tt = en_panel_hover(w, 990113, head)
    sc.eq(en_block(w, tt), en_want(w, prices, ["a18329", "a11645"]), "worn only: legacy: the worn head from its slot button")
    tt = en_panel_hover(w, 990102, head, bag=True)
    sc.eq(en_count(w, tt), 0, "worn only: legacy: a bag item under the head slot's button (another item there): nothing")
    # The inspect frame's slot button (InspectMainHandSlot, id 16) over the same Greatsword you wear: nothing.
    en_panel_hover(w, 990102, main)
    tt = g.GameTooltip
    tt.SetOwner(tt, en_button(w, "InspectMainHandSlot", 16), "ANCHOR_RIGHT")
    w.M.inspected[16] = w.to_lua({"itemID": 990102, "bound": True})
    tt.SetInventoryItem(tt, "target", 16)
    sc.check(len(w.all_lines(tt)) > 0 and en_count(w, tt) == 0,
             "worn only: legacy: the inspect frame's main hand (you wear the same): nothing (%s)"
             % [strip_codes(l or "") for l, _ in w.all_lines(tt)])
    sc.clean(w, "worn only: legacy")


def sc_enchants_modes(sc, ref, items):
    """Compact mode: the name lines only (Shift shows the mats); prices with and without AH values; no data."""
    w, prices = en_world(ref, items)
    two = ["s20034", "s13898"]
    for top, keys in ((2, two), (5, en_five(en_arms(990102), prices))):
        w.slash("/gl enchants top%d" % top)
        w.slash("/gl compact")
        tt = en_hover(w, "equipped", 990102)
        sc.eq(w.lines(tt), en_want(w, prices, keys, full=False), "enchants modes: Top %d, compact: one line each" % top)
        tt = en_hover(w, "bag", 990102)
        sc.eq(en_block(w, tt), en_want(w, prices, keys, full=False), "enchants modes: Top %d, compact in a bag" % top)
        w.M.shift = True
        tt = en_hover(w, "equipped", 990102)
        sc.eq(w.lines(tt), en_want(w, prices, keys), "enchants modes: Top %d, compact with Shift: the mats too" % top)
        w.slash("/gl compact")
        tt = en_hover(w, "equipped", 990102)
        sc.eq(w.lines(tt), en_want(w, prices, keys), "enchants modes: Top %d, full with Shift: the same" % top)
        w.M.shift = False
        tt = en_hover(w, "equipped", 990102)
        sc.eq(w.lines(tt), en_want(w, prices, keys), "enchants modes: Top %d, full: the mats" % top)
    w.slash("/gl enchants top2")
    # Older clients answer IsShiftKeyDown with 1: that is Shift down too (as Core reads it).
    w.slash("/gl compact")
    shift = w.g.IsShiftKeyDown
    w.lua.execute("IsShiftKeyDown = function() return 1 end")
    tt = en_hover(w, "equipped", 990102)
    sc.eq(w.lines(tt), en_want(w, prices, two), "enchants modes: compact, IsShiftKeyDown gives 1: the mats too")
    w.lua.execute("IsShiftKeyDown = function() return nil end")
    tt = en_hover(w, "equipped", 990102)
    sc.eq(w.lines(tt), en_want(w, prices, two, full=False), "enchants modes: compact, IsShiftKeyDown gives nil")
    # An upgrade's grey line (how you get it) is hidden in compact mode the same way.
    en_player(w, "WARRIOR", (31, 0, 0), level=35)
    tt = en_hover(w, "equipped", 990132, 8484)
    sc.eq(w.lines(tt), en_want(w, prices, ["k252453", "k252437"], full=False), "enchants modes: compact: kits, one line each")
    w.g.IsShiftKeyDown = shift
    w.slash("/gl compact")
    en_player(w, "WARRIOR", (31, 5, 0))
    # Rounding: whole gold from 10g, whole silver under it (1g 47s is not "~1g").
    E = w.ns.Enchants
    cs = (99, 150, 14698, 25049, 99960, 100000, 104999, 105000, 2345678)
    sc.eq([E.RoundCopper(c) for c in cs], [99, 200, 14700, 25000, 100000, 100000, 100000, 110000, 2350000],
          "enchants modes: costs are rounded to whole silver under 10g, whole gold from 10g")
    sc.eq([en_round(c) for c in cs], [E.RoundCopper(c) for c in cs], "enchants modes: the harness rounds the same")
    # Every line's cost is its mats' AH value (each mat's value times its count) or the upgrade item's own.
    w.slash("/gl enchants top5")
    tt = en_hover(w, "equipped", 990102)
    got = w.lines(tt)
    names = en_source_mats()
    for key, (l, r) in zip(en_five(en_arms(990102), prices), got[0::2]):
        copper = sum(prices[mid] * n for mid, n in EN_M[key])
        sc.eq(r, "~" + money_icons(en_round(copper)), "enchants modes: %s costs its mats (%s)" % (EN_NAMES[key], en_mats(key)))
    w.slash("/gl enchants top2")
    # Old prices (more than 6 hours): the costs are grey, like the price lines' age warning; fresh again: white.
    up = w.ref.updated
    for age, stale in ((5 * 3600, False), (3 * 86400, True), (25 * 60, False)):
        w.M.now = up + age
        tt = en_hover(w, "equipped", 990102)
        sc.eq(w.lines(tt), en_want(w, prices, two), "enchants modes: prices %dh old: the same lines" % (age // 3600))
        en_styles_ok(sc, w, tt, "enchants modes: prices %dh old" % (age // 3600), stale=stale)
        tt = en_hover(w, "equipped", 990114)
        en_styles_ok(sc, w, tt, "enchants modes: legs, prices %dh old" % (age // 3600), stale=stale)
    w.M.now = w.now
    # Head at 60: Rapidity's bound Blood of Heroes is named; the Lesser Arcanum has two bound mats: "+ more".
    en_player(w, "WARRIOR", (31, 0, 0), level=60)
    tt = en_hover(w, "equipped", 990113)
    got = w.lines(tt)
    sc.eq(got, en_want(w, prices, ["a18329", "a11645"]), "enchants modes: head, bound mats")
    sc.check(got and got[0][1].endswith(" + 2 Blood of Heroes"), "enchants modes: a bound mat is named (%s)" % (got[:1],))
    sc.check(len(got) > 2 and got[2][1].endswith(" + more"), "enchants modes: two mats with no AH value: + more (%s)" % (got[2:3],))
    sc.clean(w)
    # One mat with no AH value is named; two or more: "+ more"; none priced: grey "no AH price".
    w, prices = en_world(ref, items, unlisted=(12811,))
    tt = en_hover(w, "equipped", 990102)
    got = w.lines(tt)
    sc.eq(got, en_want(w, prices, two), "enchants modes: Righteous Orb not listed")
    sc.check(got and got[0][1].endswith(" + 2 Righteous Orb"), "enchants modes: the unlisted mat is named (%s)" % (got[:1],))
    sc.clean(w)
    w, prices = en_world(ref, items, unlisted=(12811, 14344))
    tt = en_hover(w, "equipped", 990102)
    got = w.lines(tt)
    sc.eq(got, en_want(w, prices, two), "enchants modes: no Crusader mat listed")
    sc.eq(got[0][1] if got else None, "no AH price", "enchants modes: no AH price")
    en_styles_ok(sc, w, tt, "enchants modes: no AH price is grey")
    sc.clean(w)
    # An upgrade item nobody lists: "not on AH", grey.
    w, prices = en_world(ref, items, unlisted=(252453,), level=35)
    tt = en_hover(w, "equipped", 990132, 8484)
    got = w.lines(tt)
    sc.eq(got, en_want(w, prices, ["k252453", "k252437"]), "enchants modes: a kit not on the AH")
    sc.eq(got[0][1] if got else None, "not on AH", "enchants modes: not on AH")
    en_styles_ok(sc, w, tt, "enchants modes: not on AH is grey")
    sc.clean(w)
    # No price data: the names and mats (and how you get an upgrade), no price.
    w, _ = en_world(ref, items, data_src=PLACEHOLDER)
    tt = en_hover(w, "equipped", 990102)
    sc.eq(w.lines(tt), en_want(w, None, two), "enchants modes: no price data: names and mats")
    tt = en_hover(w, "bag", 990102, 1900)
    sc.eq(en_count(w, tt), 0, "enchants modes: no price data: Crusader on, nothing")
    en_player(w, "WARRIOR", (31, 0, 0), level=35)
    tt = en_hover(w, "equipped", 990132, 8484)
    sc.eq(w.lines(tt), en_want(w, None, ["k252453", "k252437"]), "enchants modes: no price data: kits and how you get them")
    sc.clean(w)


def sc_enchants_quiet(sc, ref, items):
    """No enchant lines on the bag cleanup's rows or the sidebar's rows (they are about selling)."""
    w, prices = en_world(ref, items)
    M, g, ns = w.M, w.g, w.ns
    w.M["items"][990108].vendor = 1
    bag_put(w, 0, 1, 990108, 1)
    tt = g.GameTooltip
    tt.SetOwner(tt, g.UIParent, "ANCHOR_NONE")
    tt.SetBagItem(tt, 0, 1)
    sc.eq(en_count(w, tt), 2, "enchants quiet: the cloak in the bag has the lines")
    M.OpenBags(1)
    w.settle(0.2)
    BP = ns.BagPanel
    M.click(BP.tab)
    w.settle(0.1)
    row = None
    for i in range(1, len(BP.rows) + 1):
        r = BP.rows[i]
        if r.IsShown(r) and r.entry is not None and r.entry.id == 990108:
            row = r
    # What the flag says while the rows set the tooltip.
    w.g.GL_NS = ns
    w.lua.execute("""
      local tt = GameTooltip
      QUIET_SEEN, QUIET_OLD = {}, { tt.SetBagItem, tt.SetHyperlink, tt.SetItemByID }
      for i, k in ipairs({ "SetBagItem", "SetHyperlink", "SetItemByID" }) do
        local orig = QUIET_OLD[i]
        tt[k] = function(self, ...) QUIET_SEEN[#QUIET_SEEN + 1] = k .. "=" .. tostring(GL_NS.tipQuiet == true); return orig(self, ...) end
      end""")
    if sc.check(row is not None, "enchants quiet: the cloak has a bag cleanup row"):
        M.enter(row)
        flat = [strip_codes(l or "") for l, _ in w.all_lines(tt)]
        sc.check("Test Cloak" in flat and en_count(w, tt) == 0, "enchants quiet: the bag cleanup row has no enchant lines (%s)" % flat)
        # The game builds the tooltip again when item data arrives (TOOLTIP_DATA_UPDATE): still none.
        tt.RefreshData(tt)
        flat = [strip_codes(l or "") for l, _ in w.all_lines(tt)]
        sc.check("Test Cloak" in flat and en_count(w, tt) == 0,
                 "enchants quiet: the bag cleanup row after a refresh has no enchant lines (%s)" % flat)
        M.leave(row)
        seen = [w.g.QUIET_SEEN[i] for i in range(1, len(w.g.QUIET_SEEN) + 1)]
        sc.eq(seen, ["SetBagItem=true"], "enchants quiet: the bag row sets the tooltip with the flag up")
    sc.check(not ns.tipQuiet, "enchants quiet: the flag is down after the row")
    tt.SetOwner(tt, g.UIParent, "ANCHOR_NONE")
    tt.SetBagItem(tt, 0, 1)
    sc.eq(en_count(w, tt), 2, "enchants quiet: the bag slot itself still has them")
    w.open_ah_modern()
    SB = ns.SidebarPanel
    rows = shown_rows(SB, "watchRows") if SB is not None else []
    if sc.check(len(rows) > 0, "enchants quiet: sidebar watch rows"):
        r = rows[0]
        it = M["items"][r.itemID]
        it.equipLoc, it.classID, it.subclassID = "INVTYPE_CLOAK", 4, 1
        ns.Enchants.Invalidate()
        w.lua.execute("QUIET_SEEN = {}")
        M.enter(r)
        sc.check(len(w.all_lines(tt)) > 1 and en_count(w, tt) == 0, "enchants quiet: the sidebar row has no enchant lines")
        seen = [w.g.QUIET_SEEN[i] for i in range(1, len(w.g.QUIET_SEEN) + 1)]
        sc.check(len(seen) >= 1 and all(s.endswith("=true") for s in seen),
                 "enchants quiet: the sidebar row sets the tooltip with the flag up (%s)" % seen)
        tt.RefreshData(tt)
        sc.check(len(w.all_lines(tt)) > 0 and en_count(w, tt) == 0, "enchants quiet: the sidebar row after a refresh has none")
        M.leave(r)
        # A gear version's row sets the tooltip from a link (a place that gets enchant lines): a refresh
        # of it rebuilds it from that link, after the flag is down.
        vlink = ns.VariantLink
        w.lua.execute("QUIET_SEEN = {}")
        ns.VariantLink = w.lua.eval("function(id) return MOCK.ItemLink(id) end")
        M.enter(r)
        seen = [w.g.QUIET_SEEN[i] for i in range(1, len(w.g.QUIET_SEEN) + 1)]
        sc.eq(seen, ["SetHyperlink=true"], "enchants quiet: a version's sidebar row sets the tooltip from its link")
        sc.check(len(w.all_lines(tt)) > 1 and en_count(w, tt) == 0, "enchants quiet: a version's sidebar row has no enchant lines")
        tt.RefreshData(tt)
        sc.check(len(w.all_lines(tt)) > 0 and en_count(w, tt) == 0,
                 "enchants quiet: a version's sidebar row after a refresh has none (%s)" % [strip_codes(l or "") for l, _ in w.all_lines(tt)])
        M.leave(r)
        ns.VariantLink = vlink
        sc.check(not ns.tipQuiet, "enchants quiet: the flag is down after the sidebar row")
        tt.SetOwner(tt, g.UIParent, "ANCHOR_NONE")
        tt.SetHyperlink(tt, M.ItemLink(r.itemID))
        sc.eq(en_count(w, tt), 2, "enchants quiet: the same item from a link has the lines")
        it.equipLoc, it.classID, it.subclassID = None, None, None
    w.close_ah_modern()
    w.lua.execute("""
      local tt = GameTooltip
      tt.SetBagItem, tt.SetHyperlink, tt.SetItemByID = QUIET_OLD[1], QUIET_OLD[2], QUIET_OLD[3]""")
    sc.clean(w)


def sc_enchants_legacy(sc, ref, items):
    """The older client (OnTooltipSetItem): the same options, the tooltip laid out again; talent events it lacks are skipped."""
    w, prices = en_world(ref, items, client="legacy", mode="tabs-name", points=(31, 0, 0))
    sc.eq(w.ns.tooltipMode, "script", "enchants legacy: script hooks")
    for iid, want in ((990102, ["s20034", "s13898"]), (990108, ["s1219587", "s13419"])):
        tt = en_hover(w, "bag", iid)
