# --- consumes: the list under the character screen (Consumes.lua) ---
# The best food, potions, elixirs and scrolls (flasks, stones and oils when there are some) for
# the player's role and level hang under the character screen while its Character tab is up.
CS_SECTIONS = [("food", "FOOD", ["food"]), ("potion", "POTIONS", None), ("elixir", "ELIXIRS", ["elixir"]),
               ("scroll", "SCROLLS", ["scroll"]), ("flask", "FLASKS", ["flask"]),
               ("weapon", "STONES AND OILS", ["weapon"])]
CS_HEAD_H, CS_ROW_H, CS_GAP, CS_CAP, CS_MAX_LINES = 18, 16, 2, 24, 16
# The parts on the character screen's bottom edge the list must not cover.
CS_LOW = ["CharacterMainHandSlot", "CharacterSecondaryHandSlot", "CharacterRangedSlot", "CharacterAmmoSlot",
          "MockPawnRight", "MockGearMaticPrev", "MockGearMaticNext"]
# A UI 1080 units tall (ElvUI's pixel-perfect scale at 1080p, the player's): 480 under the frame.
CS_SCREEN = (1920, 1080, 1)
CS_HELP = ("/gl consumes : the best food, potions, elixirs and scrolls for you, under the character screen (on or off; "
           "best or budget)")
CS_OFF = "Goblin Ledger: the consumes list is off. /gl consumes on brings it back."
CS_ON = "Goblin Ledger: the consumes list is on: it shows under the character screen."
CS_COLOURS = {"text": (0.90, 0.88, 0.84), "muted": (0.55, 0.51, 0.45), "pos": (0.25, 0.80, 0.45),
              "buy": (0.898, 0.722, 0.259)}
CS_QC = {0: (0.62, 0.62, 0.62), 1: (1, 1, 1), 2: (0.12, 1, 0), 3: (0, 0.44, 0.87), 4: (0.64, 0.21, 0.93)}


def cs_hex(c):
    return "ff" + "".join("%02x" % int(math.floor(max(0, min(1, v)) * 255 + 0.5)) for v in c[:3])


_CS_ITEMS = {}


def cs_source_items():
    """Consumes.lua's items, read from the source: id -> (name, short name or None, section, level,
    quality, buff, xp %, vendor copper, group, classes (None: all, else a set))."""
    path = os.path.join(ADDON, "Consumes.lua")
    if path in _CS_ITEMS:
        return _CS_ITEMS[path]
    src = open(path, "rb").read().decode("ascii").replace("\r\n", "\n")
    block = src.split("local ITEMS = {", 1)[1].split("\n}", 1)[0]
    out = {}
    pat = re.compile(r'\[(\d+)\] = \{ "([^"]*)", (nil|"[^"]*"), "(\w+)", (\d+), (\d), "([^"]*)", (\d+), (\d+), "([^"]*)"'
                     r'(?:, "([A-Z,]+)")? \}')
    for m in pat.finditer(block):
        iid, name, short, sec, req, q, buff, xp, vend, grp, cls = m.groups()
        out[int(iid)] = (name, None if short == "nil" else short.strip('"'), sec, int(req), int(q), buff, int(xp),
                         int(vend), grp, set(cls.split(",")) if cls else None)
    if len(out) != block.count("\n  ["):
        raise SystemExit("cs_source_items: %d of %d item lines read" % (len(out), block.count("\n  [")))
    _CS_ITEMS[path] = out
    return out


def cs_test_price(iid):
    return 300 + (iid * 7919) % 30000   # made up, copper


def cs_unlisted(iid):
    return iid % 5 == 2   # not on the auction house in the test data


_CS_DATA = {}


def cs_data(ref):
    """The enchant test data with every consumable priced (made-up AH values), except the
    unlisted ones (none listed), and {id: AH value as the addon reads it}."""
    if DATA_FILE in _CS_DATA:
        return _CS_DATA[DATA_FILE]
    text = en_data(ref)[0]
    want = {iid: (0 if cs_unlisted(iid) else cs_test_price(iid)) for iid in cs_source_items()}
    a, b = block_span(text, "items")
    seen = set()
    pat = re.compile(r'(\[(\d+)\]\s*=\s*")((?:[^"\\\n]|\\.)*)"')

    def one(m):
        iid = int(m.group(2))
        if iid not in want:
            return m.group(0)
        seen.add(iid)
        f = m.group(3).split("|")
        f[2] = str(want[iid])
        if want[iid] == 0:
            f[1] = "0"
        return m.group(1) + "|".join(f) + '"'
    body = pat.sub(one, text[a:b])
    items = cs_source_items()
    add = ['[%d] = "%s|%d|%d|5|1|%d|0|;;|;;",' % (iid, items[iid][0], v, v, v)
           for iid, v in sorted(want.items()) if iid not in seen and v > 0]
    text = text[:a] + "".join("    %s\n" % ln for ln in add) + body + text[b:]
    _CS_DATA[DATA_FILE] = (text, dict(want))
    return _CS_DATA[DATA_FILE]


def cs_register(w):
    """The mock game knows each consumable (name, quality, an icon) as a commodity."""
    for iid, it in cs_source_items().items():
        if w.M["items"][iid] is None:
            bag_add_item(w, iid, it[0], it[4], 0, commodity=True)


def cs_world(ref, items, cls="WARRIOR", points=(31, 5, 0), level=60, screen=CS_SCREEN, before=None, **kw):
    if kw.get("data_src") is None:
        kw["data_src"] = cs_data(ref)[0]
    w, _ = char_world(ref, items, cls=cls, points=points, level=level, screen=screen, before=before, **kw)
    cs_register(w)
    return w


def cs_frame(w):
    return w.ns.Consumes.Frame()


def cs_open(w, tab="PaperDollFrame"):
    char_show(w, tab)
    w.settle(0.3)


def cs_reopen(w):
    char_close(w)
    cs_open(w)


def cs_cells(w):
    """What the list shows: section titles [(text, key, rect)] and rows [(id, key, left, right, rect, row)],
    each top to bottom, then left to right. Every shown row counts (one left up without an item has id 0)."""
    F = cs_frame(w)
    titles, rows = [], []
    for c in lua_kids(F):
        if not c.IsShown(c):
            continue
        if c.GetObjectType(c) == "FontString" and c.glKey is not None:
            titles.append((c.GetText(c), c.glKey, w.rect(c)))
        elif c.GetObjectType(c) == "Button" and c.glNoEnchants is True:
            rows.append((int(c.glID or 0), c.glKey, c.text.GetText(c.text), c.right.GetText(c.right), w.rect(c), c))
    titles.sort(key=lambda t: (-round(t[2][3], 3), t[2][0]))
    rows.sort(key=lambda r: (-round(r[4][3], 3), r[4][0]))
    return titles, rows


def cs_sections(w):
    """[(title, [ids])] in reading order; each row sits under its title, in its column."""
    titles, rows = cs_cells(w)
    out = []
    for text, key, tr in titles:
        ids = [r[0] for r in rows if r[1] == key and abs(r[4][0] - (tr[0] - 2)) < 0.01 and r[4][3] <= tr[1] + 8]
        out.append((text, ids))
    return out


def cs_expect(w, role, cls, level, all_=False, n=4):
    """The sections the list should show, from the data in Consumes.lua: the research's
    ranking for the level's band, then every usable one of the list (potions: one of each kind
    first), a group shown once, the best 4; or with all_ every usable one, best first. Nothing
    above the player's level or for another class."""
    D = w.ns.Consumes.DATA
    it = cs_source_items()
    band = 5 if level >= 60 else 4 if level >= 50 else 3 if level >= 40 else 2 if level >= 20 else 1

    def ok(lst):
        if lst == "potion-rage":
            return cls in ("WARRIOR", "DRUID")
        if lst == "potion-mana":
            return cls not in ("WARRIOR", "ROGUE")
        return True

    def lst_of(t):
        return [int(t[i]) for i in range(1, len(t) + 1)] if t is not None else []

    def can(i):
        return it[i][3] <= level and (it[i][9] is None or cls in it[i][9])
    out = []
    for key, title, lists in CS_SECTIONS:
        if lists is None:
            lists = [D.potions[role][i] for i in range(1, len(D.potions[role]) + 1)]
        if all_:
            ids, seen = [], set()
            for lst in lists:
                t = D.all[role][lst] if ok(lst) else None
                for i in lst_of(t):
                    if can(i) and i not in seen:
                        seen.add(i)
                        ids.append(i)
        else:
            per = []
            for lst in lists:
                b = D.best[role][lst]
                per.append(((lst_of(b[band]) if b is not None else []) + lst_of(D.all[role][lst])) if ok(lst) else [])
            ids, groups, pos, more = [], set(), [0] * len(per), True
            while len(ids) < n and more:
                more = False
                for k, lids in enumerate(per):
                    while pos[k] < len(lids):
                        i = lids[pos[k]]
                        pos[k] += 1
                        if can(i) and it[i][8] not in groups:
                            groups.add(it[i][8])
                            ids.append(i)
                            more = True
                            break
                    if len(ids) >= n:
                        break
        if ids:
            out.append((title, ids))
    return out


def cs_trim(secs, n):
    return [(t, ids[:n]) for t, ids in secs]


def cs_lines(secs, n, cols=2):
    """How many lines the list takes with n rows a section, sections side by side."""
    out = 0
    for k in range(0, len(secs), cols):
        out += 1 + max(min(n, len(ids)) for _, ids in secs[k:k + cols])
    return out


def cs_mana_only(iid):
    """A potion that gives mana and no health (a rejuvenation potion heals too)."""
    b = cs_source_items()[iid][5]
    return b.endswith(" mana") and not b.startswith("heals")


def cs_names(w, title):
    it = cs_source_items()
    return [it[i][0] for i in dict(cs_sections(w)).get(title, [])]


def cs_price(prices, iid, live=None, data=True):
    """The price words: the open AH's live listing, else a vendor's when it is cheaper, else
    today's AH value, else "not on AH" ("no prices" without price data)."""
    it = cs_source_items()[iid]
    vend = it[7]
    if live:
        return short_money(live), "text"
    m = prices.get(iid, 0) if data else 0
    if vend > 0 and (m <= 0 or vend <= m):
        return "vendor " + short_money(vend), "text"
    if m > 0:
        return short_money(m), "price"
    return ("not on AH" if data else "no prices"), "muted"


def cs_left(iid, level):
    it = cs_source_items()[iid]
    t = it[1] or it[0]
    if it[5]:
        t += " " + it[5]
    if it[6] > 0 and level < 60:
        t += " +%d%% XP" % it[6]
    return t


def cs_rows_ok(sc, w, prices, level, label, counts=None, stale=False, live=None, data=True, cls=None):
    """Every row: the name in its quality colour, the buff, +XP% in green where the data has it
    (below 60), the count, and the price in its colour (grey: old prices or none); nothing above
    the player's level or (cls) for another class; no row left up without an item."""
    counts, live = counts or {}, live or {}
    bad = []
    items = cs_source_items()
    for iid, key, left, right, rect, row in cs_cells(w)[1]:
        if iid not in items:
            bad.append((iid, "a row up without an item", strip_codes(left or "")))
            continue
        it = items[iid]
        want_l = cs_left(iid, level)
        words, kind = cs_price(prices, iid, live.get(iid), data)
        col = CS_COLOURS["muted"] if kind == "muted" or (kind == "price" and stale) else CS_COLOURS["text"]
        want_r = ("x%d " % counts[iid] if counts.get(iid) else "") + words
        if strip_codes(left) != want_l:
            bad.append((iid, "left", strip_codes(left), want_l))
        if not left.startswith("|c%s%s|r" % (cs_hex(CS_QC[it[4]]), it[1] or it[0])):
            bad.append((iid, "quality colour", left[:40]))
        xp = "|c%s+%d%% XP|r" % (cs_hex(CS_COLOURS["pos"]), it[6])
        if (it[6] > 0 and level < 60) != (xp in left):
            bad.append((iid, "XP in green", left))
        if strip_codes(right) != want_r:
            bad.append((iid, "right", strip_codes(right), want_r))
        if not right.endswith("|c%s%s|r" % (cs_hex(col), words)):
            bad.append((iid, "price colour", right, cs_hex(col)))
        if it[3] > level:
            bad.append((iid, "above the player's level", it[3]))
        if cls and it[9] is not None and cls not in it[9]:
            bad.append((iid, "not for a " + cls, sorted(it[9])))
    sc.eq(bad, [], "%s: every row's words and colours" % label)


def cs_lowest(w):
    """The lowest thing on the character screen's bottom edge (screen units): the frame, the shown
    weapon slots, Pawn's button, GearMatic's arrows and ElvUI's enchant labels with words in them
    (nothing more than 24 under the frame, in its scale)."""
    g = w.g
    cf = w.rect(g.CharacterFrame)
    cap = CS_CAP * g.CharacterFrame.GetEffectiveScale(g.CharacterFrame)
    low = cf[1]
    parts = []
    for n in CS_LOW + ["PawnUI_InventoryPawnButton", "GearMaticPaperdollPrev", "GearMaticPaperdollNext"]:
        f = g[n]
        if f is not None and f.IsVisible(f):
            parts.append(f)
            lab = f.enchantText
            if lab is not None and lab.IsVisible(lab) and (lab.GetText(lab) or "") != "":
                parts.append(lab)
    for f in parts:
        r = w.rect(f)
        if r and cf[1] - cap <= r[1] < low:
            low = r[1]
    return low


def cs_place_ok(sc, w, label, side="below", avoid=True):
    """As wide as the character screen and on screen; below: its top 2 under the lowest thing on the
    frame's bottom edge; above: its bottom 2 over the frame's top (and the portrait). It covers none
    of the panel's parts, Pawn's or GearMatic's buttons or the enchant labels."""
    g, C = w.g, w.ns.Consumes
    F = cs_frame(w)
    cf, r = w.rect(g.CharacterFrame), w.rect(F)
    if not sc.check(r is not None and cf is not None and F.IsVisible(F), "%s: the list is up and has a place" % label):
        return
    sc.check(abs(r[0] - cf[0]) < 0.01 and abs(r[2] - cf[2]) < 0.01,
             "%s: as wide as the character screen (%s, frame %s)" % (label, r, cf))
    sc.check(r[1] >= -0.01 and r[3] <= w.M.screenH + 0.01, "%s: all of it on screen (%s)" % (label, r))
    sc.eq(C.Layout().side, side, "%s: the side" % label)
    gap = CS_GAP * F.GetEffectiveScale(F)   # 2 in the list's own scale
    if side == "below":
        low = cs_lowest(w)
        sc.check(abs(r[3] - (low - gap)) < 0.01, "%s: its top 2 under the lowest part (top %s, lowest %s)" % (label, r[3], low))
    else:
        high = cf[3]
        p = g.CharacterFramePortrait
        if p is not None and p.IsVisible(p):
            high = max(high, w.rect(p)[3])
        sc.check(abs(r[1] - (high + gap)) < 0.01, "%s: its bottom 2 over the frame's top (%s, top %s)" % (label, r[1], high))
    h = F.GetHeight(F)
    lines = C.Layout().lines
    sc.eq(h, CS_HEAD_H + (1 + lines * CS_ROW_H + 3 if lines > 0 else 0), "%s: the height fits its lines" % label)
    if avoid:
        others = {}
        for n in TG_AVOID + ["PawnUI_InventoryPawnButton", "GearMaticPaperdollPrev", "GearMaticPaperdollNext"]:
            f = g[n]
            if f is not None and f.IsVisible(f):
                others[n] = w.rect(f)
                lab = f.enchantText
                if lab is not None and lab.IsVisible(lab) and (lab.GetText(lab) or "") != "":
                    others[n + ".enchantText"] = w.rect(lab)
        sc.eq(sorted(n for n, o in others.items() if o is not None and _overlap(r, o)), [], "%s: covers nothing" % label)
    # Every row and title is inside the list, and rows of one line do not overlap.
    titles, rows = cs_cells(w)
    out = [t[0] for t in titles if not (r[0] <= t[2][0] and t[2][2] <= r[2] + 0.01 and r[1] <= t[2][1] and t[2][3] <= r[3])]
    out += [x[0] for x in rows if not (r[0] <= x[4][0] and x[4][2] <= r[2] + 0.01 and r[1] <= x[4][1] and x[4][3] <= r[3])]
    sc.eq(out, [], "%s: every line inside the list" % label)
    clash = [(a[0], b[0]) for i, a in enumerate(rows) for b in rows[i + 1:] if _overlap(a[4], b[4])]
    sc.eq(clash, [], "%s: no two rows overlap" % label)


def cs_header(w):
    F = cs_frame(w)
    return strip_codes(F.title.GetText(F.title))


def sc_consumes_place(sc, ref, items):
    """The list hangs right under the character screen when it opens, as wide as it, under the
    weapon slots, Pawn's button and GearMatic's arrows (read from the frames each time)."""
    w = cs_world(ref, items)
    M, g, ns = w.M, w.g, w.ns
    C = ns.Consumes
    F = cs_frame(w)
    if not sc.check(F is not None and w.same(F, g.GoblinLedgerConsumes), "place: the list is made when the addon loads"):
        sc.clean(w)
        return
    sc.eq(C.builds, 1, "place: made once")
    sc.check(w.same(F.GetParent(F), g.PaperDollFrame), "place: its parent is PaperDollFrame (the Character tab)")
    sc.check(not any(w.same(c, F) for c in lua_kids(g.PaperDollItemsFrame)),
             "place: not one of PaperDollItemsFrame's children (ElvUI skins those as slots)")
    sc.check(not F.IsVisible(F), "place: not on screen before the character screen opens")
    sc.check(F._clamped is True and F.IsMouseEnabled(F), "place: kept on screen, takes the mouse")
    cs_open(w)
    sc.check(F.IsVisible(F), "place: shown when the character screen opens")
    cs_place_ok(sc, w, "place: Forever's layout")
    L = C.Layout()
    sc.eq((L.side, L.n, L.cols, L.lines), ("below", 4, 2, L.total), "place: under the frame, the best 4, 2 columns, all lines")
    sc.eq(cs_header(w), "Consumes for melee, level 60", "place: the header")
    want = cs_expect(w, "melee", "WARRIOR", 60)
    sc.eq([t for t, _ in want][:4], ["FOOD", "POTIONS", "ELIXIRS", "SCROLLS"], "place: food, potions, elixirs, scrolls first")
    sc.eq(cs_sections(w), want, "place: the sections and the best 4 of each, in reading order")
    titles, rows = cs_cells(w)
    sc.eq(len({round(t[2][1], 3) for t in titles[:2]}), 1, "place: two sections side by side")
    sc.check(F.header.IsVisible(F.header) and F.allButton.IsVisible(F.allButton), "place: header and All switch up")
    # The parts on the bottom edge by their real names (Pawn, GearMatic): one hanging under the
    # frame pushes the list down; one far under it (some other popup) does not.
    w.lua.execute("PawnUI_InventoryPawnButton = MockPawnRight; GearMaticPaperdollPrev = MockGearMaticPrev; "
                  "GearMaticPaperdollNext = MockGearMaticNext")
    pawn = g.MockPawnRight
    pawn.ClearAllPoints(pawn)
    pawn.SetPoint(pawn, "TOPRIGHT", g.CharacterFrame, "BOTTOMRIGHT", -250, 14)
    w.settle(0.3)
    cf = w.rect(g.CharacterFrame)
    sc.check(abs(w.rect(F)[3] - (cf[1] - 12)) < 0.01, "place: Pawn's button 10 under the frame: the list 2 under it (%s)" % (w.rect(F),))
    cs_place_ok(sc, w, "place: Pawn's button under the frame")
    nxt = g.MockGearMaticNext
    nxt.ClearAllPoints(nxt)
    nxt.SetPoint(nxt, "TOPLEFT", g.CharacterFrame, "BOTTOMLEFT", 450, -30)
    w.settle(0.3)
    sc.check(abs(w.rect(F)[3] - (cf[1] - 12)) < 0.01, "place: something 30 under the frame is not followed (%s)" % (w.rect(F),))
    nxt.ClearAllPoints(nxt)
    nxt.SetPoint(nxt, "LEFT", g.CharacterRangedSlot, "RIGHT", 6, 0)
    pawn.ClearAllPoints(pawn)
    pawn.SetPoint(pawn, "TOPRIGHT", g.CharacterTrinket1Slot, "BOTTOMRIGHT", 4, -18)
    w.settle(0.3)
    cs_place_ok(sc, w, "place: back in their places")
    sc.check(abs(w.rect(F)[3] - (cf[1] - 2)) < 0.01, "place: back right under the frame")
    polls = C.polls
    w.tick(60, 1 / 60.0)
    sc.check(3 <= C.polls - polls <= 5, "place: one second at 60 fps: the frames read 4 times (%d)" % (C.polls - polls))
    sc.clean(w, "place")
    # Hunters, warriors and rogues have the ammo slot (GearMatic's arrow right of it).
    w = cs_world(ref, items, cls="HUNTER", points=(31, 5, 0), char={"ammo": True})
    cs_open(w)
    sc.check(w.g.CharacterAmmoSlot.IsVisible(w.g.CharacterAmmoSlot), "place: ammo slot up")
    cs_place_ok(sc, w, "place: with the ammo slot")
    sc.eq(cs_header(w), "Consumes for hunter, level 60", "place: a hunter's header")
    sc.eq(cs_sections(w), cs_expect(w, "hunter", "HUNTER", 60), "place: a hunter's sections")
    sc.clean(w, "place: ammo")


def cs_elv_world(ref, items, layout=True, **o):
    def setup(w):
        w.M.InstallBlizzardBags()
        w.M.InstallElvUIAddon(w.to_lua(o))
    w = cs_world(ref, items, before=setup)
    if layout:
        w.M.ElvUICharacterLayout()
    return w


def sc_consumes_place_elvui(sc, ref, items):
    """With ElvUI: the weapon slots 6 over the frame's bottom, its enchant labels (the off hand's
    hangs 3 under the frame, and may be filled after the list shows): the list goes under them,
    in ElvUI's own panel look."""
    w = cs_elv_world(ref, items)
    M, g, C = w.M, w.g, w.ns.Consumes
    F = cs_frame(w)
    M.ElvUIEnchantLabels(w.to_lua(["Encha: Fiery Blaze", "Encha: Crusader", ""]))
    cs_open(w)
    cf = w.rect(g.CharacterFrame)
    mh = w.rect(g.CharacterMainHandSlot)
    sc.check(abs(mh[1] - (cf[1] + 6)) < 0.01, "elvui: the weapon row 6 over the frame's bottom (%s)" % (mh,))
    oh = w.rect(g.CharacterSecondaryHandSlot.enchantText)
    sc.check(abs(oh[1] - (cf[1] - 3)) < 0.01, "elvui: the off hand's label hangs 3 under the frame (%s)" % (oh,))
    cs_place_ok(sc, w, "elvui: under the off hand's enchant label")
    sc.check(abs(w.rect(F)[3] - (cf[1] - 5)) < 0.01, "elvui: its top 5 under the frame's bottom")
    sc.eq((C.look, F._template), ("elvui", "Transparent"), "elvui: ElvUI's Transparent look, as its character screen")
    sc.eq(sum(1 for i in range(1, len(M.elvTemplates) + 1) if w.same(M.elvTemplates[i], F)), 1, "elvui: skinned once")
    sc.check(not F.IsMouseWheelEnabled(F), "elvui: nothing to scroll: the wheel zooms the camera")
    # The labels go (no off-hand enchant): back right under the frame.
    M.ElvUIEnchantLabels(w.to_lua(["Encha: Fiery Blaze", "", ""]))
    w.settle(0.3)
    cs_place_ok(sc, w, "elvui: no off-hand enchant")
    sc.check(abs(w.rect(F)[3] - (cf[1] - 2)) < 0.01, "elvui: an empty label is not avoided")
    cs_reopen(w)
    sc.eq(sum(1 for i in range(1, len(M.elvTemplates) + 1) if w.same(M.elvTemplates[i], F)), 1, "elvui: still skinned once")
    # ElvUI fills the labels after the list showed (its own OnShow hook): the list moves under them.
    char_close(w)
    M.ElvUIEnchantLabels(w.to_lua(["", "", ""]))
    cs_open(w)
    sc.check(abs(w.rect(F)[3] - (cf[1] - 2)) < 0.01, "elvui: right under the frame while the labels are empty")
    M.ElvUIEnchantLabels(w.to_lua(["Encha: Fiery Blaze", "Encha: Crusader", "Encha: Biznicks"]))
    w.settle(0.3)
    cs_place_ok(sc, w, "elvui: labels filled after it showed")
    sc.check(abs(w.rect(F)[3] - (cf[1] - 5)) < 0.01, "elvui: moved under the late label")
    sc.clean(w, "elvui")
    # The player's UI scale (ElvUI 0.62 on a 768 high window): the gap, the labels and the frame
    # all in that scale; still under the off hand's label, on screen, as wide as the frame.
    def setup(w_):
        w_.M.InstallBlizzardBags()
        w_.M.InstallElvUIAddon(w_.to_lua({}))
    w = cs_world(ref, items, screen=(1395, 768, 0.62), before=setup)
    w.M.ElvUICharacterLayout()
    w.M.ElvUIEnchantLabels(w.to_lua(["Encha: Fiery Blaze", "Encha: Crusader", ""]))
    cs_open(w)
    g = w.g
    F = cs_frame(w)
    e = F.GetEffectiveScale(F)
    sc.check(abs(e - 0.62) < 1e-6, "elvui 0.62: the list's scale (%s)" % e)
    cf = w.rect(g.CharacterFrame)
    oh = w.rect(g.CharacterSecondaryHandSlot.enchantText)
    sc.check(abs(oh[1] - (cf[1] - 3 * e)) < 0.01, "elvui 0.62: the off hand's label 3 under the frame (%s, %s)" % (oh, cf))
    cs_place_ok(sc, w, "elvui 0.62: under the off hand's label")
    sc.check(abs(w.rect(F)[3] - (cf[1] - 5 * e)) < 0.01, "elvui 0.62: its top 5 under the frame's bottom (%s)" % (w.rect(F),))
    sc.eq(w.ns.Consumes.Layout().n, 4, "elvui 0.62: room for the best 4 under it")
    sc.clean(w, "elvui 0.62")
    # ElvUI's character skin off: the addon's own flat look, the game's layout.
    w = cs_elv_world(ref, items, layout=False, characterSkin=False)
    cs_open(w)
    F = cs_frame(w)
    sc.eq((w.ns.Consumes.look, F._template), ("plain", None), "elvui: character skin off: the plain look")
    sc.check(F._backdrop is not None, "elvui: character skin off: its own backdrop")
    cs_place_ok(sc, w, "elvui: character skin off")
    sc.clean(w, "elvui: skin off")
    # The list up before login (before ElvUI is set up): the plain look then, ElvUI's the next time.
    w = cs_elv_world(ref, items, layout=False)
    F = cs_frame(w)
    w.lua.execute("MOCK.elvReady = false; ElvUI[1].modules.Skins.Initialized = false")
    F.glLookDone = None
    cs_open(w)
    sc.eq((w.ns.Consumes.look, F._template), ("plain", None), "elvui early: the plain look before ElvUI is set up")
    char_close(w)
    w.lua.execute("MOCK.elvReady = true; ElvUI[1].modules.Skins.Initialized = true")
    cs_open(w)
    sc.eq((w.ns.Consumes.look, F._template), ("elvui", "Transparent"), "elvui early: ElvUI's look once it is set up")
    sc.clean(w, "elvui early")


def sc_consumes_fold(sc, ref, items):
    """The stats pane folded away (398 wide): the list follows the width by itself."""
    w = cs_world(ref, items)
    g, C = w.g, w.ns.Consumes
    F = cs_frame(w)
    cs_open(w)
    cf = g.CharacterFrame
    wide = C.Layout().colW
    cf.SetWidth(cf, 398)
    g.CharacterFrameRightPaneHost.Hide(g.CharacterFrameRightPaneHost)
    w.settle(0.3)
    sc.eq(round(F.GetWidth(F), 3), 398, "fold: 398 wide with the stats pane folded")
    L = C.Layout()
    sc.check(L.cols == 2 and L.colW < wide, "fold: still 2 columns, narrower (%s, %s)" % (L.cols, L.colW))
    cs_place_ok(sc, w, "fold: folded")
    sc.eq(cs_sections(w), cs_expect(w, "melee", "WARRIOR", 60), "fold: the same lists")
    cf.SetWidth(cf, 631)
    g.CharacterFrameRightPaneHost.Show(g.CharacterFrameRightPaneHost)
    w.settle(0.3)
    sc.eq((round(F.GetWidth(F), 3), C.Layout().colW), (631, wide), "fold: back to 631")
    cs_place_ok(sc, w, "fold: open again")
    sc.clean(w, "fold")


def sc_consumes_tabs(sc, ref, items):
    """Only with the Character tab: not on the other tabs, gone with the character screen, back when
    it opens; the game's frames keep their scripts; made once, no new rows when it opens again."""
    w = cs_world(ref, items)
    M, g, C = w.M, w.g, w.ns.Consumes
    F = cs_frame(w)
    kept, which = M.CharScriptsKept()
    sc.check(kept, "tabs: the game's frames keep their own scripts (%s)" % which)
    hooks = {n: sum(len(g[n]._hooks[k] or {}) for k in ("OnShow", "OnHide"))
             for n in ("CharacterFrame", "PaperDollFrame", "PaperDollItemsFrame")}
    cs_open(w)
    sc.check(F.IsVisible(F), "tabs: on the Character tab")
    buttons = int(M.counts.Button or 0)
    for tab in ("ReputationFrame", "SkillsFrame", "PVPRankFrame", "TokenFrame"):
        cs_open(w, tab)
        sc.check(not F.IsVisible(F), "tabs: not on the %s tab" % tab)
    cs_open(w)
    sc.check(F.IsVisible(F), "tabs: back on the Character tab")
    cs_place_ok(sc, w, "tabs: back")
    M.CharacterPetPage(True)
    w.settle(0.3)
    sc.check(F.IsVisible(F), "tabs: still up on the pet's page")
    cs_place_ok(sc, w, "tabs: the pet's page (no slots)")
    M.CharacterPetPage(False)
    char_close(w)
    sc.check(not F.IsVisible(F), "tabs: gone when the character screen closes")
    w.g.ToggleCharacter("PaperDollFrame")
    w.settle(0.3)
    sc.check(F.IsVisible(F), "tabs: back when it opens again")
    w.g.ToggleCharacter("PaperDollFrame")
    sc.check(not F.IsVisible(F), "tabs: the key again closes both")
    cs_open(w)
    sc.eq(int(M.counts.Button or 0), buttons, "tabs: no new buttons when it opens again")
    sc.eq(C.builds, 1, "tabs: made once")
    kept, which = M.CharScriptsKept()
    sc.check(kept, "tabs: still their own scripts (%s)" % which)
    sc.eq({n: sum(len(g[n]._hooks[k] or {}) for k in ("OnShow", "OnHide"))
           for n in ("CharacterFrame", "PaperDollFrame", "PaperDollItemsFrame")}, hooks, "tabs: no hooks added on the game's frames")
    # The auction house (or a drag) moves the character screen: the list goes with it.
    cf = g.CharacterFrame
    cf.ClearAllPoints(cf)
    cf.SetPoint(cf, "TOPLEFT", g.UIParent, "TOPLEFT", 700, -116)
    w.settle(0.3)
    cs_place_ok(sc, w, "tabs: the frame moved right")
    for ev, args in (("ADDON_LOADED", ("Blizzard_UIPanels_Game",)), ("PLAYER_LOGIN", ()), ("PLAYER_ENTERING_WORLD", (False, True))):
        M.fire(ev, *args)
    C.Build()
    sc.eq(C.builds, 1, "tabs: still made once")
    sc.clean(w, "tabs")


def cs_move(w, bottom):
    """The character screen dragged so its bottom is at this height."""
    g = w.g
    cf = g.CharacterFrame
    cf.ClearAllPoints(cf)
    cf.SetPoint(cf, "TOPLEFT", g.UIParent, "TOPLEFT", 16, -(w.M.screenH - bottom - 484))


def sc_consumes_room(sc, ref, items):
    """Near the bottom of the screen: fewer rows a section, then above the character screen,
    then what fits, scrolled; never off screen."""
    # The game's default UI (768 tall): the frame's bottom at 168, room for the best 2 a section.
    w = cs_world(ref, items, screen=(1365, 768, 1))
    C = w.ns.Consumes
    cs_open(w)
    sc.eq(w.rect(w.g.CharacterFrame)[1], 168, "room: a 768 UI: the frame's bottom at 168")
    L = C.Layout()
    sc.eq((L.side, L.n), ("below", 2), "room: a 768 UI: the best 2 a section, under the frame")
    cs_place_ok(sc, w, "room: 768")
    sc.eq(cs_sections(w), cs_trim(cs_expect(w, "melee", "WARRIOR", 60), 2), "room: 768: the best 2 of each")
    # Dragged low: above the frame, 3 a section (room above for 3 a section, not for 4).
    want = cs_expect(w, "melee", "WARRIOR", 60)
    l3, l4 = cs_lines(want, 3), cs_lines(want, 4)
    sc.check(l3 < l4, "room: the best 3 take fewer lines than the best 4 (%d, %d)" % (l3, l4))
    g = w.g
    over = w.rect(g.CharacterFramePortrait)[3] - w.rect(g.CharacterFrame)[3]
    low = w.M.screenH - 484 - over - CS_GAP - (CS_HEAD_H + 4 + l3 * CS_ROW_H + CS_ROW_H / 2)
    cs_move(w, low)
    w.settle(0.3)
    L = C.Layout()
    sc.eq((L.side, L.n, L.lines), ("above", 3, l3), "room: frame bottom at %d: above it, the best 3" % low)
    cs_place_ok(sc, w, "room: bottom at %d" % low, side="above")
    sc.eq(cs_sections(w), cs_trim(cs_expect(w, "melee", "WARRIOR", 60), 3), "room: above: the best 3 of each")
    cs_move(w, 20)
    w.settle(0.3)
    sc.eq((C.Layout().side, C.Layout().n), ("above", 4), "room: frame bottom at 20: above it, room for the best 4")
    cs_place_ok(sc, w, "room: bottom at 20", side="above")
    # Room for 4 again: under it, all 4.
    cs_move(w, 300)
    w.settle(0.3)
    sc.eq((C.Layout().side, C.Layout().n), ("below", 4), "room: frame bottom at 300: under it, the best 4")
    cs_place_ok(sc, w, "room: bottom at 300")
    sc.clean(w, "room")
    # A short screen: no room under nor over it for 2 a section: what fits above, scrolled, on screen.
    w = cs_world(ref, items, screen=(1365, 640, 1))
    C = w.ns.Consumes
    cs_open(w)
    L = C.Layout()
    sc.check(L.side == "above" and 0 < L.lines < L.total, "room: a 640 UI: what fits above it, the rest scrolls (%s, %s/%s)"
             % (L.side, L.lines, L.total))
    cs_place_ok(sc, w, "room: 640", side="above")
    F = cs_frame(w)
    sc.check(F.scrollBar.IsVisible(F.scrollBar), "room: 640: a scroll bar")
    sc.clean(w, "room: short screen")


def sc_consumes_collapse(sc, ref, items):
    """A click on the header folds the list to its one line, remembered; another opens it."""
    w = cs_world(ref, items)
    g, M, ns = w.g, w.M, w.ns
    S, C = ns.settings, ns.Consumes
    F = cs_frame(w)
    cs_open(w)
    sc.eq(F.arrow.GetText(F.arrow), "v", "collapse: the arrow points down while open")
    M.click(F.header)
    sc.eq(S.consumesCollapsed, True, "collapse: remembered")
    sc.eq((F.GetHeight(F), C.Layout().collapsed, F.arrow.GetText(F.arrow)), (CS_HEAD_H, True, ">"), "collapse: the header only")
    titles, rows = cs_cells(w)
    sc.eq((len(titles), len(rows)), (0, 0), "collapse: no sections, no rows")
    sc.check(not F.allButton.IsVisible(F.allButton), "collapse: no All switch")
    sc.eq(cs_header(w), "Consumes for melee, level 60", "collapse: the header says it all")
    cs_place_ok(sc, w, "collapse: folded")
    cs_reopen(w)
    sc.eq((F.GetHeight(F), C.Layout().collapsed), (CS_HEAD_H, True), "collapse: still folded when it opens again")
    M.click(F.header)
    sc.check(S.consumesCollapsed is None and not C.Layout().collapsed, "collapse: a second click opens it")
    sc.eq(cs_sections(w), cs_expect(w, "melee", "WARRIOR", 60), "collapse: the rows are back")
    M.click(F.header)
    sc.clean(w, "collapse")
    # Saved: folded after a reload.
    w = cs_world(ref, items, saved={"consumesCollapsed": True})
    F = cs_frame(w)
    cs_open(w)
    sc.eq((F.GetHeight(F), w.ns.Consumes.Layout().collapsed), (CS_HEAD_H, True), "collapse: folded after a reload")
    w.M.click(F.header)
    sc.eq(cs_sections(w), cs_expect(w, "melee", "WARRIOR", 60), "collapse: and opens with a click")
    sc.clean(w, "collapse saved")


def cs_row(w, pred=None):
    for r in cs_cells(w)[1]:
        if pred is None or pred(r[0]):
            return r
    return None


def sc_consumes_clicks(sc, ref, items):
    """A click on a row at the auction house searches it; with the auction house closed it does
    nothing; shift-click puts its link in chat and does not search."""
    w = cs_world(ref, items)
    M, g, ns = w.M, w.g, w.ns
    cs_open(w)
    iid, _, _, _, _, row = cs_row(w)
    mark = w.chat_mark()
    M.click(row)
    w.settle(0.3)
    sc.eq(w.chat(mark), [], "clicks: the auction house closed: nothing said")
    w.open_ah_modern()
    box = g.AuctionHouseFrame.SearchBar.SearchBox
    box.SetText(box, "")
    M.click(row)
    w.settle(0.4)
    sc.eq(box.GetText(box), ns.ItemName(iid), "clicks: at the auction house a click searches it")
    other = cs_row(w, lambda i: i != iid)
    M.click(other[5])
    w.settle(0.4)
    sc.eq(box.GetText(box), ns.ItemName(other[0]), "clicks: another row searches that one")
    # Shift-click: the link in chat, no search.
    w.lua.execute("MOCK.inserted = {}; ChatFrameUtil = nil; "
                  "ChatEdit_InsertLink = function(ln) table.insert(MOCK.inserted, ln) return true end")
    w.lua.execute("IsModifiedClick = function(k) return k == 'CHATLINK' end")
    box.SetText(box, "")
    M.click(row)
    w.lua.execute("IsModifiedClick = function() return false end")
    inserted = list(M.inserted.values())
    sc.check(len(inserted) == 1 and "item:%d" % iid in str(inserted[0]), "clicks: shift-click links it in chat (%s)" % inserted)
    sc.eq(box.GetText(box), "", "clicks: and does not search")
    w.close_ah_modern()
    box.SetText(box, "")
    M.click(row)
    w.settle(0.3)
    sc.eq(box.GetText(box), "", "clicks: the auction house closed again: no search")
    sc.clean(w, "clicks")


def sc_consumes_tooltip(sc, ref, items):
    """Hover a row: the game's tooltip for the item with Goblin Ledger's price lines (no enchant
    lines); it goes with the mouse."""
    w = cs_world(ref, items)
    M, g = w.M, w.g
    cs_open(w)
    _, prices = cs_data(ref)
    iid, _, _, _, _, row = cs_row(w, lambda i: prices.get(i, 0) > 0)
    tt = g.GameTooltip
    # What ns.tipQuiet was while the row set the tooltip up (no enchant lines then).
    w.lua.eval("function(ns) local tt = GameTooltip; local o = tt.SetItemByID; "
               "tt.SetItemByID = function(self, ...) MOCK.quietSeen = ns.tipQuiet; return o(self, ...) end end")(w.ns)
    M.enter(row)
    sc.check(tt.IsShown(tt) and w.same(tt.GetOwner(tt), row), "tooltip: shown, owned by the row")
    sc.eq(M.quietSeen, True, "tooltip: ns.tipQuiet while the row sets the item")
    lines = [l or "" for l, _ in w.all_lines(tt)]
    sc.check(len(lines) > 0 and str(M["items"][iid].name) in lines[0], "tooltip: the item's own tooltip (%s)" % lines[:2])
    sc.check(any(l.startswith("AH value") for l in lines), "tooltip: with Goblin Ledger's price lines (%s)" % lines)
    sc.check(not any(l.startswith("Best enchant") for l in lines), "tooltip: no enchant lines")
    sc.check(row.glNoEnchants is True and not w.ns.tipQuiet, "tooltip: the row marks itself, tipQuiet back off")
    M.leave(row)
    sc.check(not tt.IsShown(tt), "tooltip: gone with the mouse")
    sc.clean(w, "tooltip")


def sc_consumes_prices(sc, ref, items):
    """Each row's price: today's AH value, a vendor's price when cheaper, "not on AH"; grey when the
    prices are over 6 hours old; the live listing at the auction house; the bag count; no data."""
    text, prices = cs_data(ref)
    w = cs_world(ref, items, level=35)
    M, g, ns = w.M, w.g, w.ns
    cs_open(w)
    cs_rows_ok(sc, w, prices, 35, "prices")
    kinds = {cs_price(prices, r[0])[1] if not cs_price(prices, r[0])[0].startswith("vendor") else "vendor"
             for r in cs_cells(w)[1]}
    sc.check({"price", "vendor", "muted"} <= kinds, "prices: the test shows AH values, vendor prices and not on AH (%s)" % kinds)
    # Bag counts: x3 once they are in the bags (after the game says the bags changed).
    rows = cs_cells(w)[1]
    a, b = rows[0][0], rows[1][0]
    w.put_bag(0, 1, a, 2)
    w.put_bag(1, 4, a, 1)
    w.put_bag(0, 2, b, 20)
    M.fire("BAG_UPDATE_DELAYED")
    w.settle(0.1)
    cs_rows_ok(sc, w, prices, 35, "prices: bag counts", counts={a: 3, b: 20})
    # The live listing while the auction house shows it.
    w.open_ah_modern()
    w.set_commodity_results(a, [(1234, 5, False)])
    M.fire("COMMODITY_SEARCH_RESULTS_UPDATED", a)
    w.settle(0.3)
    sc.eq(w.live(a), 1234, "prices: the auction house has a live listing")
    cs_rows_ok(sc, w, prices, 35, "prices: the live listing", counts={a: 3, b: 20}, live={a: 1234})
    w.close_ah_modern()
    cs_rows_ok(sc, w, prices, 35, "prices: auction house closed", counts={a: 3, b: 20})
    sc.clean(w, "prices")
    # Over 6 hours old: AH values grey (vendor prices are not).
    w = cs_world(ref, items, level=35, now=ref.updated + 7 * 3600)
    cs_open(w)
    cs_rows_ok(sc, w, prices, 35, "prices: 7 hours old", stale=True)
    sc.clean(w, "prices: stale")
    # No price data at all: vendor prices and "no prices", no error.
    w = cs_world(ref, items, level=35, data_src=PLACEHOLDER)
    cs_open(w)
    cs_rows_ok(sc, w, prices, 35, "prices: no data", data=False)
    sc.eq(cs_sections(w), cs_expect(w, "melee", "WARRIOR", 35), "prices: no data: the same lists")
    sc.clean(w, "prices: no data", ok_chat=())


def sc_consumes_roles(sc, ref, items):
    """The lists follow the role (talents, or a /gl enchants pick) and the level: nothing the player
    cannot use yet, potions by the class (rage for warriors and druids), +5% XP on food below 60."""
    _, prices = cs_data(ref)
    w = cs_world(ref, items)
    ns = w.ns
    cases = [("WARRIOR", (31, 5, 0), 60, "melee"), ("WARRIOR", (0, 5, 31), 60, "tank"), ("MAGE", (0, 31, 20), 60, "caster"),
             ("ROGUE", (5, 31, 15), 60, "agility"), ("PRIEST", (31, 20, 0), 60, "healer"), ("HUNTER", (31, 20, 0), 60, "hunter"),
             ("PALADIN", (0, 31, 0), 60, "tank"), ("DRUID", (0, 31, 0), 60, "agility"),
             ("WARRIOR", (25, 5, 0), 35, "melee"), ("MAGE", (0, 0, 20), 25, "caster"), ("WARRIOR", (0, 0, 0), 12, "melee"),
             ("PRIEST", (0, 20, 0), 44, "healer"), ("ROGUE", (0, 30, 0), 52, "agility"),
             ("PALADIN", (0, 0, 31), 60, "melee"), ("SHAMAN", (0, 31, 5), 60, "melee"), ("WARRIOR", (20, 0, 0), 20, "melee"),
             ("WARLOCK", (31, 0, 0), 60, "caster"), ("PRIEST", (31, 20, 0), 30, "healer")]
    seen = {}
    for cls, pts, lvl, role in cases:
        en_player(w, cls, pts, "forever", lvl)
        cs_reopen(w)
        label = "roles: %s %s level %d" % (cls, pts, lvl)
        sc.eq(cs_header(w), "Consumes for %s, level %d" % (role, lvl), label + ": header")
        want = cs_expect(w, role, cls, lvl)
        got = cs_sections(w)
        sc.eq(got, want, label + ": sections, best 4")
        cs_rows_ok(sc, w, prices, lvl, label, cls=cls)
        sc.check(all(len(ids) <= 4 for _, ids in got) and all(len(ids) == len(set(ids)) for _, ids in got),
                 label + ": at most 4 a section, none twice")
        items_ = cs_source_items()
        groups = [[items_[i][8] for i in ids] for _, ids in got]
        sc.check(all(len(g_) == len(set(g_)) for g_ in groups), label + ": two of one group never both in the best 4")
        rage = [i for _, ids in got for i in ids if "rage" in items_[i][5]]
        sc.check(bool(rage) == (cls in ("WARRIOR", "DRUID") and role in ("melee", "tank")),
                 label + ": rage potions only for warriors (%s)" % rage)
        mana = [i for t, ids in got if t == "POTIONS" for i in ids if cs_mana_only(i)]
        sc.check(not mana or cls not in ("WARRIOR", "ROGUE"), label + ": no mana potions for warriors and rogues (%s)" % mana)
        if cls in ("PALADIN", "SHAMAN", "MAGE", "PRIEST", "WARLOCK") and lvl >= 20:
            sc.check(len(mana) == 1, label + ": a mana potion for a mana user (%s)" % mana)
        food = dict(got).get("FOOD", [])
        lefts = {r[0]: strip_codes(r[2]) for r in cs_cells(w)[1]}
        xp = [i for i in food if "+5% XP" in lefts[i]]
        if lvl < 60:
            sc.eq(sorted(xp), sorted(i for i in food if items_[i][6] > 0), label + ": +5% XP on Well Fed food")
            sc.check(len(xp) > 0, label + ": some food gives XP")
        else:
            sc.eq(xp, [], label + ": no XP at 60")
        sc.check(not any("XP" in strip_codes(r[2]) for r in cs_cells(w)[1] if r[1] != "food"), label + ": XP only on food")
        seen[(cls, pts, lvl)] = got
    sc.check(seen[("WARRIOR", (31, 5, 0), 60)] != seen[("WARRIOR", (0, 5, 31), 60)] != seen[("MAGE", (0, 31, 20), 60)],
             "roles: melee, tank and caster lists differ")
    names = lambda key, title: [cs_source_items()[i][0] for i in dict(seen[key]).get(title, [])]
    sc.eq(names(("WARRIOR", (31, 5, 0), 60), "FOOD")[0], "Poached Sunscale Salmon", "roles: a fury warrior's best food (+40 AP)")
    sc.eq(names(("MAGE", (0, 31, 20), 60), "FOOD")[0], "Lobster Stew", "roles: a mage's best food (+28 spell damage)")
    sc.eq(names(("MAGE", (0, 31, 20), 60), "POTIONS")[0], "Major Mana Potion", "roles: a mage's first potion")
    sc.check("Flask of Supreme Power" in names(("MAGE", (0, 31, 20), 60), "FLASKS"), "roles: a mage's flask")
    sc.check("Flask of the Titans" in names(("WARRIOR", (0, 5, 31), 60), "FLASKS"), "roles: a tank's flask")
    sc.eq(names(("WARRIOR", (31, 5, 0), 60), "SCROLLS")[:2], ["Scroll of Strength IV", "Scroll of Agility IV"],
          "roles: one scroll of each stat (Strength III is the same buff)")
    sc.eq(names(("WARRIOR", (31, 5, 0), 60), "ELIXIRS")[:2], ["Elixir of the Grizzly", "Elixir of the Mongoose"],
          "roles: one elixir of each stat line")
    sc.check("FLASKS" not in dict(seen[("WARRIOR", (25, 5, 0), 35)]), "roles: no flask at 35")
    sc.check("Great Rage Potion" in names(("WARRIOR", (25, 5, 0), 35), "POTIONS"), "roles: a level 35 warrior's rage potion")
    # A role picked by hand (/gl enchants) wins over the talents, also while the enchant tips are off.
    en_player(w, "WARRIOR", (31, 5, 0), "forever", 60)
    cs_reopen(w)
    w.slash("/gl enchants tank")
    w.settle(0.1)
    sc.eq(cs_header(w), "Consumes for tank, level 60", "roles: /gl enchants tank: at once")
    sc.eq(cs_sections(w), cs_expect(w, "tank", "WARRIOR", 60), "roles: /gl enchants tank: a tank's lists")
    w.slash("/gl enchants off")
    cs_reopen(w)
    sc.eq(cs_header(w), "Consumes for tank, level 60", "roles: enchant tips off: still the role picked")
    w.slash("/gl enchants auto")
    w.settle(0.1)
    sc.eq(cs_header(w), "Consumes for melee, level 60", "roles: /gl enchants auto: the talents' role")
    # A level up while it is up: the lists follow.
    en_player(w, "WARRIOR", (31, 5, 0), "forever", 59)
    w.M.fire("PLAYER_LEVEL_UP", 59)
    w.settle(0.1)
    sc.eq(cs_header(w), "Consumes for melee, level 59", "roles: a new level while it is up")
    sc.eq(cs_sections(w), cs_expect(w, "melee", "WARRIOR", 59), "roles: level 59's lists")
    sc.clean(w, "roles")


def sc_consumes_all(sc, ref, items):
    """All shows every usable item of each section (best first), scrolled in at most 16 lines;
    the wheel scrolls; Best (All again) goes back."""
    _, prices = cs_data(ref)
    w = cs_world(ref, items)
    M, ns = w.M, w.ns
    S, C = ns.settings, ns.Consumes
    F = cs_frame(w)
    cs_open(w)
    best = cs_sections(w)
    rows0 = [r[5] for r in cs_cells(w)[1]]
    sc.check(not F.IsMouseWheelEnabled(F) and not any(r.IsMouseWheelEnabled(r) for r in rows0),
             "all: the best 4 do not scroll: the wheel left to the camera")
    M.click(F.allButton)
    sc.eq((S.consumesAll, C.Model().all), (True, True), "all: on, remembered")
    sc.check(F.IsMouseWheelEnabled(F) and all(r[5].IsMouseWheelEnabled(r[5]) for r in cs_cells(w)[1]),
             "all: it scrolls: the wheel scrolls it")
    want = cs_expect(w, "melee", "WARRIOR", 60, all_=True)
    model = [(s.title, [int(s.ids[i]) for i in range(1, len(s.ids) + 1)]) for s in
             [C.Model().sections[k] for k in range(1, len(C.Model().sections) + 1)]]
    sc.eq(model, want, "all: every usable item of each section")
    sc.check(sum(len(ids) for _, ids in want) > sum(len(ids) for _, ids in best), "all: more than the best 4")
    sc.check(all(ids[:1] == b[:1] for (_, ids), (_, b) in zip(want, best)), "all: the best first")
    L = C.Layout()
    sc.check(L.lines == CS_MAX_LINES and L.total > L.lines, "all: 16 lines shown, the rest scrolls (%s/%s)" % (L.lines, L.total))
    cs_place_ok(sc, w, "all")
    sc.check(F.scrollBar.IsVisible(F.scrollBar), "all: a scroll bar")
    top = cs_sections(w)
    cs_rows_ok(sc, w, prices, 60, "all")
    M.fireScript(F, "OnMouseWheel", -1)
    after = cs_sections(w)
    sc.check(after != top, "all: the wheel scrolls down")
    cs_place_ok(sc, w, "all: scrolled")
    for _ in range(100):
        M.fireScript(F, "OnMouseWheel", -1)
    _, rows = cs_cells(w)
    cells = C.Layout().cells
    end = max((cells[i] for i in range(1, len(cells) + 1)), key=lambda c: c.line)
    sc.check(end.id is not None and any(r[0] == end.id for r in rows), "all: scrolls to the last line")
    row = rows[0][5]
    for _ in range(100):
        M.fireScript(row, "OnMouseWheel", 1)
    sc.eq(cs_sections(w), top, "all: the wheel over a row scrolls back to the top")
    M.click(F.allButton)
    sc.eq((S.consumesAll, C.Model().all), (None, False), "all: off again")
    sc.eq(cs_sections(w), best, "all: the best 4 again")
    cs_rows_ok(sc, w, prices, 60, "all: off again")
    sc.eq(sum(1 for r in cs_cells(w)[1]), sum(len(ids) for _, ids in best), "all: no spare row left up")
    sc.check(not F.scrollBar.IsVisible(F.scrollBar), "all: no scroll bar")
    sc.check(not F.IsMouseWheelEnabled(F), "all: off again: the wheel back to the camera")
    sc.clean(w, "all")
    # Low levels: All shows only what the level and class can use (a level 25 priest: no mage scroll).
    for cls, pts, lvl, role in (("PRIEST", (31, 20, 0), 25, "healer"), ("MAGE", (0, 0, 20), 25, "caster"),
                                ("WARRIOR", (20, 0, 0), 22, "melee")):
        w = cs_world(ref, items, cls=cls, points=pts, level=lvl, saved={"consumesAll": True})
        cs_open(w)
        C = w.ns.Consumes
        model = [(s.title, [int(s.ids[i]) for i in range(1, len(s.ids) + 1)]) for s in
                 [C.Model().sections[k] for k in range(1, len(C.Model().sections) + 1)]]
        sc.eq(model, cs_expect(w, role, cls, lvl, all_=True), "all: %s %d: every usable one" % (cls, lvl))
        it = cs_source_items()
        sc.eq([i for _, ids in model for i in ids if it[i][3] > lvl or (it[i][9] and cls not in it[i][9])], [],
              "all: %s %d: nothing above the level or for another class" % (cls, lvl))
        for _ in range(60):
            cs_rows_ok(sc, w, prices, lvl, "all: %s %d (scrolled)" % (cls, lvl), cls=cls)
            if C.Layout().lines >= C.Layout().total:
                break
            M2 = w.M
            M2.fireScript(cs_frame(w), "OnMouseWheel", -1)
        sc.clean(w, "all: %s %d" % (cls, lvl))


def sc_consumes_slash(sc, ref, items):
    """/gl consumes off: never shows; on: back; alone: switches; /gl help says it in one line.
    Saved off stays off; no character frame: nothing, no error; one made later: the list then."""
    w = cs_world(ref, items)
    M, g, ns = w.M, w.g, w.ns
    S = ns.settings
    F = cs_frame(w)
    cs_open(w)
    out = [strip_codes(x) for x in w.slash("/gl consumes off")]
    sc.eq(out, [CS_OFF], "slash: off says so")
    sc.check(not F.IsVisible(F) and S.consumes is False, "slash: off: gone at once, saved")
    cs_reopen(w)
    sc.check(not F.IsVisible(F), "slash: off: not when the character screen opens")
    out = [strip_codes(x) for x in w.slash("/gl consumes on")]
    sc.eq(out, [CS_ON], "slash: on says so")
    sc.check(F.IsVisible(F) and S.consumes is None, "slash: on: back at once")
    cs_place_ok(sc, w, "slash: on")
    sc.eq(cs_sections(w), cs_expect(w, "melee", "WARRIOR", 60), "slash: on: the lists")
    w.slash("/gl consumes")
    sc.check(not F.IsVisible(F) and S.consumes is False, "slash: alone: off")
    w.slash("/gl consumes")
    sc.check(F.IsVisible(F) and S.consumes is None, "slash: alone again: on")
    # Turned off by the setting itself while the screen was closed: read when it opens.
    char_close(w)
    S.consumes = False
    cs_open(w)
    sc.check(not F.IsVisible(F), "slash: the setting off: not shown when it opens")
    S.consumes = None
    F.Show(F)
    cs_reopen(w)
    sc.check(F.IsVisible(F), "slash: the setting on again")
    out = [strip_codes(x) for x in w.slash("/gl consumes sideways")]
    sc.eq(out, ["Goblin Ledger: unknown choice. Use /gl consumes on, off, best, budget or status (alone: switches it on or off)."],
          "slash: unknown")
    sc.check(F.IsVisible(F), "slash: unknown changes nothing")
    out = [strip_codes(x) for x in w.slash("/gl help")]
    sc.eq([t for t in out if "/gl consumes" in t], ["Goblin Ledger: " + CS_HELP], "slash: /gl help names it in one line")
    sc.check(sum(1 for t in out if "/gl enchants" in t) == 1, "slash: /gl help still lists /gl enchants once")
    sc.clean(w, "slash")
    # Saved off: never shows after a reload, until /gl consumes on.
    w = cs_world(ref, items, saved={"consumes": False})
    F = cs_frame(w)
    cs_open(w)
    sc.check(not F.IsVisible(F), "slash: saved off: not shown after a reload")
    w.slash("/gl consumes on")
    sc.check(F.IsVisible(F), "slash: saved off: /gl consumes on shows it")
    cs_place_ok(sc, w, "slash: saved off, then on")
    sc.clean(w, "slash saved")
    # No character frame: nothing made, commands still answer, no error; made when it comes.
    w = cs_world(ref, items, char=False)
    C = w.ns.Consumes
    sc.check(C.Frame() is None, "slash: no PaperDollFrame: no list")
    w.slash("/gl consumes off")
    w.slash("/gl consumes on")
    sc.eq(w.ns.settings.consumes, None, "slash: no PaperDollFrame: the setting still works")
    w.M.InstallCharacterFrame()
    w.M.InstallCharacterNeighbours()
    w.M.fire("ADDON_LOADED", "Blizzard_UIPanels_Game")
    F = C.Frame()
    if sc.check(F is not None and w.same(F.GetParent(F), w.g.PaperDollFrame), "slash: late: made on ADDON_LOADED"):
        cs_open(w)
        cs_place_ok(sc, w, "slash: late")
        sc.eq(cs_sections(w), cs_expect(w, "melee", "WARRIOR", 60), "slash: late: the lists")
    sc.clean(w, "slash: late")
    # The character screen open before the list is made (it comes on that OnShow): up at once.
    w = cs_world(ref, items, char=False)
    w.M.InstallCharacterFrame({"noPaperDoll": True})
    char_show(w)
    w.M.InstallPaperDoll()
    w.M.fire("PLAYER_LOGIN")
    F = w.ns.Consumes.Frame()
    if sc.check(F is not None, "slash: made while the screen is open"):
        w.M.HideFrame(w.g.PaperDollFrame)
        w.M.ShowFrame(w.g.PaperDollFrame)
        w.settle(0.3)
        sc.check(F.IsVisible(F), "slash: and shown")
    sc.clean(w, "slash: open first")
    # The source: plain ASCII with CRLF line ends, after Enchants.lua in both TOC files.
    raw = open(os.path.join(ADDON, "Consumes.lua"), "rb").read()
    sc.check(all(b < 128 for b in raw), "slash: Consumes.lua is plain ASCII")
    sc.check(raw.count(b"\r\n") == raw.count(b"\n") or raw.count(b"\r") == 0,
             "slash: Consumes.lua line ends all alike")
    for toc in ("GoblinLedger.toc", "GoblinLedger_Forever.toc"):
        lines = [l.strip() for l in open(os.path.join(ADDON, toc), "rb").read().decode("ascii").splitlines() if l.strip()]
        at = lines.index("Enchants.lua") if "Enchants.lua" in lines else -2
        sc.eq(lines[at:at + 2], ["Enchants.lua", "Consumes.lua"], "slash: %s loads Consumes.lua after Enchants.lua" % toc)


def sc_consumes_picks(sc, ref, items):
    """What the lists pick, checked by name against the game's data (not by the addon's own rule):
    a level low in its band still gets its usable food; mana potions for paladins and shamans, none
    for a warrior who picked a caster role; the mage's familiar scrolls and a school's elixir only
    for the classes that use them; Discolored healing potions (75% of the heal comes back as a poison
    or disease) never ahead of a clean one; tanks get armor; one stone and one oil of each kind;
    a 2 min elixir not over a 1 hr one; +5% XP food first while levelling; no Darkmoon Faire or
    Season of Discovery vendor prices."""
    it = cs_source_items()

    def row(i):   # a missing item reads as "missing" (each check then fails by itself)
        return it.get(i) or ("missing", None, "", 0, 1, "missing", 0, -1, "", None)
    # The data: Darkmoon Faire only vendors are no vendor (Scroll of Agility IV is 88s on the AH,
    # the Faire sells it for 6s 50c one week a month); Season of Discovery's quartermaster potions out.
    for iid in (10309, 10310, 10308, 10307, 10306, 4425, 4426, 4419, 4422, 4424, 1477, 2289, 13443):
        sc.eq(row(iid)[7], 0, "picks: %s has no vendor price (Darkmoon Faire only)" % row(iid)[0])
    sc.eq(row(3928)[7], 1000, "picks: Superior Healing Potion keeps its vendor price")
    sc.check(223913 not in it and 223914 not in it, "picks: no Season of Discovery quartermaster potions")
    sc.eq((row(12218)[0], row(12218)[6]), ("Monster Omelet", 5), "picks: Monster Omelet is Well Fed food with +5% XP")
    sc.eq((row(286152)[5], row(286152)[6]), ("+150 armor", 5), "picks: Plated Armorfish: +150 armor, +5% XP")
    sc.check("+500 armor" in row(250329)[5], "picks: Elixir of the Phalanx says its armor (%s)" % row(250329)[5])
    sc.check("+9 hp5" in row(250336)[5], "picks: Wicked Regeneration says its health (%s)" % row(250336)[5])
    for iid in (13445, 8951, 3389, 5997, 13455, 4623, 10305, 4421, 1478, 3013, 20746, 20747):
        sc.check(iid in it, "picks: %d is in the list (%s)" % (iid, it.get(iid, ("missing",))[0]))
    for iid in (247239, 247240, 247241, 247242, 241650):
        sc.check(row(iid)[5].endswith("75% back as DoT"), "picks: %s says the heal comes back (%s)" % (row(iid)[0], row(iid)[5]))
    sc.eq(sorted(i for i in it if it[i][9] == {"MAGE"} and it[i][2] == "scroll"), [275069, 277483, 277493],
          "picks: the familiar scrolls are for mages")
    sc.eq([(row(i)[0], sorted(row(i)[9] or [])) for i in (9264, 6373, 250343, 21546)],
          [("Elixir of Shadow Power", ["PRIEST", "WARLOCK"]), ("Elixir of Fire Power", ["MAGE", "WARLOCK"]),
           ("Elixir of Nature Power", ["DRUID", "SHAMAN"]), ("Elixir of Holy Power", ["PALADIN", "PRIEST"])],
          "picks: school elixirs for the classes with that school")
    shown = {}
    for iid, r_ in it.items():
        shown.setdefault((r_[2], r_[1] or r_[0]), []).append(iid)
    sc.eq([k for k, v in shown.items() if len(v) > 1], [], "picks: no two items of a section show the same name")
    w = cs_world(ref, items)

    def look(cls, pts, lvl, pick=None):
        en_player(w, cls, pts, "forever", lvl)
        if pick:
            w.slash("/gl enchants " + pick)
        cs_reopen(w)
        return dict(cs_sections(w))
    # A level low in its band: the food it can eat (not just the one of the band's top ones).
    secs = look("WARRIOR", (20, 0, 0), 20)
    sc.eq(cs_names(w, "FOOD"), ["Longjaw Mud Snapper", "Succulent Pork Ribs", "Crocolisk Gumbo"],
          "picks: a level 20 warrior's food")
    secs = look("PRIEST", (31, 20, 0), 20)
    sc.check(len(secs.get("FOOD", [])) == 4, "picks: a level 20 healer: 4 foods (%s)" % cs_names(w, "FOOD"))
    # Mana potions: paladins and shamans in every role, never a warrior or a rogue (even as a caster).
    for cls, pts, lvl in (("PALADIN", (0, 0, 31), 60), ("PALADIN", (0, 31, 0), 60), ("SHAMAN", (0, 31, 5), 60),
                          ("PALADIN", (0, 0, 31), 25), ("SHAMAN", (0, 31, 5), 30)):
        secs = look(cls, pts, lvl)
        mana = [it[i][0] for i in secs.get("POTIONS", []) if cs_mana_only(i)]
        sc.check(len(mana) == 1, "picks: %s %s level %d: a mana potion (%s)" % (cls, pts, lvl, cs_names(w, "POTIONS")))
    for cls, pts in (("WARRIOR", (31, 5, 0)), ("ROGUE", (5, 31, 15))):
        secs = look(cls, pts, 60, "caster")
        sc.eq(cs_header(w), "Consumes for caster, level 60", "picks: a %s picked caster" % cls)
        sc.eq([it[i][0] for i in secs.get("POTIONS", []) if cs_mana_only(i)], [], "picks: a %s as a caster: no mana potion" % cls)
        w.slash("/gl enchants auto")
    # Class: the familiar scrolls only for mages, a school's elixir only for its classes.
    secs = look("PRIEST", (31, 20, 0), 30)
    sc.check(not any(it[i][9] == {"MAGE"} for i in secs.get("SCROLLS", [])), "picks: a level 30 healer priest: no mage scroll")
    sc.check(any(it[i][0] == "Scroll of Intellect II" for i in secs.get("SCROLLS", [])),
             "picks: a level 30 healer priest: Scroll of Intellect II (%s)" % cs_names(w, "SCROLLS"))
    secs = look("MAGE", (0, 0, 20), 25)
    sc.check("Scroll of Cat Familiar" in cs_names(w, "SCROLLS"), "picks: a level 25 mage: the cat familiar")
    secs = look("MAGE", (0, 31, 20), 60)
    sc.check("Elixir of Shadow Power" not in cs_names(w, "ELIXIRS"), "picks: a mage: no Shadow Power (%s)" % cs_names(w, "ELIXIRS"))
    secs = look("WARLOCK", (31, 0, 0), 60)
    sc.check("Elixir of Shadow Power" in cs_names(w, "ELIXIRS"), "picks: a warlock: Shadow Power (%s)" % cs_names(w, "ELIXIRS"))
    # Healing potions: a Discolored one never first while a clean one is there.
    for cls, pts, lvl in (("WARRIOR", (31, 5, 0), 12), ("WARRIOR", (31, 5, 0), 25), ("WARRIOR", (25, 5, 0), 35),
                          ("ROGUE", (5, 31, 15), 45), ("PRIEST", (31, 20, 0), 55), ("WARRIOR", (31, 5, 0), 60)):
        look(cls, pts, lvl)
        heal = [n for n in cs_names(w, "POTIONS") if "Healing" in n or "Rejuvenation" in n]
        sc.check(heal and "Discolored" not in heal[0], "picks: %s level %d: a clean healing potion first (%s)" % (cls, lvl, heal))
    look("WARRIOR", (25, 5, 0), 35)
    sc.eq([n for n in cs_names(w, "POTIONS") if "Healing" in n], ["Superior Healing Potion"],
          "picks: a level 35 warrior's healing potion")
    # Tanks: armor (elixir, scroll; the stoneshield potion in All).
    look("WARRIOR", (0, 5, 31), 60)
    sc.check({"Elixir of the Phalanx", "Elixir of Greater Defense"} <= set(cs_names(w, "ELIXIRS")),
             "picks: a tank's armor elixirs (%s)" % cs_names(w, "ELIXIRS"))
    sc.check("Scroll of Protection IV" in cs_names(w, "SCROLLS"), "picks: a tank's armor scroll (%s)" % cs_names(w, "SCROLLS"))
    C = w.ns.Consumes
    w.ns.settings.consumesAll = True
    C.Refresh()
    allpot = [it[i][0] for s_ in [C.Model().sections[k] for k in range(1, len(C.Model().sections) + 1)] if s_.title == "POTIONS"
              for i in [int(s_.ids[j]) for j in range(1, len(s_.ids) + 1)]]
    sc.check("Greater Stoneshield Potion" in allpot, "picks: a tank's All: Greater Stoneshield Potion")
    # Rage potions in All for a druid (bear form), never for a rogue.
    for cls, pts, want in (("DRUID", (0, 31, 0), True), ("ROGUE", (5, 31, 15), False)):
        en_player(w, cls, pts, "forever", 60)
        C.Refresh()
        pots = [int(s_.ids[j]) for s_ in [C.Model().sections[k] for k in range(1, len(C.Model().sections) + 1)]
                if s_.title == "POTIONS" for j in range(1, len(s_.ids) + 1)]
        sc.eq(any(" rage" in it[i][5] for i in pots), want, "picks: a %s's All: rage potions %s" % (cls, "in" if want else "out"))
    w.ns.settings.consumesAll = None
    # Stones and oils: one of each kind, the best one.
    look("WARRIOR", (31, 5, 0), 60)
    sc.eq(sorted(cs_names(w, "STONES AND OILS")), ["Dense Sharpening Stone", "Dense Weightstone"], "picks: melee: one stone of each kind")
    look("MAGE", (0, 31, 20), 60)
    sc.eq(cs_names(w, "STONES AND OILS"), ["Wizard Oil", "Lesser Mana Oil"], "picks: a mage: one oil of each kind")
    look("MAGE", (0, 31, 20), 35)
    sc.check("Lesser Wizard Oil" in cs_names(w, "STONES AND OILS"), "picks: a level 35 mage: Lesser Wizard Oil (%s)"
             % cs_names(w, "STONES AND OILS"))
    look("PRIEST", (31, 20, 0), 45)
    sc.check("Lesser Mana Oil" in cs_names(w, "STONES AND OILS"), "picks: a level 45 healer: Lesser Mana Oil (%s)"
             % cs_names(w, "STONES AND OILS"))
    # A 1 hr elixir over a 2 min one of the same stat.
    look("WARRIOR", (5, 0, 0), 10)
    el = cs_names(w, "ELIXIRS")
    sc.check("Elixir of Minor Strength" in el and "Elixir of Giant Growth" not in el, "picks: a level 10 warrior: the 1 hr elixir (%s)" % el)
    # Levelling: +5% XP food before any food without it.
    for cls, pts, lvl in (("WARRIOR", (0, 5, 31), 15), ("PRIEST", (31, 20, 0), 16), ("WARRIOR", (0, 5, 31), 45),
                          ("MAGE", (0, 0, 20), 25)):
        secs = look(cls, pts, lvl)
        xp = [it[i][6] > 0 for i in secs.get("FOOD", [])]
        sc.check(xp and xp[0] and xp == sorted(xp, reverse=True), "picks: %s level %d: +5%% XP food first (%s)"
                 % (cls, lvl, cs_names(w, "FOOD")))
    look("WARRIOR", (0, 5, 31), 52)
    sc.check("Plated Armorfish" in [it[i][0] for i in cs_expect(w, "tank", "WARRIOR", 52, all_=True)[0][1]],
             "picks: Plated Armorfish in a tank's food")
    sc.clean(w, "picks")


# --- consumes: Best / Budget and the % of best ---
# Best shows the strongest; Budget, for each Best pick, one for less gold: the pick itself when it is
# cheap (10c a level at most), else the best value of the cheaper ones that do the same job and are
# better value, at least half as strong (a dear pick, over 25c a level: else a third); none: the pick,
# unless it is dear (then the row goes). Never PvP-only, random or unpriced; below 60, when no food
# shown gives +5% XP, the cheapest that does. Each row's grey number is its strength in % of the
# strongest usable one of its kind.
CS_MODE_TIP = "Best: the strongest. Budget: good value for less gold. Click to switch."
CS_BUDGET_SAY = ("Goblin Ledger: the consumes list shows Budget picks: good value for less gold. "
                 "/gl consumes best for the strongest.")
CS_BEST_SAY = ("Goblin Ledger: the consumes list shows the Best ones: the strongest. "
               "/gl consumes budget for good value for less gold.")
CS_STATUS_BEST = "Best: the strongest (/gl consumes budget for good value for less gold)"
CS_STATUS_BUDGET = "Budget: good value for less gold (/gl consumes best for the strongest)"
CS_FLOORS, CS_CHEAP, CS_DEAR, CS_NOXP = (1 / 2, 1 / 3), 10, 25, 0.25
CS_PCT_GAP = 4   # the grey number's gap to the words and to the price
_CS_SCORES = {}


def cs_lua_list(t):
    return [t[i] for i in range(1, len(t) + 1)] if t is not None else []


def cs_scores(w, role, lst):
    """{id: strength} for a role's list, in the order of ALL (from the data in Consumes.lua)."""
    key = (ADDON, role, lst)
    if key not in _CS_SCORES:
        D = w.ns.Consumes.DATA
        a = D.all[role][lst] if D.all[role] is not None else None
        s = D.scores[role][lst] if D.scores[role] is not None else None
        _CS_SCORES[key] = dict(zip([int(x) for x in cs_lua_list(a)], [float(x) for x in cs_lua_list(s)]))
    return _CS_SCORES[key]


def cs_ok_list(lst, cls):
    if lst == "potion-rage":
        return cls in ("WARRIOR", "DRUID")
    if lst == "potion-mana":
        return cls not in ("WARRIOR", "ROGUE")
    return True


def cs_can(iid, level, cls):
    it = cs_source_items()[iid]
    return it[3] <= level and (it[9] is None or cls in it[9])


def cs_pvp(w, iid):
    return bool(w.ns.Consumes.DATA.pvp[iid])


def cs_kind(w, lst, iid):
    """What one is measured against: its list; a stone or oil: those for the same weapons; a
    protection potion: those of its kind; a utility potion: itself."""
    it = cs_source_items()[iid]
    if lst == "potion-utility":
        return lst + ":" + it[8]
    if lst == "potion-protection":
        return lst + ":" + (w.ns.Consumes.DATA.kind[iid] or "")
    if lst == "weapon":
        return lst + ":" + it[8].split(":")[1]
    return lst


def cs_strength(w, role, lst, iid, level):
    s = cs_scores(w, role, lst).get(iid)
    if s is not None and lst == "food" and level < 60 and cs_source_items()[iid][6] <= 0:
        s *= CS_NOXP
    return s


def cs_cost(prices, iid):
    """What one costs for the Budget picks: a vendor's price when it is the cheaper, else today's AH
    value in the price data (never a live listing); None: no price."""
    vend = cs_source_items()[iid][7]
    ah = prices.get(iid, 0)
    if vend > 0 and (ah <= 0 or vend <= ah):
        return vend
    return ah if ah > 0 else None


def cs_lists(w, role, key):
    D = w.ns.Consumes.DATA
    for k, _, lists in CS_SECTIONS:
        if k == key:
            return lists if lists is not None else [D.potions[role][i] for i in range(1, len(D.potions[role]) + 1)]
    return []


def cs_band(level):
    return 5 if level >= 60 else 4 if level >= 50 else 3 if level >= 40 else 2 if level >= 20 else 1


def cs_rank_order(w, role, lst, level):
    D = w.ns.Consumes.DATA
    b = D.best[role][lst] if D.best[role] is not None else None
    first = [int(x) for x in cs_lua_list(b[cs_band(level)])] if b is not None and b[cs_band(level)] is not None else []
    return first + list(cs_scores(w, role, lst))


def cs_refs(w, role, cls, level, lists):
    """kind -> (strength, id) of the strongest usable one (the first of equals; no PvP-only one)."""
    ref = {}
    for lst in lists:
        if not cs_ok_list(lst, cls):
            continue
        for iid in cs_scores(w, role, lst):
            if cs_can(iid, level, cls) and not cs_pvp(w, iid):
                s, k = cs_strength(w, role, lst, iid, level), cs_kind(w, lst, iid)
                if k not in ref or s > ref[k][0]:
                    ref[k] = (s, iid)
    return ref


def cs_turns(per, lists, level, cls):
    """The next one of each list in turn, a group once, 4 at most: [(id, list)]."""
    it = cs_source_items()
    out, groups, pos, more = [], set(), [0] * len(per), True
    while len(out) < 4 and more:
        more = False
        for k, lids in enumerate(per):
            while pos[k] < len(lids):
                i = lids[pos[k]]
                pos[k] += 1
                if cs_can(i, level, cls) and it[i][8] not in groups:
                    groups.add(it[i][8])
                    out.append((i, lists[k]))
                    more = True
                    break
            if len(out) >= 4:
                break
    return out


def cs_peer(w, lst, iid):
    """Who can stand in for a Best pick: food, elixirs, scrolls, flasks, stones and oils of its group;
    a protection potion of its school; other potions of its list."""
    if lst == "potion-protection":
        return cs_kind(w, lst, iid)
    if lst.startswith("potion-"):
        return lst
    return lst + ":" + cs_source_items()[iid][8]


def cs_chancy(lst, iid):
    """A potion with a random amount from next to nothing ("heals 1-1499")."""
    m = re.search(r"(\d+)-(\d+)", cs_source_items()[iid][5]) if lst.startswith("potion-") else None
    return bool(m) and int(m.group(1)) * 3 < int(m.group(2))


def cs_minutes(iid):
    b = cs_source_items()[iid][5]
    m = re.search(r"(\d+) hr", b)
    if m:
        return int(m.group(1)) * 60
    m = re.search(r"(\d+) min", b)
    return int(m.group(1)) if m else None


def cs_value(lst, iid, s, c):
    """Strength per copper; an elixir, flask or scroll lasting over 30 minutes priced for 30 of them."""
    m = cs_minutes(iid) if lst in ("elixir", "flask", "scroll") else None
    if m and m > 30:
        c = c * 30 / m
    return s / c


def cs_stand_in(w, role, lst, b, level, cls, seen, prices):
    it = cs_source_items()
    cb, sb = cs_cost(prices, b), cs_strength(w, role, lst, b, level) or 0
    own = not cs_pvp(w, b) and not cs_chancy(lst, b)
    if own and cb and cb <= level * CS_CHEAP:
        return b
    dear = not own or not cb or cb > level * CS_DEAR
    vb = cs_value(lst, b, sb, cb) if own and cb else 0
    peer = cs_peer(w, lst, b)
    for f in (CS_FLOORS if dear else CS_FLOORS[:1]):
        top = None
        for iid in cs_scores(w, role, lst):
            if (iid == b or not cs_can(iid, level, cls) or cs_pvp(w, iid) or it[iid][8] in seen or cs_chancy(lst, iid)
                    or cs_peer(w, lst, iid) != peer):
                continue
            c, s = cs_cost(prices, iid), cs_strength(w, role, lst, iid, level)
            if c and s is not None and (not cb or c < cb) and s >= f * sb - 1e-9:
                v = cs_value(lst, iid, s, c)
                if v > vb and (top is None or v > top[1] or (v == top[1] and (s > top[2] or (s == top[2] and c < top[3])))):
                    top = (iid, v, s, c)
        if top:
            return top[0]
    return None if dear else b


def cs_budget(w, role, key, lists, level, cls, prices):
    """The Budget rows [(id, list, the Best pick it stands in for (None: the XP food))]."""
    it = cs_source_items()
    per = [cs_rank_order(w, role, lst, level) if cs_ok_list(lst, cls) else [] for lst in lists]
    out, seen = [], set()
    for b, lst in cs_turns(per, lists, level, cls):
        iid = cs_stand_in(w, role, lst, b, level, cls, seen, prices)
        if iid is not None and it[iid][8] not in seen:
            seen.add(it[iid][8])
            out.append((iid, lst, b))
    if key == "food" and level < 60 and not any(it[r[0]][6] > 0 for r in out):
        cheap = None
        for iid in cs_scores(w, role, "food"):
            if it[iid][6] > 0 and cs_can(iid, level, cls) and not cs_pvp(w, iid) and it[iid][8] not in seen:
                c, s = cs_cost(prices, iid), cs_strength(w, role, "food", iid, level) or 0
                if c and (cheap is None or c < cheap[1] or (c == cheap[1] and s > cheap[2])):
                    cheap = (iid, c, s)
        if cheap:
            out = out[:3] + [(cheap[0], "food", None)]
    return out


def cs_pct_of(w, role, level, ref, iid, lst):
    r, s = ref.get(cs_kind(w, lst, iid)), cs_strength(w, role, lst, iid, level)
    if r is None or s is None or r[0] <= 0:
        return (iid, lst, None, None)
    p = 100 if s >= r[0] - 1e-9 else max(1, min(99, int(math.floor(s * 100 / r[0] + 1e-9))))
    return (iid, lst, p, r[1])


def cs_picks(w, role, cls, level, budget=False, all_=False, prices=None):
    """[(title, [(id, list, %, strongest id)])]: what the list should show, worked out here from the
    data in Consumes.lua (the scores, the research's ranking) and the prices: Best, Budget or All
    (with Budget: the Budget picks first, then cheapest first, no price last)."""
    prices = prices or {}
    out = []
    for key, title, _ in CS_SECTIONS:
        lists = cs_lists(w, role, key)
        ref = cs_refs(w, role, cls, level, lists)
        if all_:
            lead = [(r[0], r[1]) for r in cs_budget(w, role, key, lists, level, cls, prices)] if budget else []
            rows, seen = list(lead), set(r[0] for r in lead)
            for lst in lists:
                if cs_ok_list(lst, cls):
                    for iid in cs_scores(w, role, lst):
                        if cs_can(iid, level, cls) and iid not in seen:
                            seen.add(iid)
                            rows.append((iid, lst))
            if budget:
                rest = rows[len(lead):]
                cost = [cs_cost(prices, iid) for iid, _ in rest]
                order = sorted(range(len(rest)), key=lambda k: (cost[k] is None, cost[k] or 0, k))
                rows = lead + [rest[k] for k in order]
        elif budget:
            rows = [(r[0], r[1]) for r in cs_budget(w, role, key, lists, level, cls, prices)]
        else:
            per = [cs_rank_order(w, role, lst, level) if cs_ok_list(lst, cls) else [] for lst in lists]
            rows = cs_turns(per, lists, level, cls)
        if rows:
            out.append((title, [cs_pct_of(w, role, level, ref, iid, lst) for iid, lst in rows]))
    return out


def cs_ids(picks):
    return [(t, [r[0] for r in rows]) for t, rows in picks]


def cs_model(w):
    """The model's sections: [(title, [(id, list, %, strongest id)])]."""
    m = w.ns.Consumes.Model()
    out = []
    for k in range(1, len(m.sections) + 1):
        s = m.sections[k]
        n = len(s.ids)
        out.append((s.title, [(int(s.ids[i]), s.lists[i], None if s.pct[i] is None else int(s.pct[i]),
                               None if s.ref[i] is None else int(s.ref[i])) for i in range(1, n + 1)]))
    return out


def cs_pct_word(p):
    return "" if p is None else ("best" if p >= 100 else "%d%%" % p)


def cs_pcts(w):
    """{name: the grey number} of the rows shown."""
    it = cs_source_items()
    return {it[r[0]][0]: r[5].pct.GetText(r[5].pct) for r in cs_cells(w)[1]}


def cs_rgb(fs):
    c = fs._textColor
    return tuple(round(c[i], 3) for i in (1, 2, 3)) if c is not None else None


def cs_live(w, prices):
    """ns.LivePrice as the live prices give it: while the auction house is open, these ids at these
    prices (copper, the cheapest listing), the rest none; with it closed, none."""
    w.M.lp = w.to_lua({int(k): v for k, v in prices.items()})
    w.lua.eval("function(ns) ns.LivePrice = function(id) if not ns.AH_IsOpen() then return nil end "
               "return MOCK.lp[id] end end")(w.ns)


def cs_set_prices(w, px):
    """Today's AH values in the price data as the addon reads them (ns.GetItem): these ids at these
    prices (0: not listed), the rest as they are. None: back as they were."""
    if px is None:
        w.lua.eval("function(ns) if MOCK.getItem0 then ns.GetItem = MOCK.getItem0; MOCK.getItem0 = nil end end")(w.ns)
        return
    w.M.px = w.to_lua({int(k): v for k, v in px.items()})
    w.lua.eval("""function(ns)
      MOCK.getItem0 = MOCK.getItem0 or ns.GetItem
      local orig = MOCK.getItem0
      ns.GetItem = function(id, ...)
        local p = MOCK.px[id]
        if p == nil then return orig(id, ...) end
        if p <= 0 then return nil end
        local g, t = orig(id, ...), {}
        if type(g) == "table" then for k, v in pairs(g) do t[k] = v end end
        t.market, t.cheapest = p, p
        return t
      end
    end""")(w.ns)


def cs_picks_ok(sc, w, role, cls, level, label, budget=False, all_=False, prices=None):
    """The model and the rows shown: the picks, each row's grey number and what it is measured against."""
    want = cs_picks(w, role, cls, level, budget=budget, all_=all_, prices=prices)
    got = cs_model(w)
    sc.eq(cs_ids(got), cs_ids(want), "%s: the picks" % label)
    sc.eq(got, want, "%s: each row's list, %% and strongest one" % label)
    pct = {r[0]: cs_pct_word(r[2]) for _, rows in want for r in rows}
    shown = [(r[0], r[5].pct.GetText(r[5].pct)) for r in cs_cells(w)[1]]
    sc.eq([s for s in shown if pct.get(s[0]) != s[1]], [], "%s: every row's grey number" % label)
    sc.check(all(cs_rgb(r[5].pct) == CS_COLOURS["muted"] for r in cs_cells(w)[1]), "%s: the numbers in grey" % label)
    return want


def cs_head_ok(sc, w, label):
    """Best / Budget in the header strip, left of All and apart from it, clear of the title's words and
    the arrow, its word inside it, as tall as All."""
    F = cs_frame(w)
    mb, al = F.modeButton, F.allButton
    es = F.GetEffectiveScale(F)
    fr, mr, ar = w.rect(F), w.rect(mb), w.rect(al)
    if not sc.check(mb.IsVisible(mb) and mr is not None and ar is not None, "%s: the switch is up" % label):
        return
    tr, rr = w.rect(F.title), w.rect(F.arrow)
    sc.check(fr[0] - 0.01 <= mr[0] and mr[2] <= fr[2] + 0.01 and mr[3] <= fr[3] + 0.01
             and mr[1] >= fr[3] - CS_HEAD_H * es - 0.01, "%s: the switch in the header (%s, list %s)" % (label, mr, fr))
    sc.check(not _overlap(mr, ar) and mr[2] <= ar[0] - 3 * es + 0.01, "%s: left of All, apart (%s, %s)" % (label, mr, ar))
    right = tr[0] + F.title.GetStringWidth(F.title) * es
    sc.check(right + 4 * es <= mr[0] + 0.01, "%s: clear of the title's words (%s, switch at %s)" % (label, right, mr[0]))
    sc.check(rr[2] <= tr[0] + 0.01 and rr[2] < mr[0], "%s: clear of the arrow" % label)
    tw = mb.text.GetStringWidth(mb.text) * es
    sc.check(tw <= mr[2] - mr[0] - 4 * es + 0.01, "%s: its word fits (%s in %s)" % (label, tw, mr[2] - mr[0]))
    sc.check(abs((mr[3] - mr[1]) - (ar[3] - ar[1])) < 0.01 and abs(mr[3] - ar[3]) < 0.01, "%s: in line with All" % label)


def cs_pct_place_ok(sc, w, label):
    """Every row: the grey number between the words and the price, inside the row, a gap each side;
    the words give way (cut short) before the number or the price would."""
    bad = []
    F = cs_frame(w)
    es = F.GetEffectiveScale(F)
    for iid, key, left, right, rect, row in cs_cells(w)[1]:
        pr, rr, tr, ir = w.rect(row.pct), w.rect(row.right), w.rect(row.text), w.rect(row.icon)
        if pr is None or rr is None or tr is None:
            bad.append((iid, "no place"))
            continue
        if not (rect[0] - 0.01 <= ir[2] + 4 * es <= pr[0] + 0.01 and pr[2] <= rr[0] - CS_PCT_GAP * es + 0.01
                and rr[2] <= rect[2] + 0.01):
            bad.append((iid, "out of the row or over the price", pr, rr, rect))
        if abs(tr[2] - (pr[0] - CS_PCT_GAP * es)) > 0.01 or abs(tr[0] - (ir[2] + 4 * es)) > 0.01:
            bad.append((iid, "the words not between the icon and the number", tr, pr))
        if _overlap(pr, rr) or _overlap(pr, tr):
            bad.append((iid, "the number covers the price or the words"))
        if abs((pr[1] + pr[3]) / 2 - (rect[1] + rect[3]) / 2) > 0.01:
            bad.append((iid, "not in the row's middle"))
        if abs((pr[2] - pr[0]) - row.pct.GetStringWidth(row.pct) * es) > 0.01:
            bad.append((iid, "the number cut short"))
    sc.eq(bad, [], "%s: every row's number in its place" % label)


def sc_consumes_budget(sc, ref, items):
    """Best / Budget in the header: Best at first (grey); a click: Budget (gold), saved, the Budget picks
    at once; again: Best. Hover: what the two are. With All: cheapest first. Folded: no switch.
    /gl consumes budget, best and status; saved after a reload."""
    _, prices = cs_data(ref)
    w = cs_world(ref, items)
    M, g, ns = w.M, w.g, w.ns
    S, C = ns.settings, ns.Consumes
    F = cs_frame(w)
    cs_open(w)
    mb = F.modeButton
    if not sc.check(mb is not None and mb.IsVisible(mb), "budget: the switch is up in the header"):
        sc.clean(w)
        return
    sc.eq((mb.text.GetText(mb.text), cs_rgb(mb.text), S.consumesBudget), ("Best", CS_COLOURS["muted"], None),
          "budget: Best at first, grey, nothing saved")
    hl = F.header.GetFrameLevel(F.header)
    sc.check(mb.GetFrameLevel(mb) > hl and F.allButton.GetFrameLevel(F.allButton) > hl,
             "budget: the switch and All above the header (a click on them is theirs, not the fold's)")
    best = cs_sections(w)
    sc.eq(best, cs_expect(w, "melee", "WARRIOR", 60), "budget: Best: the best 4 as before")
    cs_picks_ok(sc, w, "melee", "WARRIOR", 60, "budget: Best")
    tt = g.GameTooltip
    M.enter(mb)
    sc.check(tt.IsShown(tt) and w.same(tt.GetOwner(tt), mb), "budget: hover: a tooltip on the switch")
    sc.eq([l for l, _ in w.all_lines(tt)], [CS_MODE_TIP], "budget: hover: what Best and Budget are")
    M.leave(mb)
    sc.check(not tt.IsShown(tt), "budget: hover: gone with the mouse")
    M.click(mb)
    sc.eq((S.consumesBudget, C.Model().budget, mb.text.GetText(mb.text), cs_rgb(mb.text)),
          (True, True, "Budget", CS_COLOURS["buy"]), "budget: a click: Budget (gold), saved")
    want = cs_picks_ok(sc, w, "melee", "WARRIOR", 60, "budget", budget=True, prices=prices)
    sc.eq(cs_sections(w), cs_ids(want), "budget: the Budget picks shown at once")
    sc.check(cs_sections(w) != best, "budget: not the same as Best")
    sc.eq(C.Layout().n, 4, "budget: room for 4 a section")
    cs_rows_ok(sc, w, prices, 60, "budget")
    cs_place_ok(sc, w, "budget")
    cs_head_ok(sc, w, "budget")
    cs_reopen(w)
    sc.eq(cs_sections(w), cs_ids(want), "budget: still Budget when it opens again")
    M.click(mb)
    sc.eq((S.consumesBudget, C.Model().budget, mb.text.GetText(mb.text), cs_rgb(mb.text)),
          (None, False, "Best", CS_COLOURS["muted"]), "budget: a second click: Best again")
    sc.eq(cs_sections(w), best, "budget: the best 4 again")
    # All with Budget: the Budget picks first, then every other usable one cheapest first (no price
    # last); with Best: strongest first.
    M.click(F.allButton)
    M.click(mb)
    sc.eq((S.consumesAll, S.consumesBudget), (True, True), "budget: All and Budget both on")
    M.enter(F.allButton)
    sc.eq([l for l, _ in w.all_lines(tt)], ["Show the 4 Budget picks"], "budget: All's hover says what it goes back to")
    M.leave(F.allButton)
    allb = cs_picks_ok(sc, w, "melee", "WARRIOR", 60, "budget: All", budget=True, all_=True, prices=prices)
    lead = dict(cs_ids(want))
    for title, rows in allb:
        first = lead.get(title, [])
        sc.eq([r[0] for r in rows[:len(first)]], first, "budget: All: %s: the Budget picks first" % title)
        cost = [cs_cost(prices, r[0]) for r in rows[len(first):]]
        priced = [c for c in cost if c is not None]
        sc.check(priced == sorted(priced) and cost[:len(priced)] == priced,
                 "budget: All: %s: then the rest cheapest first, no price last" % title)
    sc.eq({t: sorted(ids) for t, ids in cs_ids(allb)},
          {t: sorted(ids) for t, ids in cs_expect(w, "melee", "WARRIOR", 60, all_=True)}, "budget: All: every usable one, as with Best")
    cs_rows_ok(sc, w, prices, 60, "budget: All")
    cs_place_ok(sc, w, "budget: All")
    cs_head_ok(sc, w, "budget: All")
    M.click(mb)
    sc.eq(cs_ids(cs_model(w)), cs_expect(w, "melee", "WARRIOR", 60, all_=True), "budget: All with Best: strongest first")
    # Scrolled down, then switched (a click, or /gl consumes): the list from its top again.
    for how in ("click", "slash"):
        M.fireScript(F, "OnMouseWheel", -1)
        M.fireScript(F, "OnMouseWheel", -1)
        titles = cs_cells(w)[0]
        sc.check(not titles or titles[0][0] != "FOOD", "budget: All scrolled down (%s)" % how)
        if how == "click":
            M.click(mb)
        else:
            w.slash("/gl consumes best")
        titles = cs_cells(w)[0]
        sc.check(titles and titles[0][0] == "FOOD" and C.Layout().total > C.Layout().lines,
                 "budget: switched (%s): the list from its top (%s)" % (how, [t[0] for t in titles[:2]]))
    M.click(F.allButton)
    # Folded: the header only, no switch; open again: back.
    M.click(F.header)
    sc.check(not mb.IsVisible(mb) and not F.allButton.IsVisible(F.allButton), "budget: folded: no switches")
    M.click(F.header)
    sc.check(mb.IsVisible(mb), "budget: open again: the switch is back")
    # /gl consumes budget, best, status.
    out = [strip_codes(x) for x in w.slash("/gl consumes budget")]
    sc.eq(out, [CS_BUDGET_SAY], "budget: /gl consumes budget says so")
    sc.eq((S.consumesBudget, mb.text.GetText(mb.text), cs_sections(w)), (True, "Budget", cs_ids(want)),
          "budget: /gl consumes budget: saved, shown at once")
    out = [strip_codes(x) for x in w.slash("/gl consumes status")]
    sc.eq(out, ["Goblin Ledger: the consumes list is on. %s." % CS_STATUS_BUDGET], "budget: status says Budget")
    out = [strip_codes(x) for x in w.slash("/gl consumes best")]
    sc.eq(out, [CS_BEST_SAY], "budget: /gl consumes best says so")
    sc.eq((S.consumesBudget, mb.text.GetText(mb.text), cs_sections(w)), (None, "Best", best), "budget: /gl consumes best: back at once")
    out = [strip_codes(x) for x in w.slash("/gl consumes status")]
    sc.eq(out, ["Goblin Ledger: the consumes list is on. %s." % CS_STATUS_BEST], "budget: status says Best")
    w.slash("/gl consumes off")
    out = [strip_codes(x) for x in w.slash("/gl consumes status")]
    sc.eq(out, ["Goblin Ledger: the consumes list is off. %s." % CS_STATUS_BEST], "budget: status while off")
    # Switched while it is off: it says so.
    out = [strip_codes(x) for x in w.slash("/gl consumes budget")]
    sc.eq(out, [CS_BUDGET_SAY + " It is off: /gl consumes on brings it back."], "budget: /gl consumes budget while off says it is off")
    out = [strip_codes(x) for x in w.slash("/gl consumes best")]
    sc.eq(out, [CS_BEST_SAY + " It is off: /gl consumes on brings it back."], "budget: /gl consumes best while off says it is off")
    w.slash("/gl consumes on")
    # Switched while the character screen is closed: Budget when it opens.
    char_close(w)
    w.slash("/gl consumes budget")
    cs_open(w)
    sc.eq((mb.text.GetText(mb.text), cs_sections(w)), ("Budget", cs_ids(want)), "budget: switched while closed: Budget when it opens")
    sc.clean(w, "budget")
    # Saved: Budget after a reload.
    w = cs_world(ref, items, saved={"consumesBudget": True})
    cs_open(w)
    F = cs_frame(w)
    sc.eq((F.modeButton.text.GetText(F.modeButton.text), w.ns.Consumes.Model().budget), ("Budget", True), "budget: Budget after a reload")
    sc.eq(cs_sections(w), cs_ids(want), "budget: after a reload: the Budget picks")
    sc.clean(w, "budget: saved")


def sc_consumes_budget_place(sc, ref, items):
    """Best / Budget never covers the title, All or the arrow: 631 and 398 wide, the game's look and
    ElvUI's, ElvUI's 0.62 scale, the longest header, both words."""
    def both(w, label):
        F = cs_frame(w)
        for _ in range(2):
            cs_head_ok(sc, w, "%s (%s)" % (label, F.modeButton.text.GetText(F.modeButton.text)))
            cs_pct_place_ok(sc, w, "%s (%s)" % (label, F.modeButton.text.GetText(F.modeButton.text)))
            cs_place_ok(sc, w, "%s (%s)" % (label, F.modeButton.text.GetText(F.modeButton.text)))
            w.M.click(F.modeButton)

    def fold(w, wide):
        cf = w.g.CharacterFrame
        cf.SetWidth(cf, wide)
        pane = w.g.CharacterFrameRightPaneHost
        (pane.Show if wide > 400 else pane.Hide)(pane)
        w.settle(0.3)
    # The longest header ("Consumes for agility, level 60"), at 631 and 398.
    w = cs_world(ref, items, cls="ROGUE", points=(5, 31, 15))
    cs_open(w)
    sc.eq(cs_header(w), "Consumes for agility, level 60", "place2: the longest header")
    both(w, "place2: 631")
    fold(w, 398)
    sc.eq(round(cs_frame(w).GetWidth(cs_frame(w)), 3), 398, "place2: folded to 398")
    both(w, "place2: 398")
    fold(w, 631)
    sc.clean(w, "place2")
    # ElvUI's look, its enchant labels, 631 and 398.
    w = cs_elv_world(ref, items)
    w.M.ElvUIEnchantLabels(w.to_lua(["Encha: Fiery Blaze", "Encha: Crusader", ""]))
    cs_open(w)
    sc.eq(w.ns.Consumes.look, "elvui", "place2: ElvUI's look")
    both(w, "place2: elvui 631")
    fold(w, 398)
    both(w, "place2: elvui 398")
    sc.clean(w, "place2: elvui")
    # ElvUI at 0.62 (a 768 high window): all of it in that scale.

    def setup(w_):
        w_.M.InstallBlizzardBags()
        w_.M.InstallElvUIAddon(w_.to_lua({}))
    w = cs_world(ref, items, cls="ROGUE", points=(5, 31, 15), screen=(1395, 768, 0.62), before=setup)
    w.M.ElvUICharacterLayout()
    cs_open(w)
    sc.check(abs(cs_frame(w).GetEffectiveScale(cs_frame(w)) - 0.62) < 1e-6, "place2: 0.62 scale")
    both(w, "place2: elvui 0.62")
    fold(w, 398)
    both(w, "place2: elvui 0.62 398")
    sc.clean(w, "place2: elvui 0.62")
    # Bag counts and vendor prices make the price long: at 398 the number still fits by it.
    w = cs_world(ref, items, level=35)
    cs_open(w)
    fold(w, 398)
    k = 0
    for r in cs_cells(w)[1]:
        w.put_bag(k // 16, k % 16 + 1, r[0], 200)
        k += 1
    w.M.fire("BAG_UPDATE_DELAYED")
    w.settle(0.1)
    sc.check(all(strip_codes(r[3]).startswith("x200 ") for r in cs_cells(w)[1]), "place2: 398: every row x200")
    both(w, "place2: 398 with bag counts")
    sc.clean(w, "place2: counts")


def sc_consumes_percent(sc, ref, items):
    """Each row's grey % of the strongest usable one of its kind for the role and level: "best" on the
    strongest (two as strong: both), then 62% ...; the same in Best, Budget and All; a section of one:
    best; below 60 a food without the +5% XP counts a quarter; the tooltip says it in words."""
    _, prices = cs_data(ref)
    # The player's list (a level 47 warrior, the screenshot), by name.
    w = cs_world(ref, items, level=47)
    cs_open(w)
    sc.eq(cs_pcts(w), {
        "Poached Sunscale Salmon": "best", "Smoked Desert Dumplings": "best", "Grilled Squid": "62%", "Flank au Poivre": "50%",
        "Major Healing Potion": "best", "Superior Frenzy Potion": "best", "Mighty Rage Potion": "best",
        "Limited Invulnerability Potion": "best", "Elixir of the Mongoose": "best", "Elixir of Brute Force": "57%",
        "Winterfall Firewater": "31%", "Scroll of Strength III": "best", "Scroll of Agility III": "50%",
        "Dense Weightstone": "best", "Dense Sharpening Stone": "best"},
        "percent: a level 47 warrior's list (+40 AP = +20 Str = best; +1% crit 62%; +20 Agi 50%; Mongoose 75, Brute Force 43, "
        "Firewater 35 AP for 20 of 30 min 23)")
    cs_picks_ok(sc, w, "melee", "WARRIOR", 47, "percent: 47 Best")
    cs_pct_place_ok(sc, w, "percent: 47")
    # The tooltip says it in words.
    tt = w.g.GameTooltip
    rows = {cs_source_items()[r[0]][0]: r[5] for r in cs_cells(w)[1]}
    for name, line in (("Grilled Squid", "62% as strong as Poached Sunscale Salmon for a level 47 melee"),
                       ("Poached Sunscale Salmon", "Best: the strongest for a level 47 melee"),
                       ("Smoked Desert Dumplings", "Best: the strongest for a level 47 melee"),
                       ("Winterfall Firewater", "31% as strong as Elixir of the Mongoose for a level 47 melee"),
                       ("Scroll of Agility III", "50% as strong as Scroll of Strength III for a level 47 melee")):
        w.M.enter(rows[name])
        lines = [l or "" for l, _ in w.all_lines(tt)]
        sc.check(lines and lines[-1] == line and lines.count(line) == 1 and name in lines[0],
                 "percent: %s's tooltip says it, once (%s)" % (name, lines[-2:]))
        # The game builds the tooltip again (item data arriving, a modifier key): still there, once; the
        # post calls again without a clear: no second copy.
        tt.RefreshData(tt)
        lines = [l or "" for l, _ in w.all_lines(tt)]
        sc.check(lines and lines[-1] == line and lines.count(line) == 1 and name in lines[0],
                 "percent: %s's tooltip built again: the line still there, once (%s)" % (name, lines[-2:]))
        for fn_i in range(1, len(w.M.postCalls[0]) + 1):
            w.M.postCalls[0][fn_i](tt, tt.processingInfo.tooltipData)
        sc.eq([l or "" for l, _ in w.all_lines(tt)].count(line), 1, "percent: %s: a second post call adds no copy" % name)
        w.M.leave(rows[name])
    # Another item's tooltip (not a row's) never gets the line.
    tt.SetOwner(tt, w.g.UIParent, "ANCHOR_NONE")
    tt.SetItemByID(tt, 13928)
    sc.check(not any("as strong as" in (l or "") or (l or "").startswith("Best: the strongest") for l, _ in w.all_lines(tt)),
             "percent: an item's tooltip elsewhere has no such line")
    tt.Hide(tt)
    # The words have room at 631 (two columns), at the player's prices: on the screenshot's food no row loses
    # more than 8px (in the mock a space is as wide as a letter), Smoked Desert Dumplings shows +5% XP whole.
    cs_set_prices(w, cs_px_all(CS_SHOT_PX))
    cs_reopen(w)
    sc.eq(round(cs_frame(w).GetWidth(cs_frame(w))), 631, "percent: 631 wide")
    cut = {}
    for r in cs_cells(w)[1]:
        if r[1] == "food":
            tr = w.rect(r[5].text)
            cut[cs_source_items()[r[0]][0]] = r[5].text.GetStringWidth(r[5].text) - (tr[2] - tr[0])
    sc.check(len(cut) == 4 and max(cut.values()) <= 8 and cut["Smoked Desert Dumplings"] <= 0,
             "percent: 631: the food rows' words fit, or nearly (%s)" % cut)
    cs_set_prices(w, None)
    cs_reopen(w)
    w.M.click(cs_frame(w).modeButton)
    want = cs_picks_ok(sc, w, "melee", "WARRIOR", 47, "percent: 47 Budget", budget=True, prices=prices)
    sc.check(any(r[2] is not None and r[2] < 100 for _, rs in want for r in rs), "percent: Budget shows weaker ones too")
    for r in cs_cells(w)[1]:
        p = r[5].pct.GetText(r[5].pct)
        if p.endswith("%"):
            w.M.enter(r[5])
            ln = [l or "" for l, _ in w.all_lines(tt)][-1]
            refname = cs_source_items()[dict((x[0], x[3]) for _, xs in want for x in xs)[r[0]]][0]
            sc.eq(ln, "%s as strong as %s for a level 47 melee" % (p, refname), "percent: Budget: %s's tooltip" % cs_source_items()[r[0]][0])
            w.M.leave(r[5])
            break
    cs_pct_place_ok(sc, w, "percent: 47 Budget")
    sc.clean(w, "percent: 47")
    # Many players, both picks and All: the numbers agree with the strength data.
    w = cs_world(ref, items)
    for cls, pts, lvl, role in (("WARRIOR", (31, 5, 0), 60, "melee"), ("MAGE", (0, 31, 20), 60, "caster"),
                                ("WARRIOR", (0, 5, 31), 45, "tank"), ("PRIEST", (31, 20, 0), 52, "healer"),
                                ("HUNTER", (31, 20, 0), 60, "hunter"), ("ROGUE", (5, 31, 15), 30, "agility"),
                                ("WARRIOR", (0, 0, 0), 12, "melee"), ("DRUID", (0, 31, 0), 60, "agility")):
        en_player(w, cls, pts, "forever", lvl)
        for budget, all_ in ((False, False), (True, False), (False, True), (True, True)):
            w.ns.settings.consumesBudget = budget or None
            w.ns.settings.consumesAll = all_ or None
            cs_reopen(w)
            label = "percent: %s %d %s%s" % (cls, lvl, "Budget" if budget else "Best", " All" if all_ else "")
            got = cs_picks_ok(sc, w, role, cls, lvl, label, budget=budget, all_=all_, prices=prices)
            sc.check(all(r[2] is not None for _, rs in got for r in rs), label + ": every row has its number")
            if not all_ and not budget:
                firsts = [rs[0] for t, rs in got if t != "POTIONS"]
                sc.check(all(r[2] == 100 for r in firsts), label + ": the first of each section is the best (%s)" % firsts)
                ups = [(t, [r[2] for r in rs]) for t, rs in got if t in ("FOOD", "ELIXIRS", "SCROLLS", "FLASKS")
                       and any(rs[k][2] < rs[k + 1][2] for k in range(len(rs) - 1))]
                sc.eq(ups, [], label + ": the numbers never rise down a section")
        w.ns.settings.consumesBudget = None
        w.ns.settings.consumesAll = None
    # Levelling casters (15-24): a food without the +5% XP (Goblin Deviled Clams) never above an XP one by its number.
    for cls, pts in (("MAGE", (0, 31, 20)), ("WARLOCK", (31, 0, 0))):
        for lvl in range(15, 25):
            en_player(w, cls, pts, "forever", lvl)
            cs_reopen(w)
            food = [r[2] for r in dict(cs_model(w)).get("FOOD", [])]
            sc.check(all(food[k] >= food[k + 1] for k in range(len(food) - 1)),
                     "percent: %s %d: the food numbers never rise down the list (%s)" % (cls, lvl, food))
    # A section of one: a hunter's flask.
    en_player(w, "HUNTER", (31, 20, 0), "forever", 60)
    cs_reopen(w)
    sc.eq(dict(cs_sections(w)).get("FLASKS"), [13511], "percent: a hunter's one flask")
    sc.eq(cs_pcts(w).get("Flask of Distilled Wisdom"), "best", "percent: a section of one: best")
    # Two as strong: both best (Dense Weightstone and Dense Sharpening Stone, +8 weapon damage).
    en_player(w, "WARRIOR", (31, 5, 0), "forever", 60)
    cs_reopen(w)
    p = cs_pcts(w)
    sc.eq((p.get("Dense Weightstone"), p.get("Dense Sharpening Stone")), ("best", "best"), "percent: two as strong: both best")
    # Below 60 a food without the +5% XP counts a quarter: Clamlette Surprise (+12 Sta, +12 Spi = 30 for a
    # tank) next to Savory Turtle Stew (+20 Sta = 50): 15% at 45, 60% at 60.
    w.ns.settings.consumesAll = True
    for lvl, want_p in ((45, 15), (60, 60)):
        en_player(w, "WARRIOR", (0, 5, 31), "forever", lvl)
        cs_reopen(w)
        food = dict(cs_model(w)).get("FOOD", [])
        row = [r for r in food if r[0] == 16971]
        sc.eq([(r[2], r[3]) for r in row], [(want_p, 250068)], "percent: tank %d: Clamlette Surprise (no XP) %d%% of Savory Turtle Stew" % (lvl, want_p))
    w.ns.settings.consumesAll = None
    sc.clean(w, "percent")
    # The data: the strengths are the role weights times the buff (spot checks by name), and ALL is
    # strongest first (food: the +5% XP ones first).
    D = w.ns.Consumes.DATA
    for role, lst, iid, v in (("melee", "food", 13932, 40), ("melee", "food", 20452, 40), ("melee", "food", 13928, 25),
                              ("melee", "food", 250069, 20), ("melee", "elixir", 13452, 75), ("melee", "elixir", 13453, 43.2),
                              ("melee", "elixir", 12820, 23.33), ("melee", "potion-heal", 13446, 1400),
                              ("melee", "potion-rage", 13442, 720), ("caster", "food", 13933, 28), ("tank", "food", 250068, 50),
                              ("caster", "potion-heal", 18253, 2080), ("melee", "weapon", 12643, 40)):
        sc.eq(cs_scores(w, role, lst).get(iid), v, "percent: the data: %s %s %s" % (role, cs_source_items()[iid][0], lst))
    unsorted = []
    for role in ("melee", "agility", "tank", "caster", "healer", "hunter"):
        for lst in ("food", "potion-heal", "potion-mana", "potion-rage", "potion-buff", "potion-protection", "potion-utility",
                    "elixir", "flask", "scroll", "weapon"):
            sco = cs_scores(w, role, lst)
            key = [((0 if cs_source_items()[i][6] > 0 or lst != "food" else 1), -s) for i, s in sco.items()]
            if key != sorted(key):
                unsorted.append((role, lst))
    sc.eq(unsorted, [], "percent: the data: each list strongest first")
    sc.eq(sorted(int(k) for k in D.pvp.keys()), [17348, 17349, 17351, 17352, 18839, 18841], "percent: the data: the PvP-only potions")
    for iid in (17348, 17349, 17351, 17352):
        sc.check(cs_source_items()[iid][5].endswith("battlegrounds only"), "percent: %s says battlegrounds only" % cs_source_items()[iid][0])


def cs_px_all(px):
    """Made-up AH values for every consumable: these, the rest not listed (vendor prices still count)."""
    out = {iid: 0 for iid in cs_source_items()}
    out.update(px)
    return out


# The level 47 warrior's list (the screenshot) and what can stand in for it, about as on the player's AH;
# Elixir of Ogre Strength (1 hr) made dearer than Elixir of Strength (30 min), Wildvine Potion 1c.
CS_SHOT_PX = {
    13932: 323, 8364: 96, 20452: 2500, 274976: 230, 250070: 1655, 13928: 419, 250069: 2098, 12212: 423, 4592: 13,
    13446: 2700, 3928: 785, 1710: 448, 9144: 1, 250942: 5999, 250940: 965, 250941: 6299, 13442: 12495, 5633: 239,
    5631: 68, 3387: 6499, 5634: 1192, 2459: 1257,
    13452: 7890, 9187: 3277, 8949: 1263, 13453: 13854, 3391: 1500, 250349: 1000, 12820: 4940, 246948: 0,
    4426: 1089, 2289: 268, 4425: 995, 1477: 699, 3012: 239,
    12643: 542, 7965: 273, 12404: 486, 7964: 266}


def cs_patch_items(w, changes):
    """Items' fields changed in the addon's data and the test's copy of it: {id: {Lua index: value}}
    (7: % XP, 8: vendor copper); returns what puts the test's copy back."""
    items = cs_source_items()
    old = dict(items)
    D = w.ns.Consumes.DATA["items"]
    for iid, ch in changes.items():
        t = list(items[iid])
        for k, v in ch.items():
            t[k - 1] = v
            D[iid][k] = v
        items[iid] = tuple(t)

    def undo():
        items.clear()
        items.update(old)
    return undo


def cs_xp_only(w, keep):
    """Every food's +5% XP taken away but these; returns what puts the test's copy back."""
    return cs_patch_items(w, {iid: {7: 0} for iid, t in cs_source_items().items()
                              if t[2] == "food" and t[6] > 0 and iid not in keep})


def sc_consumes_budget_rule(sc, ref, items):
    """Budget by name, with made-up AH values in the price data: for each Best pick, a cheap one (10c a
    level at most) stays; a dearer one gives way to the best value of the cheaper ones that do the same
    job and are better value, at least half as strong (a dear one, over 25c a level: else a third); a
    dear one with nothing like it goes; an hour's elixir priced for 30 minutes; never a random,
    PvP-only or unpriced one, a protection potion of another school or a cheaper one that is worse
    value; the auction house's live listings never move the picks; below 60 the cheapest +5% XP food
    when no food shown gives it; the level, class and potion rules hold."""
    _, prices = cs_data(ref)
    it = cs_source_items()
    w = cs_world(ref, items, level=47, saved={"consumesBudget": True})
    C = w.ns.Consumes
    px = cs_px_all(CS_SHOT_PX)
    cs_set_prices(w, px)
    cs_reopen(w)

    def names():
        return {t: [it[i][0] for i in ids] for t, ids in cs_sections(w)}
    got = names()
    sc.eq(got.get("FOOD"), ["Poached Sunscale Salmon", "Plain Ol' Paletusk", "Grilled Squid", "Jungle Stew"],
          "rule: 47 food: the cheap ones stay (Salmon 3s 23c, Squid 4s 19c, though Mithril Head Trout is better value), "
          "+10 Str for Smoked Desert Dumplings, +15 Agi for Flank au Poivre")
    sc.eq(got.get("POTIONS"), ["Superior Healing Potion", "Frenzy Potion", "Great Rage Potion", "Free Action Potion"],
          "rule: 47 potions: the best value at least half as strong; never the 1c Wildvine Potion (random) or a "
          "battleground or PvP hall potion; Free Action for Limited Invulnerability")
    sc.eq(got.get("ELIXIRS"), ["Elixir of Greater Agility", "Elixir of Ogre Strength"],
          "rule: 47 elixirs: a third as strong when none is half (Greater Agility for Mongoose); the hour's Ogre Strength "
          "at 15s over the 30 min Elixir of Strength at 10s; Winterfall Firewater (dear, nothing like it priced) goes")
    sc.eq(got.get("SCROLLS"), ["Scroll of Strength II", "Scroll of Agility III"],
          "rule: 47 scrolls: Strength II for III; Agility III (9s 95c) stays: Agility II is cheaper but worse value")
    sc.eq(got.get("STONES AND OILS"), ["Solid Weightstone", "Solid Sharpening Stone"], "rule: 47 stones: Solid for Dense")
    want = cs_picks_ok(sc, w, "melee", "WARRIOR", 47, "rule: 47", budget=True, prices=px)
    pct = cs_pcts(w)
    sc.eq((pct.get("Elixir of Greater Agility"), pct.get("Plain Ol' Paletusk"), pct.get("Free Action Potion")),
          ("33%", "50%", "best"), "rule: 47: the grey numbers (Free Action: nothing does what it does)")
    sc.check(sum(len(ids) for _, ids in cs_sections(w)) < sum(len(ids) for _, ids in cs_ids(cs_picks(w, "melee", "WARRIOR", 47))),
             "rule: 47: fewer rows than Best")
    # Each row the Best pick itself or a cheaper one for it.
    for key, title, _ in CS_SECTIONS:
        for iid, lst, b in cs_budget(w, "melee", key, cs_lists(w, "melee", key), 47, "WARRIOR", px):
            sc.check(b is None or iid == b or cs_cost(px, iid) < (cs_cost(px, b) or 10 ** 12),
                     "rule: 47: %s is %s or cheaper" % (it[iid][0], it[b][0] if b else "the XP food"))
    # The Salmon dearer than 4s 70c: Mithril Head Trout (better value, half as strong); the Mighty Rage's
    # Great Rage gone: Rage Potion (a third as strong) for the dear one.
    for sal in (1000, 2000):
        cs_set_prices(w, {**px, 13932: sal, 5633: 0})
        cs_reopen(w)
        got = names()
        sc.check(got.get("FOOD", [])[:1] == ["Mithril Head Trout"],
                 "rule: Salmon at %s: Mithril Head Trout instead (%s)" % (short_money(sal), got.get("FOOD")))
        sc.check("Rage Potion" in got.get("POTIONS", []), "rule: no Great Rage: Rage Potion, a third as strong (%s)" % got.get("POTIONS"))
        cs_picks_ok(sc, w, "melee", "WARRIOR", 47, "rule: Salmon at %d" % sal, budget=True, prices={**px, 13932: sal, 5633: 0})
    # A cheaper one that is worse value never: Lesser Agility (13s 6c) for a level 20 has only Minor Agility
    # (half as strong, 12s 21c): the row goes (it is dear for a level 20).
    en_player(w, "WARRIOR", (20, 0, 0), "forever", 20)
    p20 = {**px, 3390: 1306, 2457: 1221, 3391: 440}
    cs_set_prices(w, p20)
    cs_reopen(w)
    el = dict(cs_sections(w)).get("ELIXIRS", [])
    sc.check(3390 in dict(cs_ids(cs_picks(w, "melee", "WARRIOR", 20)))["ELIXIRS"] and 2457 not in el and 3390 not in el,
             "rule: 20: not Minor Agility for Lesser Agility, and the dear Lesser Agility goes (%s)" % cs_names(w, "ELIXIRS"))
    sc.check(3391 in el, "rule: 20: Elixir of Ogre Strength (4s 40c, mid-price, the best value) stays")
    cs_picks_ok(sc, w, "melee", "WARRIOR", 20, "rule: 20", budget=True, prices=p20)
    # A food above the level is never one: Smoked Desert Dumplings (level 45) at 1c, level 20.
    cs_set_prices(w, {**p20, 20452: 1})
    cs_reopen(w)
    sc.check(all(it[i][3] <= 20 for i in dict(cs_sections(w)).get("FOOD", [])), "rule: 20: not the 1c level 45 food")
    # A protection potion: only one of its school stands in (rogue 60: Greater Arcane Protection made dear,
    # Greater Fire Protection 1c): none here, so the row goes.
    en_player(w, "ROGUE", (21, 30, 0), "forever", 60)
    pr = {**px, 13461: 5800, 13457: 1, 6049: 1}
    cs_set_prices(w, pr)
    cs_reopen(w)
    best_p = dict(cs_ids(cs_picks(w, "agility", "ROGUE", 60)))["POTIONS"]
    pots = dict(cs_sections(w)).get("POTIONS", [])
    sc.check(13461 in best_p and not any(C.DATA.kind[i] is not None for i in pots),
             "rule: rogue 60: no fire potion for the arcane one (%s)" % cs_names(w, "POTIONS"))
    cs_picks_ok(sc, w, "agility", "ROGUE", 60, "rule: rogue 60", budget=True, prices=pr)
    # A random one is never the pick, also when Best shows it: a level 40 hunter's Wildvine Potion.
    en_player(w, "HUNTER", (21, 10, 0), "forever", 40)
    cs_set_prices(w, {**px, 9144: 836})
    cs_reopen(w)
    best_p = dict(cs_ids(cs_picks(w, "hunter", "HUNTER", 40)))["POTIONS"]
    pots = dict(cs_sections(w)).get("POTIONS", [])
    sc.check(9144 in best_p and 9144 not in pots and 1710 in pots,
             "rule: hunter 40: Greater Healing Potion for the random Wildvine Potion (%s)" % cs_names(w, "POTIONS"))
    cs_picks_ok(sc, w, "hunter", "HUNTER", 40, "rule: hunter 40", budget=True, prices={**px, 9144: 836})
    sc.clean(w, "rule")
    # The auction house's live listings never move the picks: open there with every one at 1c (ns.LivePrice),
    # the same picks; the rows show the live price. A failing ns.LivePrice or ns.GetItem: no error.
    w = cs_world(ref, items, level=47, saved={"consumesBudget": True})
    cs_set_prices(w, px)
    cs_open(w)
    shut = cs_sections(w)
    cs_live(w, {iid: 1 for iid in it})
    w.open_ah_modern()
    cs_reopen(w)
    sc.eq(cs_sections(w), shut, "rule: at the auction house, every one 1c live: the same picks")
    cs_picks_ok(sc, w, "melee", "WARRIOR", 47, "rule: at the auction house", budget=True, prices=px)
    shown = [strip_codes(r[3]) for r in cs_cells(w)[1] if it[r[0]][7] == 0]
    sc.check(shown and all(s == short_money(1) for s in shown), "rule: at the auction house: the rows show the live 1c (%s)" % shown[:3])
    w.close_ah_modern()
    w.settle(0.1)
    cs_rows_ok(sc, w, px, 47, "rule: auction house closed: the price data again")
    w.lua.eval("function(ns) ns.LivePrice = function() error('no live prices') end end")(w.ns)
    w.open_ah_modern()
    cs_reopen(w)
    sc.eq(cs_sections(w), shut, "rule: a failing ns.LivePrice: the same picks")
    w.close_ah_modern()
    w.ns.LivePrice = None
    sc.clean(w, "rule: live")
    w = cs_world(ref, items, level=47, saved={"consumesBudget": True})
    w.lua.eval("function(ns) ns.GetItem = function() error('no item') end end")(w.ns)
    cs_open(w)
    cs_picks_ok(sc, w, "melee", "WARRIOR", 47, "rule: a failing ns.GetItem: as with no AH values", budget=True, prices={})
    sc.check(w.ns.Consumes.lastError is None and len(cs_cells(w)[1]) > 0, "rule: a failing ns.GetItem: rows, no error")
    w.ns.Consumes.lastError = None
    # Below 60, when no food shown gives the +5% XP, the cheapest that does is the last food (in the 4th
    # row's place when there are 4): a level 47 tank, only Longjaw Mud Snapper with XP, the Best foods cheap.
    w = cs_world(ref, items, cls="WARRIOR", points=(0, 5, 31), level=47, saved={"consumesBudget": True})
    undo = cs_xp_only(w, {4592})
    try:
        best_f = dict(cs_ids(cs_picks(w, "tank", "WARRIOR", 47)))["FOOD"]
        pf = dict(px)
        pf.update({i: 100 for i in best_f})
        cs_set_prices(w, pf)
        cs_open(w)
        food = dict(cs_sections(w)).get("FOOD", [])
        sc.check(len(best_f) == 4 and not any(it[i][8] == it[4592][8] for i in best_f), "rule: tank 47: 4 Best foods, none of +AP")
        sc.eq(food, best_f[:3] + [4592], "rule: tank 47: Longjaw Mud Snapper (the only +5% XP food) in the 4th row's place")
        cs_picks_ok(sc, w, "tank", "WARRIOR", 47, "rule: tank 47 XP food", budget=True, prices=pf)
    finally:
        undo()
    sc.clean(w, "rule: XP food")
    # With the Budget foods giving +5% XP: no extra XP food (Longjaw Mud Snapper, 13c, is not in).
    w = cs_world(ref, items, level=47, saved={"consumesBudget": True})
    cs_set_prices(w, px)
    cs_open(w)
    food = dict(cs_sections(w)).get("FOOD", [])
    sc.check(4592 not in food and all(it[i][6] > 0 for i in food), "rule: 47: every food +5%% XP, no extra XP food (%s)" % cs_names(w, "FOOD"))
    sc.clean(w, "rule: no XP food")
    # Only XP foods of a stat already shown, or above the level: no extra row (a level 30 mage, +5% XP left
    # only on Spiced Chili Crab (+Int, shown) and Grilled Squid (level 35), both 1c; the Best foods cheap).
    w = cs_world(ref, items, cls="MAGE", points=(0, 31, 20), level=30, saved={"consumesBudget": True})
    undo = cs_xp_only(w, {12216, 13928})
    try:
        best_f = dict(cs_ids(cs_picks(w, "caster", "MAGE", 30)))["FOOD"]
        pf = dict(px)
        pf.update({i: 100 for i in best_f})
        pf.update({12216: 1, 13928: 1})
        cs_set_prices(w, pf)
        cs_open(w)
        sc.check(it[12216][8] in [it[i][8] for i in best_f] and it[13928][3] > 30, "rule: mage 30: the crab's stat is shown, the squid is level 35")
        sc.eq(dict(cs_sections(w)).get("FOOD"), best_f, "rule: mage 30: no XP food of a shown stat or above the level")
        cs_picks_ok(sc, w, "caster", "MAGE", 30, "rule: mage 30 XP food", budget=True, prices=pf)
    finally:
        undo()
    sc.clean(w, "rule: XP food shown or above")
    # Never dearer than the Best pick: a level 45 mage's Combat Mana Potion (PvP hall, 11s); Superior Mana at
    # 12s is better value than Greater Mana at 10s (no vendor here), but dearer: Greater Mana.
    w = cs_world(ref, items, cls="MAGE", points=(0, 31, 20), level=45, saved={"consumesBudget": True})
    undo = cs_patch_items(w, {6149: {8: 0}})
    try:
        pm = {**px, 13443: 1200, 6149: 1000, 17747: 0}
        cs_set_prices(w, pm)
        cs_open(w)
        sc.check(18841 in dict(cs_ids(cs_picks(w, "caster", "MAGE", 45)))["POTIONS"], "rule: mage 45: Best shows Combat Mana Potion")
        pots = dict(cs_sections(w)).get("POTIONS", [])
        sc.check(6149 in pots and 13443 not in pots and 18841 not in pots,
                 "rule: mage 45: Greater Mana, not the dearer Superior Mana (%s)" % cs_names(w, "POTIONS"))
        cs_picks_ok(sc, w, "caster", "MAGE", 45, "rule: mage 45", budget=True, prices=pm)
    finally:
        undo()
    sc.clean(w, "rule: never dearer")
    # A potion already shown never stands in again: a level 8 mage, Minor Mana and Lesser Healing dear (no
    # vendor here), Minor Rejuvenation 1c stands in for the mana one; the healing one gets Minor Healing.
    w = cs_world(ref, items, cls="MAGE", points=(0, 0, 0), level=8, saved={"consumesBudget": True})
    undo = cs_patch_items(w, {2455: {8: 0}, 858: {8: 0}})
    try:
        p8 = {**px, 2455: 1000, 858: 1000, 2456: 1, 118: 10}
        cs_set_prices(w, p8)
        cs_open(w)
        bp = dict(cs_ids(cs_picks(w, "caster", "MAGE", 8)))["POTIONS"]
        sc.check(bp[:2] == [2455, 858], "rule: mage 8: Best shows Minor Mana, Lesser Healing (%s)" % [it[i][0] for i in bp])
        sc.eq(dict(cs_sections(w)).get("POTIONS", [])[:2], [2456, 118], "rule: mage 8: Minor Rejuvenation, then Minor Healing")
        cs_picks_ok(sc, w, "caster", "MAGE", 8, "rule: mage 8", budget=True, prices=p8)
    finally:
        undo()
    sc.clean(w, "rule: shown once")
    # No price data at all: vendor prices only.
    w = cs_world(ref, items, level=47, data_src=PLACEHOLDER, saved={"consumesBudget": True})
    cs_open(w)
    got = cs_picks_ok(sc, w, "melee", "WARRIOR", 47, "rule: no price data", budget=True, prices={})
    sc.check(all(it[r[0]][7] > 0 for _, rs in got for r in rs), "rule: no price data: only vendor items")
    sc.clean(w, "rule: no data", ok_chat=())
    # The level, class, list and potion rules in Budget, and the picks for many players (the test prices).
    w = cs_world(ref, items, saved={"consumesBudget": True})
    cases = [("WARRIOR", (31, 5, 0), 60, "melee"), ("WARRIOR", (0, 5, 31), 60, "tank"), ("MAGE", (0, 31, 20), 60, "caster"),
             ("ROGUE", (5, 31, 15), 60, "agility"), ("PRIEST", (31, 20, 0), 60, "healer"), ("HUNTER", (31, 20, 0), 60, "hunter"),
             ("PALADIN", (0, 31, 0), 60, "tank"), ("DRUID", (0, 31, 0), 60, "agility"), ("WARRIOR", (25, 5, 0), 35, "melee"),
             ("MAGE", (0, 0, 20), 25, "caster"), ("WARRIOR", (0, 0, 0), 12, "melee"), ("PRIEST", (0, 20, 0), 44, "healer"),
             ("ROGUE", (0, 30, 0), 52, "agility"), ("PALADIN", (0, 0, 31), 60, "melee"), ("SHAMAN", (0, 31, 5), 60, "melee"),
             ("WARRIOR", (20, 0, 0), 20, "melee"), ("WARLOCK", (31, 0, 0), 60, "caster"), ("PRIEST", (31, 20, 0), 30, "healer"),
             ("WARRIOR", (31, 5, 0), 47, "melee"), ("PALADIN", (0, 0, 31), 25, "melee"), ("DRUID", (0, 31, 0), 47, "agility"),
             ("WARLOCK", (31, 0, 0), 40, "caster"), ("HUNTER", (31, 20, 0), 18, "hunter")]
    for cls, pts, lvl, role in cases:
        en_player(w, cls, pts, "forever", lvl)
        cs_reopen(w)
        label = "rule: %s %s level %d" % (cls, pts, lvl)
        got = cs_picks_ok(sc, w, role, cls, lvl, label, budget=True, prices=prices)
        cs_rows_ok(sc, w, prices, lvl, label, cls=cls)
        rows = [(t, r) for t, rs in got for r in rs]
        sc.eq([r[0] for t, r in rows if not cs_can(r[0], lvl, cls)], [], label + ": nothing above the level or for another class")
        sc.eq([r[0] for t, r in rows if cs_pvp(w, r[0]) or cs_chancy(r[1], r[0])], [], label + ": nothing PvP-only or random")
        sc.eq([r[0] for t, r in rows if cs_cost(prices, r[0]) is None], [], label + ": everything has a price")
        rage = [r[0] for t, r in rows if r[1] == "potion-rage"]
        sc.check(not rage or cls in ("WARRIOR", "DRUID"), label + ": rage potions only for warriors and druids")
        mana = [r[0] for t, r in rows if t == "POTIONS" and cs_mana_only(r[0])]
        sc.check(not mana or cls not in ("WARRIOR", "ROGUE"), label + ": no mana potions for warriors and rogues")
        best = dict(cs_ids(cs_picks(w, role, cls, lvl)))
        for t, rs in got:
            groups = [it[r[0]][8] for r in rs]
            sc.check(len(groups) == len(set(groups)) and len(rs) <= min(4, len(best.get(t, [])) + (t == "FOOD")),
                     label + ": %s: a group once, no more rows than Best" % t)
        bad = []
        for key, title, _ in CS_SECTIONS:
            for iid, lst, b in cs_budget(w, role, key, cs_lists(w, role, key), lvl, cls, prices):
                if b is None or iid == b:
                    continue
                cb, sb, s = cs_cost(prices, b), cs_strength(w, role, lst, b, lvl), cs_strength(w, role, lst, iid, lvl)
                dear = cs_pvp(w, b) or cs_chancy(lst, b) or not cb or cb > lvl * CS_DEAR
                if (cb and cs_cost(prices, iid) >= cb) or s < (1 / 3 if dear else 1 / 2) * sb - 1e-9 or cs_peer(w, lst, iid) != cs_peer(w, lst, b):
                    bad.append((it[iid][0], it[b][0]))
        sc.eq(bad, [], label + ": each stand-in cheaper, of the same job, at least half as strong (a dear pick's: a third)")
        if lvl < 60 and "FOOD" in dict(got):
            food = [r[0] for r in dict(got)["FOOD"]]
            sc.check(any(it[i][6] > 0 for i in food), label + ": a +5%% XP food in (%s)" % [it[i][0] for i in food])
    sc.clean(w, "rule: players")


